insert into public.question_content_versions(source_key,version_number,question,content_hash,source_type,creator_id,source_set_id,source_title) values
('original:scientific-method:observe',1,'{"question":"What usually begins a scientific investigation?","choices":["An observation or question","A final conclusion","A proven answer","A completed graph"],"answer":0,"explanation":"Observations lead scientists to questions that they can investigate."}'::jsonb,'572ceb54218ad601e6bb8d4c27ed2334','official',NULL,NULL,'Scientific Method'),
('original:scientific-method:hypothesis',1,'{"question":"Which statement is a testable hypothesis?","choices":["Plants are the best living things.","If bean plants receive more light, then they will grow taller.","Green plants are pretty.","Everyone should grow beans."],"answer":1,"explanation":"A testable hypothesis predicts a relationship that can be checked with measurements."}'::jsonb,'2c5c3078f6aa1e9f7c0d69eaa8f7aa90','official',NULL,NULL,'Scientific Method'),
('original:scientific-method:independent',1,'{"question":"A student changes the amount of fertilizer given to plants. What is the independent variable?","choices":["Plant height","The type of pot","The fertilizer amount","The final conclusion"],"answer":2,"explanation":"The independent variable is the factor deliberately changed: fertilizer amount."}'::jsonb,'931cdb49a2692ffba9f2f33f8bfa767c','official',NULL,NULL,'Scientific Method'),
('original:scientific-method:dependent',1,'{"question":"A student measures plant height after changing fertilizer amounts. What is the dependent variable?","choices":["The fertilizer amount","The number of pots","The sunlight kept the same","Plant height"],"answer":3,"explanation":"The dependent variable is the outcome measured: plant height."}'::jsonb,'ce4ab4794643b98939bfe6ffeaec9661','official',NULL,NULL,'Scientific Method'),
('original:scientific-method:constant',1,'{"question":"Why should all test plants receive the same amount of water?","choices":["To make water the independent variable","To keep water from affecting the comparison","To guarantee taller plants","To avoid measuring anything"],"answer":1,"explanation":"Keeping water constant helps isolate the effect of the variable being tested."}'::jsonb,'4c943a3b86b8c924e70104946b4d36d3','official',NULL,NULL,'Scientific Method'),
('original:scientific-method:control',1,'{"question":"What is the main purpose of a control group?","choices":["Provide a baseline for comparison","Prove every hypothesis correct","Eliminate the need for trials","Make the experiment faster"],"answer":0,"explanation":"A control group provides a comparison without the treatment being tested."}'::jsonb,'a433debfe937dc95bb2a37e9044a5bc8','official',NULL,NULL,'Scientific Method'),
('original:scientific-method:quantitative',1,'{"question":"Which observation is quantitative data?","choices":["The liquid smells sour.","The leaf is rough.","The mass is 12 grams.","The solution is cloudy."],"answer":2,"explanation":"Quantitative data are numerical measurements, such as 12 grams."}'::jsonb,'101e79e89107e996e7dcaf6093954e02','official',NULL,NULL,'Scientific Method'),
('original:scientific-method:qualitative',1,'{"question":"Which observation is qualitative data?","choices":["The solution turned cloudy.","The temperature is 18°C.","The reaction took 4 seconds.","The volume is 22 mL."],"answer":0,"explanation":"Qualitative observations describe qualities, such as cloudiness, rather than numerical measurements."}'::jsonb,'41adbe7b9970badfdb2fd551de64cb98','official',NULL,NULL,'Scientific Method'),
('original:scientific-method:repeat',1,'{"question":"Why repeat an experiment for several trials?","choices":["To guarantee the expected answer","To improve reliability and detect variation","To avoid using a control","To change every variable"],"answer":1,"explanation":"Repeated trials reveal variation and help determine whether a result is consistent."}'::jsonb,'181c3719d0614c33f03db662f56e683c','official',NULL,NULL,'Scientific Method'),
('original:scientific-method:conclusion',1,'{"question":"What should a scientific conclusion be based on?","choices":["The result the scientist hoped for","The most popular opinion","The hypothesis alone","The evidence collected"],"answer":3,"explanation":"A conclusion should follow the evidence, even when the evidence does not support the prediction."}'::jsonb,'c1da65f92c2f6934b85dab7d37837747','official',NULL,NULL,'Scientific Method'),
('original:scientific-method:unsupported',1,'{"question":"The data do not support a hypothesis. What should the scientist do?","choices":["Hide unexpected data","Stop asking questions","Revise the explanation and test again","Change the measurements"],"answer":2,"explanation":"Unexpected results are useful evidence. Scientists reconsider their explanations and continue testing."}'::jsonb,'0d597091873d36f3236619c2296ab23c','official',NULL,NULL,'Scientific Method'),
('original:scientific-method:graph',1,'{"question":"Which graph usually best shows temperature changes over time?","choices":["An unlabeled sketch","A line graph","A diagram of a thermometer","A photograph"],"answer":1,"explanation":"A line graph makes a pattern of change over time easier to see."}'::jsonb,'00ce9a7c184f933f320aefa0048629ce','official',NULL,NULL,'Scientific Method'),
('original:scientific-method:volume',1,'{"question":"Which tool is designed to measure liquid volume?","choices":["A balance","A meter stick","A stopwatch","A graduated cylinder"],"answer":3,"explanation":"Graduated cylinders have marked units for measuring liquid volume."}'::jsonb,'6f111db0649aad6976d42c5bcbbe2817','official',NULL,NULL,'Scientific Method'),
('original:scientific-method:theory',1,'{"question":"What is a scientific theory?","choices":["An unsupported guess","A well-supported explanation of natural phenomena","One measurement","An opinion that cannot be tested"],"answer":1,"explanation":"A scientific theory explains natural phenomena and is supported by substantial evidence."}'::jsonb,'9706860d26c7c4b3ed5dbf153a15b044','official',NULL,NULL,'Scientific Method'),
('original:scientific-method:peer',1,'{"question":"What does peer review help scientists evaluate?","choices":["The popularity of a claim","The cost of the lab alone","The methods, evidence, and reasoning","Whether questions should be banned"],"answer":2,"explanation":"Other researchers examine whether the methods and evidence support the conclusions."}'::jsonb,'95bdd57e5f018ad2ac284b58bce276a0','official',NULL,NULL,'Scientific Method'),
('original:scientific-method:testable',1,'{"question":"Which question is scientifically testable?","choices":["Which flower is the prettiest?","Should everyone love flowers?","Are flowers more interesting than trees?","Does water temperature affect seed germination?"],"answer":3,"explanation":"Water temperature and seed germination can be measured in a controlled investigation."}'::jsonb,'2edc67f16d9aa87970159953d16f50ed','official',NULL,NULL,'Scientific Method'),
('original:scientific-method:error',1,'{"question":"Which practice helps reduce measurement error?","choices":["Use calibrated tools consistently","Switch units in every trial","Estimate all measurements","Record only expected results"],"answer":0,"explanation":"Calibrated tools and consistent procedures help reduce measurement error."}'::jsonb,'1032aabe1962e918922d891ec6708b28','official',NULL,NULL,'Scientific Method'),
('original:scientific-method:design',1,'{"question":"Students test paper-towel brands using different amounts of water. What is the main problem?","choices":["There is no independent variable","Water amount was not controlled","The brands are identical","There are too many measurements"],"answer":1,"explanation":"Changing water amount along with towel brand makes the comparison unfair."}'::jsonb,'0352cb599edac800a126a2e64adf01cc','official',NULL,NULL,'Scientific Method'),
('original:scientific-method:two',1,'{"question":"Why is it difficult to interpret an experiment that changes two variables at once?","choices":["No data can be collected","The sample is always too large","The cause of the outcome is unclear","The hypothesis becomes a theory"],"answer":2,"explanation":"If multiple factors change, it is difficult to identify which caused the outcome."}'::jsonb,'9872654aa26c37ede0160c472a0d2342','official',NULL,NULL,'Scientific Method'),
('original:scientific-method:light',1,'{"question":"Which design best tests how light color affects plant growth?","choices":["Use different plants and soil for every color","Ask which color looks best","Grow one plant under one color","Use the same plant species and conditions; change only light color"],"answer":3,"explanation":"Changing only light color while controlling other factors makes the effect easier to identify."}'::jsonb,'73c47fcbf39bde37a3519fb211ec5b5e','official',NULL,NULL,'Scientific Method'),
('original:scientific-method:outlier',1,'{"question":"A measurement is far from all the other results. What should happen first?","choices":["Delete it automatically","Treat it as proof","Investigate whether it reflects an error or a real effect","Replace it with the expected number"],"answer":2,"explanation":"An outlier may reveal a mistake or a meaningful effect; it should be investigated."}'::jsonb,'c1b7ca67d49810974baae153196f9a8a','official',NULL,NULL,'Scientific Method'),
('original:scientific-method:correlation',1,'{"question":"Two variables change together. What can scientists conclude from that alone?","choices":["One definitely caused the other","They are correlated; causation is not established","All the data are invalid","No further testing is needed"],"answer":1,"explanation":"A correlation describes a relationship but does not, by itself, prove cause and effect."}'::jsonb,'a377c6fe16b93f5c1ef7d313731c9f02','official',NULL,NULL,'Scientific Method'),
('original:scientific-method:reproduce',1,'{"question":"What helps another scientist reproduce an experiment?","choices":["Detailed methods and materials","Only the final answer","The scientist’s reputation","An eye-catching title"],"answer":0,"explanation":"Detailed procedures allow others to repeat the investigation and compare results."}'::jsonb,'ef597b8ab7bcbf9d514c10810e6451b8','official',NULL,NULL,'Scientific Method'),
('original:scientific-method:support',1,'{"question":"Repeated controlled trials support a hypothesis. What is the strongest appropriate conclusion?","choices":["It is absolutely proven forever","It instantly becomes a scientific law","No further studies are useful","The evidence supports it under the conditions tested"],"answer":3,"explanation":"Scientific claims reflect the strength and limits of the evidence collected."}'::jsonb,'18b3f757ca19b65577f8a5bff168be5b','official',NULL,NULL,'Scientific Method'),
('original:constitution-basics:purpose',1,'{"question":"What is the main purpose of the U.S. Constitution?","choices":["Establish the framework of the federal government","List every state law","Describe all political parties","Set prices for goods"],"answer":0,"explanation":"The Constitution establishes the federal government and its powers and limits."}'::jsonb,'9936cc18d21a3eb9923221f0723908f8','official',NULL,NULL,'U.S. Constitution Basics'),
('original:constitution-basics:branches',1,'{"question":"Which list names the three branches of the federal government?","choices":["National, state, and local","Legislative, executive, and judicial","Army, Navy, and Air Force","House, Senate, and Cabinet"],"answer":1,"explanation":"The three branches make laws, carry out laws, and interpret laws."}'::jsonb,'965544a1958ec689bb02cc85b3caca0e','official',NULL,NULL,'U.S. Constitution Basics'),
('original:constitution-basics:legislative',1,'{"question":"Which branch makes federal laws?","choices":["Executive","Judicial","Legislative","Military"],"answer":2,"explanation":"Congress, the legislative branch, makes federal laws."}'::jsonb,'fb2578c96a845f54c10983def13f3065','official',NULL,NULL,'U.S. Constitution Basics'),
('original:constitution-basics:executive',1,'{"question":"Which official heads the executive branch?","choices":["Chief justice","Speaker of the House","Senate majority leader","President"],"answer":3,"explanation":"The president heads the executive branch, which carries out federal laws."}'::jsonb,'41202b028b2f02c20574bbbba690f2d7','official',NULL,NULL,'U.S. Constitution Basics'),
('original:constitution-basics:judicial',1,'{"question":"What is a major role of the judicial branch?","choices":["Interpret laws and resolve legal disputes","Command the military","Write the federal budget alone","Appoint governors"],"answer":0,"explanation":"Federal courts interpret laws and decide cases within their jurisdiction."}'::jsonb,'33dae576a93c4ff670bce61e04161ff9','official',NULL,NULL,'U.S. Constitution Basics'),
('original:constitution-basics:congress',1,'{"question":"Which two bodies make up Congress?","choices":["Supreme Court and Cabinet","House of Representatives and Senate","President and vice president","Governors and mayors"],"answer":1,"explanation":"Congress has two chambers: the House of Representatives and the Senate."}'::jsonb,'61bf52febac6fa452630bd1f8238b371','official',NULL,NULL,'U.S. Constitution Basics'),
('original:constitution-basics:senate',1,'{"question":"How many U.S. senators does each state have?","choices":["One","A number based on population","Two","Five"],"answer":2,"explanation":"Every state has two U.S. senators."}'::jsonb,'f3e7ade5be04fb9aae9a1ce2c0e5fd90','official',NULL,NULL,'U.S. Constitution Basics'),
('original:constitution-basics:house',1,'{"question":"What mainly determines a state’s number of U.S. representatives?","choices":["Its land area","Its age","Its number of counties","Its population"],"answer":3,"explanation":"House seats are apportioned among states based on population."}'::jsonb,'7e89b6a1f4549856960f870e44962fb0','official',NULL,NULL,'U.S. Constitution Basics'),
('original:constitution-basics:separation',1,'{"question":"What does separation of powers mean?","choices":["Dividing government responsibilities among branches","Giving all power to the president","Keeping states out of government","Removing courts from government"],"answer":0,"explanation":"Separation of powers divides responsibilities among the legislative, executive, and judicial branches."}'::jsonb,'232c562e4a1cfa70770f5d2ed0b800b8','official',NULL,NULL,'U.S. Constitution Basics'),
('original:constitution-basics:checks',1,'{"question":"Which is an example of checks and balances?","choices":["A city repairs a road","The president vetoes a bill passed by Congress","A citizen reads a newspaper","A state opens a park"],"answer":1,"explanation":"A veto allows the president to check Congress’s lawmaking power."}'::jsonb,'2b4b4311fd28d9073e52307fb294a00e','official',NULL,NULL,'U.S. Constitution Basics'),
('original:constitution-basics:federalism',1,'{"question":"What is federalism?","choices":["Government by judges alone","Government without states","A division of power between national and state governments","A system with one political party"],"answer":2,"explanation":"Federalism divides governing power between national and state governments."}'::jsonb,'35adc748bcdcbdd237163c5c6ffc53f2','official',NULL,NULL,'U.S. Constitution Basics'),
('original:constitution-basics:supremacy',1,'{"question":"Under the Supremacy Clause, what happens when a valid federal law conflicts with a state law?","choices":["The state law always wins","Both laws automatically disappear","The governor makes the final decision","The federal law takes precedence"],"answer":3,"explanation":"The Constitution and valid federal laws are the supreme law of the land."}'::jsonb,'5085bf34959478e01ee1a12888e248ce','official',NULL,NULL,'U.S. Constitution Basics'),
('original:constitution-basics:amendment',1,'{"question":"What is a constitutional amendment?","choices":["A formal change or addition to the Constitution","A presidential speech","A temporary court schedule","A local election result"],"answer":0,"explanation":"An amendment formally changes or adds to the Constitution."}'::jsonb,'9737091dfa7e14413755539ad1d7fbc1','official',NULL,NULL,'U.S. Constitution Basics'),
('original:constitution-basics:bill',1,'{"question":"What is the Bill of Rights?","choices":["The president’s annual budget","The first ten amendments to the Constitution","A list of state capitals","The last ten federal laws passed"],"answer":1,"explanation":"The first ten amendments are known as the Bill of Rights."}'::jsonb,'636596a81a9b750e4f4804e8f789ae4c','official',NULL,NULL,'U.S. Constitution Basics'),
('original:constitution-basics:first',1,'{"question":"Which freedom is protected by the First Amendment?","choices":["Freedom from every tax","A guaranteed government job","Freedom of speech","A right to ignore all laws"],"answer":2,"explanation":"The First Amendment protects speech, religion, press, assembly, and petition."}'::jsonb,'014e4070f1d8d5da3f82355b989a19fe','official',NULL,NULL,'U.S. Constitution Basics'),
('original:constitution-basics:fourth',1,'{"question":"Which amendment protects against unreasonable searches and seizures?","choices":["First","Second","Third","Fourth"],"answer":3,"explanation":"The Fourth Amendment protects against unreasonable searches and seizures."}'::jsonb,'cb4cb726845fb4a95bd1416e33a02173','official',NULL,NULL,'U.S. Constitution Basics'),
('original:constitution-basics:popular',1,'{"question":"What does popular sovereignty mean?","choices":["Government authority comes from the people","Only wealthy people may vote","Courts control all elections","States cannot elect leaders"],"answer":0,"explanation":"Popular sovereignty means the people are the source of government authority."}'::jsonb,'290246a5a4492854263aa2bdf1aabc49','official',NULL,NULL,'U.S. Constitution Basics'),
('original:constitution-basics:limited',1,'{"question":"What does limited government mean?","choices":["Government has no responsibilities","Government power is restricted by law","Government has only one branch","Government may act without rules"],"answer":1,"explanation":"Limited government requires officials to operate within legal and constitutional limits."}'::jsonb,'cb2b88a0d8f8daf7060889580ac4cc1f','official',NULL,NULL,'U.S. Constitution Basics'),
('original:constitution-basics:republic',1,'{"question":"In a representative republic, how do people usually exercise political power?","choices":["By choosing a hereditary ruler","By removing all public officials","By electing representatives","By letting courts write every law"],"answer":2,"explanation":"Citizens elect representatives to make decisions on their behalf."}'::jsonb,'96395fd9532b4e800d30bd16b142dc69','official',NULL,NULL,'U.S. Constitution Basics'),
('original:constitution-basics:preamble',1,'{"question":"What is the Preamble to the Constitution?","choices":["A list of every amendment","A declaration of war","A collection of state laws","An introduction stating the Constitution’s purposes"],"answer":3,"explanation":"The Preamble introduces the Constitution and states its broad purposes."}'::jsonb,'6a9ea5bb2566c713bc168c6be8b543ff','official',NULL,NULL,'U.S. Constitution Basics'),
('original:linear-equations:add',1,'{"question":"Solve: x + 7 = 12","choices":["5","19","−5","7"],"answer":0,"explanation":"Subtract 7 from both sides: x = 5."}'::jsonb,'3492d8f23b99387a8742889d786b481b','official',NULL,NULL,'One-Variable Linear Equations'),
('original:linear-equations:subtract',1,'{"question":"Solve: x − 4 = 9","choices":["5","13","−13","36"],"answer":1,"explanation":"Add 4 to both sides: x = 13."}'::jsonb,'e871e9058892a028e39b1ee69a0c6e98','official',NULL,NULL,'One-Variable Linear Equations'),
('original:linear-equations:multiply',1,'{"question":"Solve: 3x = 18","choices":["15","21","6","54"],"answer":2,"explanation":"Divide both sides by 3: x = 6."}'::jsonb,'478fed409747abf4c1236b122d1811f3','official',NULL,NULL,'One-Variable Linear Equations'),
('original:linear-equations:divide',1,'{"question":"Solve: x ÷ 5 = 4","choices":["9","1","20 ÷ 5","20"],"answer":3,"explanation":"Multiply both sides by 5: x = 20."}'::jsonb,'189b7ef50042eb276065c56b8f18c14c','official',NULL,NULL,'One-Variable Linear Equations'),
('original:linear-equations:two-step',1,'{"question":"Solve: 2x + 3 = 11","choices":["4","7","8","−4"],"answer":0,"explanation":"Subtract 3, then divide by 2: x = 4."}'::jsonb,'2fd77504a17b5b35cfb0f8b769218811','official',NULL,NULL,'One-Variable Linear Equations'),
('original:linear-equations:two-subtract',1,'{"question":"Solve: 5x − 6 = 14","choices":["2","4","8","20"],"answer":1,"explanation":"Add 6 to get 5x = 20, then divide by 5."}'::jsonb,'e9196ad8f7b20f34463df1439f77c333','official',NULL,NULL,'One-Variable Linear Equations'),
('original:linear-equations:negative',1,'{"question":"Solve: −3x = 12","choices":["4","−9","−4","9"],"answer":2,"explanation":"Divide both sides by −3: x = −4."}'::jsonb,'f8b4790bf4190a4598961f35c1602657','official',NULL,NULL,'One-Variable Linear Equations'),
('original:linear-equations:fraction',1,'{"question":"Solve: x/4 + 2 = 5","choices":["3","7","8","12"],"answer":3,"explanation":"Subtract 2 to get x/4 = 3, then multiply by 4."}'::jsonb,'aa7d4f32e852d31e6cc464b947032fc1','official',NULL,NULL,'One-Variable Linear Equations'),
('original:linear-equations:distribution',1,'{"question":"Solve: 2(x + 3) = 14","choices":["4","10","7","−4"],"answer":0,"explanation":"Divide by 2 to get x + 3 = 7, then subtract 3."}'::jsonb,'df25f91eb0936cb0e0d299005410e6ec','official',NULL,NULL,'One-Variable Linear Equations'),
('original:linear-equations:both-sides',1,'{"question":"Solve: 3x + 2 = x + 10","choices":["2","4","6","8"],"answer":1,"explanation":"Subtract x and 2 from both sides: 2x = 8, so x = 4."}'::jsonb,'8768881f2a7320fe1e7415ce01d2c038','official',NULL,NULL,'One-Variable Linear Equations'),
('original:linear-equations:decimal',1,'{"question":"Solve: 0.5x = 6","choices":["3","6.5","12","5.5"],"answer":2,"explanation":"Divide 6 by 0.5: x = 12."}'::jsonb,'a5b487059cb03f3914aaa72d5cc00486','official',NULL,NULL,'One-Variable Linear Equations'),
('original:linear-equations:negative-add',1,'{"question":"Solve: x + 8 = 3","choices":["11","5","−11","−5"],"answer":3,"explanation":"Subtract 8 from both sides: x = −5."}'::jsonb,'96b9bb93ea493149db8cfec76ea2c4cf','official',NULL,NULL,'One-Variable Linear Equations'),
('original:linear-equations:inverse',1,'{"question":"Which operation undoes multiplication by 6?","choices":["Division by 6","Addition of 6","Subtraction of 6","Multiplication by −6"],"answer":0,"explanation":"Multiplication and division by the same nonzero number are inverse operations."}'::jsonb,'b4d706e10d8d27ae93c68aefad82fef4','official',NULL,NULL,'One-Variable Linear Equations'),
('original:linear-equations:balance',1,'{"question":"Why must an operation be applied to both sides of an equation?","choices":["To make every answer positive","To preserve equality","To remove all variables immediately","To make both sides larger"],"answer":1,"explanation":"Applying the same valid operation to both sides keeps them equal."}'::jsonb,'3286d74adea7bbb4658a29cbecb51747','official',NULL,NULL,'One-Variable Linear Equations'),
('original:linear-equations:check',1,'{"question":"Which value satisfies 4x − 1 = 11?","choices":["2","4","3","5"],"answer":2,"explanation":"Substitute 3: 4(3) − 1 = 11."}'::jsonb,'c9a638ef972380608cb3ff6c1bd0bab8','official',NULL,NULL,'One-Variable Linear Equations'),
('original:linear-equations:like-terms',1,'{"question":"Solve: 2x + 3x = 25","choices":["10","25","3","5"],"answer":3,"explanation":"Combine like terms to get 5x = 25, then divide by 5."}'::jsonb,'e9ef53c83669a83b3fcd245c64b5f4d0','official',NULL,NULL,'One-Variable Linear Equations'),
('original:linear-equations:none',1,'{"question":"How many solutions does x + 2 = x + 5 have?","choices":["No solutions","Exactly one","Exactly two","Infinitely many"],"answer":0,"explanation":"Subtracting x gives 2 = 5, which is false for every value of x."}'::jsonb,'9acd751b60b91541636cbe15d508ec9b','official',NULL,NULL,'One-Variable Linear Equations'),
('original:linear-equations:infinite',1,'{"question":"How many solutions does 2(x + 1) = 2x + 2 have?","choices":["No solutions","Infinitely many","Exactly one","Exactly two"],"answer":1,"explanation":"Both sides simplify to 2x + 2, so every real value of x satisfies the equation."}'::jsonb,'822d059922b9ae648b9ff6970f7a8cad','official',NULL,NULL,'One-Variable Linear Equations'),
('original:linear-equations:word',1,'{"question":"A notebook costs $3. You spend $15 on identical notebooks. Which equation finds the number n bought?","choices":["n + 3 = 15","15n = 3","3n = 15","n − 3 = 15"],"answer":2,"explanation":"Total cost equals price per notebook multiplied by the number bought: 3n = 15."}'::jsonb,'0e8b7c2459cdee6559fefbe0b2e3859d','official',NULL,NULL,'One-Variable Linear Equations'),
('original:linear-equations:parentheses',1,'{"question":"Solve: 3(x − 2) = 9","choices":["1","3","7","5"],"answer":3,"explanation":"Divide by 3 to get x − 2 = 3, then add 2."}'::jsonb,'05d7c80214acb594846d9b2e97b4486d','official',NULL,NULL,'One-Variable Linear Equations'),
('original:ela--literature-literary-analysis--plot-and-narrative-structure:ela--literature-literary-analysis--plot-and-narrative-structure--1',1,'{"question":"In a story, which part usually introduces the characters and situation before the main problem?","choices":["climax","resolution","exposition","falling action"],"answer":2,"explanation":""}'::jsonb,'f260bc765d0ee8dcc83193051df23ddc','official',NULL,NULL,'Plot and Narrative Structure'),
('original:ela--literature-literary-analysis--plot-and-narrative-structure:ela--literature-literary-analysis--plot-and-narrative-structure--2',1,'{"question":"A brief event disrupts the main character’s routine and starts the central problem. What is it?","choices":["inciting incident","denouement","subplot","exposition"],"answer":0,"explanation":""}'::jsonb,'ace39d7d80a6bbc8f4d24f39150cb76a','official',NULL,NULL,'Plot and Narrative Structure'),
('original:ela--literature-literary-analysis--plot-and-narrative-structure:ela--literature-literary-analysis--plot-and-narrative-structure--3',1,'{"question":"Several obstacles make the protagonist’s goal harder to reach. Which plot phase is this?","choices":["exposition","resolution","flashback","rising action"],"answer":3,"explanation":""}'::jsonb,'4f78333aa7992d1c2a0d31a87219391d','official',NULL,NULL,'Plot and Narrative Structure'),
('original:ela--literature-literary-analysis--plot-and-narrative-structure:ela--literature-literary-analysis--plot-and-narrative-structure--4',1,'{"question":"At the story’s decisive turning point, the protagonist confronts the central problem. What is this moment?","choices":["falling action","climax","exposition","frame narrative"],"answer":1,"explanation":""}'::jsonb,'39ea38c30f8ddae4ab8609705cb9445a','official',NULL,NULL,'Plot and Narrative Structure'),
('original:ela--literature-literary-analysis--plot-and-narrative-structure:ela--literature-literary-analysis--plot-and-narrative-structure--5',1,'{"question":"After the climax, the story shows consequences and moves toward an ending. Which phase is this?","choices":["inciting incident","falling action","rising action","exposition"],"answer":1,"explanation":""}'::jsonb,'8e47bd2f696c5d70b8f58fb882a8a587','official',NULL,NULL,'Plot and Narrative Structure'),
('original:ela--literature-literary-analysis--plot-and-narrative-structure:ela--literature-literary-analysis--plot-and-narrative-structure--6',1,'{"question":"Which term names the events that bring the central conflict to a close?","choices":["exposition","foreshadowing","subplot","resolution"],"answer":3,"explanation":""}'::jsonb,'c846fd1ac2a6142dbe904bc9abaec87b','official',NULL,NULL,'Plot and Narrative Structure'),
('original:ela--literature-literary-analysis--plot-and-narrative-structure:ela--literature-literary-analysis--plot-and-narrative-structure--7',1,'{"question":"A story begins with an event from years earlier, then returns to the present. Which device is used?","choices":["flashback","foreshadowing","climax","in medias res"],"answer":0,"explanation":""}'::jsonb,'2bbb9b0693b961be48226c4c7150d519','official',NULL,NULL,'Plot and Narrative Structure'),
('original:ela--literature-literary-analysis--plot-and-narrative-structure:ela--literature-literary-analysis--plot-and-narrative-structure--8',1,'{"question":"Before the archive is entered, the narrator hints that an old key fits its lock. Which device hints at a later event?","choices":["exposition","resolution","foreshadowing","pacing"],"answer":2,"explanation":""}'::jsonb,'4ba9173fbcc6c2b4258665ed1a587e48','official',NULL,NULL,'Plot and Narrative Structure'),
('original:ela--literature-literary-analysis--plot-and-narrative-structure:ela--literature-literary-analysis--plot-and-narrative-structure--9',1,'{"question":"A novel opens in the middle of a storm and explains the earlier journey afterward. What opening technique is used?","choices":["in medias res","linear chronology","denouement","frame narrative"],"answer":0,"explanation":""}'::jsonb,'6162ec1dea64845cbb5f7e959354b15d','official',NULL,NULL,'Plot and Narrative Structure'),
('original:ela--literature-literary-analysis--plot-and-narrative-structure:ela--literature-literary-analysis--plot-and-narrative-structure--10',1,'{"question":"A story about a family’s move includes a smaller conflict about a sibling’s audition. What is the smaller storyline?","choices":["climax","exposition","subplot","resolution"],"answer":2,"explanation":""}'::jsonb,'c13ca0f5551691e271ca7724e59f1465','official',NULL,NULL,'Plot and Narrative Structure'),
('original:ela--literature-literary-analysis--plot-and-narrative-structure:ela--literature-literary-analysis--plot-and-narrative-structure--11',1,'{"question":"A traveler tells a present-day listener a story that contains another character’s diary. What structure is this?","choices":["linear plot","frame narrative","rising action","cliffhanger"],"answer":1,"explanation":""}'::jsonb,'c60df3eac915b6e05ce23defbc18768b','official',NULL,NULL,'Plot and Narrative Structure'),
('original:ela--literature-literary-analysis--plot-and-narrative-structure:ela--literature-literary-analysis--plot-and-narrative-structure--12',1,'{"question":"A novel follows separate episodes in a character’s life, each with a mostly self-contained problem. Which structure fits?","choices":["single climax","frame narrative","flashback","episodic structure"],"answer":3,"explanation":""}'::jsonb,'6892ac06000e680871ab07e0996938bc','official',NULL,NULL,'Plot and Narrative Structure'),
('original:ela--literature-literary-analysis--plot-and-narrative-structure:ela--literature-literary-analysis--plot-and-narrative-structure--13',1,'{"question":"Events are presented in the order they happened, from first to last. What structure is used?","choices":["nonlinear narrative","frame narrative","in medias res","linear narrative"],"answer":3,"explanation":""}'::jsonb,'e85cf0faa45931318aff445d9347deff','official',NULL,NULL,'Plot and Narrative Structure'),
('original:ela--literature-literary-analysis--plot-and-narrative-structure:ela--literature-literary-analysis--plot-and-narrative-structure--14',1,'{"question":"A story moves between past and present scenes rather than following time order. Which structure is this?","choices":["linear narrative","nonlinear narrative","episodic structure","resolution"],"answer":1,"explanation":""}'::jsonb,'d09b3babeea3d959b83a16de8d2a1af1','official',NULL,NULL,'Plot and Narrative Structure'),
('original:ela--literature-literary-analysis--plot-and-narrative-structure:ela--literature-literary-analysis--plot-and-narrative-structure--15',1,'{"question":"The author slows down a brief moment with detailed description. Which craft choice is most directly affected?","choices":["setting","point of view","pacing","theme"],"answer":2,"explanation":""}'::jsonb,'f64819b71225e7c07a9eff526bd5c235','official',NULL,NULL,'Plot and Narrative Structure'),
('original:ela--literature-literary-analysis--plot-and-narrative-structure:ela--literature-literary-analysis--plot-and-narrative-structure--16',1,'{"question":"The final scene briefly shows how the characters live after the main conflict ends. What is this closing section often called?","choices":["denouement","inciting incident","exposition","subplot"],"answer":0,"explanation":""}'::jsonb,'486e09928ceaf0cf3440794b77745d98','official',NULL,NULL,'Plot and Narrative Structure'),
('original:ela--literature-literary-analysis--plot-and-narrative-structure:ela--literature-literary-analysis--plot-and-narrative-structure--17',1,'{"question":"A chapter ends just as a character opens a mysterious letter, leaving the result unknown. What device is this?","choices":["resolution","cliffhanger","flashback","exposition"],"answer":1,"explanation":""}'::jsonb,'566046697a48885a2b5aaa4d83810e71','official',NULL,NULL,'Plot and Narrative Structure'),
('original:ela--literature-literary-analysis--plot-and-narrative-structure:ela--literature-literary-analysis--plot-and-narrative-structure--18',1,'{"question":"Two storylines follow different characters and intersect at the climax. What best describes their relationship?","choices":["frame narrative","episodic structure","parallel plots","linear chronology"],"answer":2,"explanation":""}'::jsonb,'f997b876bb59247148ecde876b380f66','official',NULL,NULL,'Plot and Narrative Structure'),
('original:ela--literature-literary-analysis--plot-and-narrative-structure:ela--literature-literary-analysis--plot-and-narrative-structure--19',1,'{"question":"A scene shows a character packing a suitcase before readers learn why the trip matters. What function can that early detail serve?","choices":["setup","resolution","falling action","denouement"],"answer":0,"explanation":""}'::jsonb,'0df2753ecd1473ad14d0587a35232f5e','official',NULL,NULL,'Plot and Narrative Structure'),
('original:ela--literature-literary-analysis--plot-and-narrative-structure:ela--literature-literary-analysis--plot-and-narrative-structure--20',1,'{"question":"After learning a friend has left, a cautious character decides to travel alone. What plot moment is the decision most likely to mark?","choices":["exposition","subplot","frame narrative","turning point"],"answer":3,"explanation":""}'::jsonb,'c3300fd4f342f92398b05e12a20ada5a','official',NULL,NULL,'Plot and Narrative Structure'),
('original:ela--literature-literary-analysis--characterization-and-character-development:ela--literature-literary-analysis--characterization-and-character-development--1',1,'{"question":"What is characterization?","choices":["the order of story events","the time and place of a story","the ways a writer presents a character","the lesson a story suggests"],"answer":2,"explanation":""}'::jsonb,'8b88aebf090bb8d129d415233bf6ab95','official',NULL,NULL,'Characterization and Character Development'),
('original:ela--literature-literary-analysis--characterization-and-character-development:ela--literature-literary-analysis--characterization-and-character-development--2',1,'{"question":"A narrator states, “Mara was patient and observant.” Which method presents the trait directly?","choices":["direct characterization","indirect characterization","dramatic irony","setting"],"answer":0,"explanation":""}'::jsonb,'dccd52736a267bbb11eb67ffb072338a','official',NULL,NULL,'Characterization and Character Development'),
('original:ela--literature-literary-analysis--characterization-and-character-development:ela--literature-literary-analysis--characterization-and-character-development--3',1,'{"question":"Readers infer a character’s traits from choices, speech, thoughts, and effects on others. What method is this?","choices":["direct characterization","exposition","point of view","indirect characterization"],"answer":3,"explanation":""}'::jsonb,'5219a64b88c595b001799651f571b596','official',NULL,NULL,'Characterization and Character Development'),
('original:ela--literature-literary-analysis--characterization-and-character-development:ela--literature-literary-analysis--characterization-and-character-development--4',1,'{"question":"A character’s goals, values, and habits remain mostly consistent throughout the story. What is a useful description?","choices":["dynamic character","static character","foil","unreliable narrator"],"answer":1,"explanation":""}'::jsonb,'b84116da90d4505a7305f549c2088444','official',NULL,NULL,'Characterization and Character Development'),
('original:ela--literature-literary-analysis--characterization-and-character-development:ela--literature-literary-analysis--characterization-and-character-development--5',1,'{"question":"A character changes a belief after facing evidence that challenges it. What kind of character is this?","choices":["static character","dynamic character","stock character","narrator"],"answer":1,"explanation":""}'::jsonb,'2044df72c77dd5d87961ab1dd4aa3cf0','official',NULL,NULL,'Characterization and Character Development'),
('original:ela--literature-literary-analysis--characterization-and-character-development:ela--literature-literary-analysis--characterization-and-character-development--6',1,'{"question":"A character’s careful planning contrasts with a sibling’s impulsiveness, highlighting both traits. What role does the sibling serve?","choices":["antagonist","narrator","confidant","foil"],"answer":3,"explanation":""}'::jsonb,'0c9d7ae2e93574532f95609d48c11212','official',NULL,NULL,'Characterization and Character Development'),
('original:ela--literature-literary-analysis--characterization-and-character-development:ela--literature-literary-analysis--characterization-and-character-development--7',1,'{"question":"The main character pursues the central goal and faces the story’s main conflict. What role is this?","choices":["protagonist","antagonist","foil","background character"],"answer":0,"explanation":""}'::jsonb,'ac382f0b725a8441c7d8bd7ab1f1b9a2','official',NULL,NULL,'Characterization and Character Development'),
('original:ela--literature-literary-analysis--characterization-and-character-development:ela--literature-literary-analysis--characterization-and-character-development--8',1,'{"question":"A character or force blocks the protagonist’s goal. Which role does it fill?","choices":["protagonist","confidant","antagonist","narrator"],"answer":2,"explanation":""}'::jsonb,'1f192244e8c2e312c04675305b5f729e','official',NULL,NULL,'Characterization and Character Development'),
('original:ela--literature-literary-analysis--characterization-and-character-development:ela--literature-literary-analysis--characterization-and-character-development--9',1,'{"question":"A trusted friend listens as the protagonist explains a difficult choice. What role may this character serve?","choices":["confidant","antagonist","foil","protagonist"],"answer":0,"explanation":""}'::jsonb,'52e56ce2d127c3be4ad3e1d23afe4407','official',NULL,NULL,'Characterization and Character Development'),
('original:ela--literature-literary-analysis--characterization-and-character-development:ela--literature-literary-analysis--characterization-and-character-development--10',1,'{"question":"A character’s actions repeatedly show generosity even when no one is watching. Which evidence most strongly supports that trait?","choices":["the color of the character’s coat","the story’s location","repeated choices to help others","the order of chapters"],"answer":2,"explanation":""}'::jsonb,'315fdd6e5b4a5cdd4300dd8e8dd2e7e8','official',NULL,NULL,'Characterization and Character Development'),
('original:ela--literature-literary-analysis--characterization-and-character-development:ela--literature-literary-analysis--characterization-and-character-development--11',1,'{"question":"“Eli said he was calm, but his hands shook as he reached for the microphone.” What trait is best supported?","choices":["arrogance","nervousness","boredom","generosity"],"answer":1,"explanation":""}'::jsonb,'d3e7d2e46e7a2d08b116691abb3e46ba','official',NULL,NULL,'Characterization and Character Development'),
('original:ela--literature-literary-analysis--characterization-and-character-development:ela--literature-literary-analysis--characterization-and-character-development--12',1,'{"question":"A student argues that Nia is resourceful. Which evidence best supports the claim?","choices":["She lives near a river.","She appears in chapter three.","Her name is Nia.","She repairs the broken radio with parts from an old lamp."],"answer":3,"explanation":""}'::jsonb,'50ea1b762f2b7e7319d2dda5b20d29fa','official',NULL,NULL,'Characterization and Character Development'),
('original:ela--literature-literary-analysis--characterization-and-character-development:ela--literature-literary-analysis--characterization-and-character-development--13',1,'{"question":"A character apologizes after first blaming everyone else. What does this change most likely reveal?","choices":["a change in setting","a shift in narrator","a new subplot","growing accountability"],"answer":3,"explanation":""}'::jsonb,'9e29283b090d14e3685a080b2e89e0c4','official',NULL,NULL,'Characterization and Character Development'),
('original:ela--literature-literary-analysis--characterization-and-character-development:ela--literature-literary-analysis--characterization-and-character-development--14',1,'{"question":"A character repeatedly promises to help but avoids taking action. Which conclusion is best supported?","choices":["the character is reliable because of the promise","the character’s behavior conflicts with the promise","the character has changed completely","the narrator is necessarily unreliable"],"answer":1,"explanation":""}'::jsonb,'91fbd2adee391cd9d000f9706a8310d9','official',NULL,NULL,'Characterization and Character Development'),
('original:ela--literature-literary-analysis--characterization-and-character-development:ela--literature-literary-analysis--characterization-and-character-development--15',1,'{"question":"A proud athlete accepts coaching after a loss and changes practice habits. What best shows development?","choices":["the setting changes from gym to field","another character tells the story","a response to experience changes behavior","the conflict is resolved offstage"],"answer":2,"explanation":""}'::jsonb,'0351893fbd9e9b5c243ea1ce7a51b4ed','official',NULL,NULL,'Characterization and Character Development'),
('original:ela--literature-literary-analysis--characterization-and-character-development:ela--literature-literary-analysis--characterization-and-character-development--16',1,'{"question":"A character who values privacy begins sharing plans with a trusted friend. What has most clearly changed?","choices":["the character’s willingness to trust","the story’s point of view","the time period","the main setting"],"answer":0,"explanation":""}'::jsonb,'feb0e8a038fb9e1f5763281d6006513c','official',NULL,NULL,'Characterization and Character Development')
insert into public.question_content_versions(source_key,version_number,question,content_hash,source_type,creator_id,source_set_id,source_title) values
('original:ela--literature-literary-analysis--characterization-and-character-development:ela--literature-literary-analysis--characterization-and-character-development--17',1,'{"question":"The protagonist’s careful questions reveal more than the narrator’s label “curious.” Which evidence should readers weigh most?","choices":["the narrator’s chapter length","the character’s actions and dialogue","the story’s title alone","the number of characters"],"answer":1,"explanation":""}'::jsonb,'d05d696641ebf704830d42bf7c2c69b4','official',NULL,NULL,'Characterization and Character Development'),
('original:ela--literature-literary-analysis--characterization-and-character-development:ela--literature-literary-analysis--characterization-and-character-development--18',1,'{"question":"A shy character leads a group during an emergency, then returns to being reserved afterward. Which reading is most precise?","choices":["the character is a foil to the group","the character must be the narrator","the character shows situational growth without necessarily changing every trait","the character has no consistent traits"],"answer":2,"explanation":""}'::jsonb,'9ff057e82c590d4ce843d73063f0c099','official',NULL,NULL,'Characterization and Character Development'),
('original:ela--literature-literary-analysis--characterization-and-character-development:ela--literature-literary-analysis--characterization-and-character-development--19',1,'{"question":"A boastful character quietly gives credit to a teammate after a loss. What does this action suggest?","choices":["the character may be reconsidering self-importance","the setting has changed","the conflict is resolved before the story begins","the narrator cannot be trusted"],"answer":0,"explanation":""}'::jsonb,'ea3e6a3372e079d6c456623d206bdc4c','official',NULL,NULL,'Characterization and Character Development'),
('original:ela--literature-literary-analysis--characterization-and-character-development:ela--literature-literary-analysis--characterization-and-character-development--20',1,'{"question":"A character’s words sound confident, but private thoughts reveal fear. What contrast helps readers understand the character?","choices":["setting and plot order","theme and genre","exposition and resolution","dialogue and internal thoughts"],"answer":3,"explanation":""}'::jsonb,'ced64c9793e491d0dca892ed6ecdc164','official',NULL,NULL,'Characterization and Character Development'),
('original:ela--literature-literary-analysis--theme-and-central-meaning:ela--literature-literary-analysis--theme-and-central-meaning--1',1,'{"question":"In literary analysis, what is a theme?","choices":["the subject named in one word","the sequence of events","a message or insight about life developed by a text","the location of the story"],"answer":2,"explanation":""}'::jsonb,'40e9ca2cd62762a2e5171f0c984a1a93','official',NULL,NULL,'Theme and Central Meaning'),
('original:ela--literature-literary-analysis--theme-and-central-meaning:ela--literature-literary-analysis--theme-and-central-meaning--2',1,'{"question":"“Friendship” names a broad subject. What would turn it into a theme statement?","choices":["Trust grows when people support one another through difficulty.","Friendship","Two friends walk home.","The story has two characters."],"answer":0,"explanation":""}'::jsonb,'3456e2d33c76a61890d87baaee16eb30','official',NULL,NULL,'Theme and Central Meaning'),
('original:ela--literature-literary-analysis--theme-and-central-meaning:ela--literature-literary-analysis--theme-and-central-meaning--3',1,'{"question":"A theme should be supported by what?","choices":["a reader’s unrelated opinion","the author’s birthday","the number of pages","patterns and events in the text"],"answer":3,"explanation":""}'::jsonb,'294a626eb3ba6eaee186d3b426313847','official',NULL,NULL,'Theme and Central Meaning'),
('original:ela--literature-literary-analysis--theme-and-central-meaning:ela--literature-literary-analysis--theme-and-central-meaning--4',1,'{"question":"A character refuses help, fails, then succeeds after accepting advice. Which theme is best supported?","choices":["every mistake is permanent","cooperation can help people meet difficult goals","advice always comes from strangers","success depends on luck alone"],"answer":1,"explanation":""}'::jsonb,'b204ce9454f9aba863048240ad32b652','official',NULL,NULL,'Theme and Central Meaning'),
('original:ela--literature-literary-analysis--theme-and-central-meaning:ela--literature-literary-analysis--theme-and-central-meaning--5',1,'{"question":"A story shows a student returning a lost wallet even though no one saw the choice. Which idea is best supported?","choices":["wealth guarantees happiness","integrity is shown through choices made without an audience","rules are impossible to follow","privacy causes conflict"],"answer":1,"explanation":""}'::jsonb,'b991137ed5b306b2afede8392b22f573','official',NULL,NULL,'Theme and Central Meaning'),
('original:ela--literature-literary-analysis--theme-and-central-meaning:ela--literature-literary-analysis--theme-and-central-meaning--6',1,'{"question":"Two characters disagree but listen and revise their views. What theme could this develop?","choices":["disagreement always ends relationships","confidence prevents learning","silence is the only path to peace","respectful dialogue can change understanding"],"answer":3,"explanation":""}'::jsonb,'314b2ccc463896f546380cfa9c9a21a1','official',NULL,NULL,'Theme and Central Meaning'),
('original:ela--literature-literary-analysis--theme-and-central-meaning:ela--literature-literary-analysis--theme-and-central-meaning--7',1,'{"question":"A traveler reaches a goal but realizes the journey changed what matters to them. What theme might fit?","choices":["experiences can reshape a person’s priorities","travel always solves problems","goals are never worthwhile","change only affects places"],"answer":0,"explanation":""}'::jsonb,'7eac2a63dfa1405f426684978ceb030b','official',NULL,NULL,'Theme and Central Meaning'),
('original:ela--literature-literary-analysis--theme-and-central-meaning:ela--literature-literary-analysis--theme-and-central-meaning--8',1,'{"question":"A story’s topic is “ambition.” Which is a theme rather than a topic?","choices":["Ambition","A student enters a contest.","Ambition without regard for others can cause harm.","The story takes place at school."],"answer":2,"explanation":""}'::jsonb,'90d804d2be3b051272fcb13f0489aab8','official',NULL,NULL,'Theme and Central Meaning'),
('original:ela--literature-literary-analysis--theme-and-central-meaning:ela--literature-literary-analysis--theme-and-central-meaning--9',1,'{"question":"A student reads a short story about one contest winner and writes, “Everyone should always follow every dream.” What is the main weakness?","choices":["It generalizes beyond what the story establishes.","It names only a broad subject, not an insight.","It summarizes a single plot event.","It describes setting instead of meaning."],"answer":0,"explanation":""}'::jsonb,'f5d0083c2d09f20e5addcd8c48eb23ad','official',NULL,NULL,'Theme and Central Meaning'),
('original:ela--literature-literary-analysis--theme-and-central-meaning:ela--literature-literary-analysis--theme-and-central-meaning--10',1,'{"question":"A character gains recognition but loses close friendships through dishonesty. Which theme is most supported?","choices":["fame always creates friendship","honesty prevents all conflict","achievement may carry a cost when pursued without integrity","recognition is the same as happiness"],"answer":2,"explanation":""}'::jsonb,'d41114d9b96bdace21f29336b5d9d518','official',NULL,NULL,'Theme and Central Meaning'),
('original:ela--literature-literary-analysis--theme-and-central-meaning:ela--literature-literary-analysis--theme-and-central-meaning--11',1,'{"question":"A story ends with a community restoring a damaged park together. Which theme best fits the repeated actions?","choices":["nature cannot recover","shared responsibility can improve a community","leaders should work alone","public spaces have no value"],"answer":1,"explanation":""}'::jsonb,'666a99f2917aab9dde78c672f314e100','official',NULL,NULL,'Theme and Central Meaning'),
('original:ela--literature-literary-analysis--theme-and-central-meaning:ela--literature-literary-analysis--theme-and-central-meaning--12',1,'{"question":"A character learns that asking questions is a strength, not a weakness. Which theme statement expresses the insight?","choices":["Questions","A classroom discussion","A student reads a book","Curiosity can support learning and confidence."],"answer":3,"explanation":""}'::jsonb,'d78211b600987e805312c60c4b16d25b','official',NULL,NULL,'Theme and Central Meaning'),
('original:ela--literature-literary-analysis--theme-and-central-meaning:ela--literature-literary-analysis--theme-and-central-meaning--13',1,'{"question":"To identify a theme, readers should connect what elements?","choices":["page numbers, chapter titles, and font","author biography and publication date only","setting names and dialogue tags only","character choices, consequences, and recurring ideas"],"answer":3,"explanation":""}'::jsonb,'1e3c07b9e81a954d682124244d30634c','official',NULL,NULL,'Theme and Central Meaning'),
('original:ela--literature-literary-analysis--theme-and-central-meaning:ela--literature-literary-analysis--theme-and-central-meaning--14',1,'{"question":"A story repeats images of locked doors, while its character slowly learns to speak honestly. Which theme is best supported?","choices":["doors are difficult to build","honesty can open paths to connection","secrets always protect people","change is impossible"],"answer":1,"explanation":""}'::jsonb,'25e875e6f892f4d330f5a454348234bb','official',NULL,NULL,'Theme and Central Meaning'),
('original:ela--literature-literary-analysis--theme-and-central-meaning:ela--literature-literary-analysis--theme-and-central-meaning--15',1,'{"question":"A narrator says “be brave,” but the plot rewards a character who carefully asks for help. What should a theme claim rely on most?","choices":["a single instruction in isolation","the reader’s favorite character","the text’s full pattern of choices and consequences","the story’s genre label"],"answer":2,"explanation":""}'::jsonb,'14d007c70b6303203115c27026db886c','official',NULL,NULL,'Theme and Central Meaning'),
('original:ela--literature-literary-analysis--theme-and-central-meaning:ela--literature-literary-analysis--theme-and-central-meaning--16',1,'{"question":"A character gives up a prize to keep a promise. What theme does that decision most directly support?","choices":["loyalty may require personal sacrifice","rewards are always unfair","promises have no consequences","competition is harmful in every case"],"answer":0,"explanation":""}'::jsonb,'84a329cf6ecebaa767b55fca8020c147','official',NULL,NULL,'Theme and Central Meaning'),
('original:ela--literature-literary-analysis--theme-and-central-meaning:ela--literature-literary-analysis--theme-and-central-meaning--17',1,'{"question":"A story presents success after several failures, with reflection after each attempt. Which theme is best supported?","choices":["failure is always caused by others","learning from setbacks can lead to progress","reflection prevents success","goals should never change"],"answer":1,"explanation":""}'::jsonb,'f8e461375f3d80ae2509a59bd7df5148','official',NULL,NULL,'Theme and Central Meaning'),
('original:ela--literature-literary-analysis--theme-and-central-meaning:ela--literature-literary-analysis--theme-and-central-meaning--18',1,'{"question":"A text includes both a generous mentor and a selfish leader. How can their contrasting outcomes develop theme?","choices":["contrasting them reveals the exact setting","their roles determine the narrator","comparing their choices shows how values affect relationships","differences remove the need for evidence"],"answer":2,"explanation":""}'::jsonb,'aa18ce9fbf92f951a152e5b232473297','official',NULL,NULL,'Theme and Central Meaning'),
('original:ela--literature-literary-analysis--theme-and-central-meaning:ela--literature-literary-analysis--theme-and-central-meaning--19',1,'{"question":"A student claims the theme is “technology.” What revision makes it an arguable insight?","choices":["Technology can connect people while also changing how they communicate.","Technology","A phone rings.","The story includes a device."],"answer":0,"explanation":""}'::jsonb,'8b85ebdad0722d3a60ce81a556a12a9a','official',NULL,NULL,'Theme and Central Meaning'),
('original:ela--literature-literary-analysis--theme-and-central-meaning:ela--literature-literary-analysis--theme-and-central-meaning--20',1,'{"question":"A story’s ending leaves a conflict partly unresolved but shows the character accepting responsibility. Which theme is most defensible?","choices":["every conflict must have a perfect ending","responsibility guarantees success","unresolved plots have no meaning","taking responsibility can matter even when problems remain"],"answer":3,"explanation":""}'::jsonb,'92125d6a40ef7c9fa5758ed12aa0ce0e','official',NULL,NULL,'Theme and Central Meaning'),
('original:ela--literature-literary-analysis--point-of-view-and-narration:ela--literature-literary-analysis--point-of-view-and-narration--1',1,'{"question":"Who is the narrator?","choices":["the real author in every case","the main conflict","the voice that tells the story","the intended audience"],"answer":2,"explanation":""}'::jsonb,'615368a8c9e4b547723d03271786aedf','official',NULL,NULL,'Point of View and Narration'),
('original:ela--literature-literary-analysis--point-of-view-and-narration:ela--literature-literary-analysis--point-of-view-and-narration--2',1,'{"question":"Which pronouns commonly signal first-person narration?","choices":["I and we","he and she","you and they","it and those"],"answer":0,"explanation":""}'::jsonb,'efe24512f5c68f7f394b6ca84cb95e5f','official',NULL,NULL,'Point of View and Narration'),
('original:ela--literature-literary-analysis--point-of-view-and-narration:ela--literature-literary-analysis--point-of-view-and-narration--3',1,'{"question":"A narrator refers to the protagonist as “she” and reports only what she notices. Which point of view is this?","choices":["first person","second person","third-person omniscient","third-person limited"],"answer":3,"explanation":""}'::jsonb,'645aaf307d4c2e0aafe280b42f966df5','official',NULL,NULL,'Point of View and Narration'),
