('original:ela--literature-literary-analysis--point-of-view-and-narration:ela--literature-literary-analysis--point-of-view-and-narration--8',1,'{"question":"A narrator describes several characters’ private thoughts and pasts. What kind of access does the narrator have?","choices":["limited","first person","omniscient","objective"],"answer":2,"explanation":""}'::jsonb,'a3e48e127cb941cef6e53ae518d85bfa','official',NULL,NULL,'Point of View and Narration'),
