('original:ela--literature-literary-analysis--literary-conflict:ela--literature-literary-analysis--literary-conflict--1',1,'{"question":"What is conflict in a narrative?","choices":["the place where events occur","the narrator’s word choice","a struggle that creates tension around a goal or value","the final sentence"],"answer":2,"explanation":""}'::jsonb,'22f5b2d2957a1c6e6cd9e131893d5ade','official',NULL,NULL,'Literary Conflict'),
