('original:ela--literature-literary-analysis--literary-conflict:ela--literature-literary-analysis--literary-conflict--5',1,'{"question":"A community challenges a rule that excludes some residents. What conflict is shown?","choices":["character versus nature","character versus society","character versus self","character versus technology"],"answer":1,"explanation":""}'::jsonb,'24b1aabb09d5b34042f3a14536deaf0f','official',NULL,NULL,'Literary Conflict'),
