('original:ela--literature-literary-analysis--literary-conflict:ela--literature-literary-analysis--literary-conflict--9',1,'{"question":"A character wants to preserve a family tradition while the town pressures everyone to abandon it. Which conflict is strongest?","choices":["character versus society","character versus self only","character versus nature","character versus technology"],"answer":0,"explanation":""}'::jsonb,'bc8d0992ee0086da0396432bf71b5a3c','official',NULL,NULL,'Literary Conflict'),
('original:ela--literature-literary-analysis--literary-conflict:ela--literature-literary-analysis--literary-conflict--10',1,'{"question":"A wildfire threatens a town, and neighbors disagree about evacuation. What is the main external force?","choices":["an internal fear","a machine","nature","a single rival"],"answer":2,"explanation":""}'::jsonb,'d66fb3c70d5c8c80b6ee8e200cd802f4','official',NULL,NULL,'Literary Conflict'),
