('original:ela--literature-literary-analysis--literary-conflict:ela--literature-literary-analysis--literary-conflict--14',1,'{"question":"A character struggles with guilt after falsely accusing someone. What type of conflict is most directly shown?","choices":["character versus nature","character versus self","character versus technology","character versus society"],"answer":1,"explanation":""}'::jsonb,'33f6080008c23f9f14a2afcfb951db1a','official',NULL,NULL,'Literary Conflict'),
('original:ela--literature-literary-analysis--literary-conflict:ela--literature-literary-analysis--literary-conflict--15',1,'{"question":"A bridge collapse forces two rivals to cooperate against a rising river. How does the setting affect conflict?","choices":["it removes the conflict","it turns the narrator into an antagonist","an environmental threat changes how characters respond to each other","it resolves every disagreement"],"answer":2,"explanation":""}'::jsonb,'a8f828a267a7bc579f8264216276472f','official',NULL,NULL,'Literary Conflict'),
