('original:ela--literature-literary-analysis--setting-tone-and-mood:ela--literature-literary-analysis--setting-tone-and-mood--17',1,'{"question":"A bleak landscape is described in playful, exaggerated language. Which conclusion is defensible?","choices":["tone and setting cannot contrast","the setting may be bleak while the tone is playful","the mood is certainly bleak for every reader","the author has no attitude"],"answer":1,"explanation":""}'::jsonb,'b21a62ce2a33a0dc557ba66b496846d9','official',NULL,NULL,'Setting, Tone, and Mood'),
('original:ela--literature-literary-analysis--setting-tone-and-mood:ela--literature-literary-analysis--setting-tone-and-mood--18',1,'{"question":"A character returns to a familiar room after many years; the room is smaller than remembered. What can the setting detail suggest?","choices":["the story has no time period","the narrator is omniscient","the character’s perspective has changed","the conflict is resolved"],"answer":2,"explanation":""}'::jsonb,'0b70dcd9926c090a488951371bfd234a','official',NULL,NULL,'Setting, Tone, and Mood'),
('original:ela--literature-literary-analysis--setting-tone-and-mood:ela--literature-literary-analysis--setting-tone-and-mood--19',1,'{"question":"Which revision would create a more hopeful mood in a scene about a storm?","choices":["neighbors bring lanterns and food to the shelter","the roof groans under another gust","water rises past the doorway","the lights fail one by one"],"answer":0,"explanation":""}'::jsonb,'9bbd1b918974e258953cd12bf739aa67','official',NULL,NULL,'Setting, Tone, and Mood'),
('original:ela--literature-literary-analysis--setting-tone-and-mood:ela--literature-literary-analysis--setting-tone-and-mood--20',1,'{"question":"Two readers feel differently about the same passage. What is the best explanation?","choices":["tone is chosen by each reader","setting changes for each reader","a text cannot create mood","mood can be influenced by readers’ experiences, while textual details still guide interpretation"],"answer":3,"explanation":""}'::jsonb,'662cf00a174c1917031967161863d112','official',NULL,NULL,'Setting, Tone, and Mood'),
('original:ela--literature-literary-analysis--figurative-language:ela--literature-literary-analysis--figurative-language--1',1,'{"question":"A simile compares two unlike things using which words?","choices":["because or although","who or which","like or as","either or"],"answer":2,"explanation":""}'::jsonb,'2895cb7c3066c4cce19078fa83e5c0a4','official',NULL,NULL,'Figurative Language'),
('original:ela--literature-literary-analysis--figurative-language:ela--literature-literary-analysis--figurative-language--2',1,'{"question":"A metaphor describes one thing as another without using “like” or “as.” Which sentence is a metaphor?","choices":["The classroom was a beehive of activity.","The classroom was as busy as a beehive.","Bees flew past the window.","The classroom had many desks."],"answer":0,"explanation":""}'::jsonb,'bcd8513ee92466244c0abf69d719cd9b','official',NULL,NULL,'Figurative Language'),
('original:ela--literature-literary-analysis--figurative-language:ela--literature-literary-analysis--figurative-language--3',1,'{"question":"Giving human actions or feelings to a nonhuman thing is called what?","choices":["alliteration","understatement","rhyme","personification"],"answer":3,"explanation":""}'::jsonb,'29dcd3716f3ebc158362d6b9b0409449','official',NULL,NULL,'Figurative Language'),
('original:ela--literature-literary-analysis--figurative-language:ela--literature-literary-analysis--figurative-language--4',1,'{"question":"An intentional exaggeration for emphasis is what?","choices":["literal language","hyperbole","onomatopoeia","allusion"],"answer":1,"explanation":""}'::jsonb,'cc29bfbda21a1482948543c6e40e7314','official',NULL,NULL,'Figurative Language'),
('original:ela--literature-literary-analysis--figurative-language:ela--literature-literary-analysis--figurative-language--5',1,'{"question":"Repeated initial consonant sounds in nearby words create what device?","choices":["assonance","alliteration","metaphor","irony"],"answer":1,"explanation":""}'::jsonb,'2d569dbd7b3679cd7cb4233507bdcacb','official',NULL,NULL,'Figurative Language'),
('original:ela--literature-literary-analysis--figurative-language:ela--literature-literary-analysis--figurative-language--6',1,'{"question":"“Buzz” imitates a sound. Which device is used?","choices":["personification","simile","symbolism","onomatopoeia"],"answer":3,"explanation":""}'::jsonb,'1faedcdf2b9e4c84931219580efbd542','official',NULL,NULL,'Figurative Language'),
('original:ela--literature-literary-analysis--figurative-language:ela--literature-literary-analysis--figurative-language--7',1,'{"question":"A comparison that uses “like” appears in which sentence?","choices":["Her idea spread like wildfire.","Her idea was wildfire.","The idea spread quickly.","The idea was popular."],"answer":0,"explanation":""}'::jsonb,'1cd3eca770002d0efef9d8800acd9259','official',NULL,NULL,'Figurative Language'),
('original:ela--literature-literary-analysis--figurative-language:ela--literature-literary-analysis--figurative-language--8',1,'{"question":"“The wind whispered through the grass” gives the wind a human action. What is this?","choices":["hyperbole","alliteration","personification","literal description"],"answer":2,"explanation":""}'::jsonb,'3b4a776aa6d87e69e21f027caf052708','official',NULL,NULL,'Figurative Language'),
('original:ela--literature-literary-analysis--figurative-language:ela--literature-literary-analysis--figurative-language--9',1,'{"question":"“I have waited a thousand years” is most likely what?","choices":["hyperbole","simile","onomatopoeia","understatement"],"answer":0,"explanation":""}'::jsonb,'bb6055620d03cc033438c7214129d2a4','official',NULL,NULL,'Figurative Language'),
('original:ela--literature-literary-analysis--figurative-language:ela--literature-literary-analysis--figurative-language--10',1,'{"question":"“Silver sunlight slid across the sea” repeats an initial sound. Which device is prominent?","choices":["metaphor","personification","alliteration","idiom"],"answer":2,"explanation":""}'::jsonb,'1dbec2725b4e5a6002dba76e3acc1a14','official',NULL,NULL,'Figurative Language'),
('original:ela--literature-literary-analysis--figurative-language:ela--literature-literary-analysis--figurative-language--11',1,'{"question":"A poem says, “His words were icy.” What does the metaphor most likely suggest?","choices":["his words were made of ice","his words felt cold or unkind","he spoke outdoors","the speaker was thirsty"],"answer":1,"explanation":""}'::jsonb,'a8e41e8999097b024d66ecdb5cba44c2','official',NULL,NULL,'Figurative Language'),
('original:ela--literature-literary-analysis--figurative-language:ela--literature-literary-analysis--figurative-language--12',1,'{"question":"“Her backpack weighed a ton” is not meant as a literal measurement. Why?","choices":["it is a simile comparing two objects","it is onomatopoeia","it is a technical fact","it is hyperbole emphasizing heaviness"],"answer":3,"explanation":""}'::jsonb,'5405c88bb08dd5f6203cf47b6214001f','official',NULL,NULL,'Figurative Language'),
('original:ela--literature-literary-analysis--figurative-language:ela--literature-literary-analysis--figurative-language--13',1,'{"question":"“Time crawled during the long wait.” Which interpretation best fits?","choices":["time moved on hands and feet","the speaker was studying biology","the sentence is a literal report","the wait felt slow"],"answer":3,"explanation":""}'::jsonb,'d46b8790fe7f7453324348266e91ad71','official',NULL,NULL,'Figurative Language'),
('original:ela--literature-literary-analysis--figurative-language:ela--literature-literary-analysis--figurative-language--14',1,'{"question":"Which sentence uses personification rather than a metaphor?","choices":["The house was a ship.","The old house sighed in the wind.","The house was like a ship.","The house had a blue door."],"answer":1,"explanation":""}'::jsonb,'9fb92fc00a79e07383834ebfe4bff06f','official',NULL,NULL,'Figurative Language'),
('original:ela--literature-literary-analysis--figurative-language:ela--literature-literary-analysis--figurative-language--15',1,'{"question":"A writer describes an idea as “a seed that took root.” What does the comparison suggest?","choices":["the idea was planted in soil","the speaker forgot the idea","the idea began to grow and develop","the idea ended immediately"],"answer":2,"explanation":""}'::jsonb,'004dea140b2553937dc9c03a44fca0d1','official',NULL,NULL,'Figurative Language'),
('original:ela--literature-literary-analysis--figurative-language:ela--literature-literary-analysis--figurative-language--16',1,'{"question":"“Clack, clack, clack” appears as a train crosses a bridge. What is the sound effect doing?","choices":["imitating the train’s noise","comparing the train to a person","exaggerating the bridge’s length","describing a symbol"],"answer":0,"explanation":""}'::jsonb,'f5244ade3d856926e100099c37e7bc62','official',NULL,NULL,'Figurative Language')
insert into public.question_content_versions(source_key,version_number,question,content_hash,source_type,creator_id,source_set_id,source_title) values
('original:ela--literature-literary-analysis--figurative-language:ela--literature-literary-analysis--figurative-language--17',1,'{"question":"“The stars were pinholes in the dark curtain of night.” Which feature makes this figurative?","choices":["it gives the stars human speech","stars and sky are compared to holes and fabric","it repeats a consonant only","it reports a scientific measurement"],"answer":1,"explanation":""}'::jsonb,'1b33c82fdf0e56e1d919b3ac11779d8c','official',NULL,NULL,'Figurative Language'),
('original:ela--literature-literary-analysis--figurative-language:ela--literature-literary-analysis--figurative-language--18',1,'{"question":"A student interprets “a mountain of work” as a literal landform. What should the student consider?","choices":["every metaphor names a setting","figurative language is always literal","the phrase is likely hyperbole for a large amount","mountains symbolize conflict in every text"],"answer":2,"explanation":""}'::jsonb,'144f4f65ccdbdfe71730d7ddffb287d6','official',NULL,NULL,'Figurative Language'),
('original:ela--literature-literary-analysis--figurative-language:ela--literature-literary-analysis--figurative-language--19',1,'{"question":"Which revision uses a simile to describe a quick runner?","choices":["The runner darted like an arrow.","The runner was an arrow.","The runner ran quickly.","The runner’s shoes were red."],"answer":0,"explanation":""}'::jsonb,'9d99a11133fd0c2d4857a4c9b7a5d654','official',NULL,NULL,'Figurative Language'),
('original:ela--literature-literary-analysis--figurative-language:ela--literature-literary-analysis--figurative-language--20',1,'{"question":"A poem calls a promise “a bridge between neighbors.” Which interpretation is best supported?","choices":["the promise is made of wood","the neighbors live near a river","the promise is a person","the promise connects the neighbors"],"answer":3,"explanation":""}'::jsonb,'d20d3bac79f5652a06335d17b18b9422','official',NULL,NULL,'Figurative Language'),
('original:ela--literature-literary-analysis--irony:ela--literature-literary-analysis--irony--1',1,'{"question":"Verbal irony occurs when a speaker’s words differ from what the speaker what?","choices":["hears","remembers","means","writes down"],"answer":2,"explanation":""}'::jsonb,'78f3a6090ed366ab519535e387014508','official',NULL,NULL,'Irony'),
('original:ela--literature-literary-analysis--irony:ela--literature-literary-analysis--irony--2',1,'{"question":"Situational irony involves an outcome that is meaningfully different from what is what?","choices":["expected","described literally","spoken aloud","written in first person"],"answer":0,"explanation":""}'::jsonb,'ba0289f349c27e3324a5da982274db0f','official',NULL,NULL,'Irony'),
('original:ela--literature-literary-analysis--irony:ela--literature-literary-analysis--irony--3',1,'{"question":"Dramatic irony occurs when readers know something important that a character does what?","choices":["refuses to say","already explained","invents","not know"],"answer":3,"explanation":""}'::jsonb,'45e7eada6835b3e8e584bc3d1710246a','official',NULL,NULL,'Irony'),
('original:ela--literature-literary-analysis--irony:ela--literature-literary-analysis--irony--4',1,'{"question":"After getting soaked in a downpour, a character says, “Perfect weather for a picnic.” What is likely used?","choices":["dramatic irony","verbal irony","situational irony","foreshadowing"],"answer":1,"explanation":""}'::jsonb,'490c2e54a7661495acffeab2f992ba79','official',NULL,NULL,'Irony'),
('original:ela--literature-literary-analysis--irony:ela--literature-literary-analysis--irony--5',1,'{"question":"A fire station burns down because its alarm system was disconnected for testing. What device may describe the unexpected outcome?","choices":["verbal irony","situational irony","dramatic irony","allusion"],"answer":1,"explanation":""}'::jsonb,'2aca0394334769f946a0c6e9d03d683f','official',NULL,NULL,'Irony'),
('original:ela--literature-literary-analysis--irony:ela--literature-literary-analysis--irony--6',1,'{"question":"Readers know a disguised visitor is the missing heir, but the characters do not. What is this?","choices":["verbal irony","situational irony","hyperbole","dramatic irony"],"answer":3,"explanation":""}'::jsonb,'045c337d7626ca34518ee429f48c9fea','official',NULL,NULL,'Irony'),
('original:ela--literature-literary-analysis--irony:ela--literature-literary-analysis--irony--7',1,'{"question":"A student studies all night for the wrong exam. Which detail makes the outcome ironic?","choices":["preparation is aimed at a test that will not occur","the student reads a book","the exam takes place at school","the student feels tired"],"answer":0,"explanation":""}'::jsonb,'2442a6fc936a0ded1ad5807828c2bb5b','official',NULL,NULL,'Irony'),
('original:ela--literature-literary-analysis--irony:ela--literature-literary-analysis--irony--8',1,'{"question":"A character says “I love waiting” while tapping a foot and checking the clock. What is the likely meaning?","choices":["the character enjoys the delay","the character has forgotten the time","the character is impatient","the character is speaking literally"],"answer":2,"explanation":""}'::jsonb,'e9b13cef07a2763635baa2a1cf6197c8','official',NULL,NULL,'Irony'),
('original:ela--literature-literary-analysis--irony:ela--literature-literary-analysis--irony--9',1,'{"question":"A town installs a huge clock to improve punctuality, but the clock stops during the opening ceremony. What is the ironic contrast?","choices":["a timekeeping project immediately fails to keep time","the clock is large","people gather in town","the ceremony has speeches"],"answer":0,"explanation":""}'::jsonb,'69cca0c0a1bd78b4ddc327b65894c713','official',NULL,NULL,'Irony'),
('original:ela--literature-literary-analysis--irony:ela--literature-literary-analysis--irony--10',1,'{"question":"Which situation is dramatic irony?","choices":["a speaker says “great job” after a mistake","a careful plan fails unexpectedly","readers see a warning sign before a character enters the unsafe room","a character explains a surprise"],"answer":2,"explanation":""}'::jsonb,'54051a381fbe384ca65289137c559369','official',NULL,NULL,'Irony'),
('original:ela--literature-literary-analysis--irony:ela--literature-literary-analysis--irony--11',1,'{"question":"A lifeguard forgets swim lessons and needs rescuing at the pool. What is the strongest ironic element?","choices":["the pool contains water","the person expected to rescue others needs rescue","other people are nearby","the lifeguard wears a uniform"],"answer":1,"explanation":""}'::jsonb,'74e441f6565db2b92f55e52408ea35a6','official',NULL,NULL,'Irony'),
('original:ela--literature-literary-analysis--irony:ela--literature-literary-analysis--irony--12',1,'{"question":"A character says “Nothing can go wrong,” while the stage directions show a candle falling toward papers. What do viewers know?","choices":["the candle is a narrator","the character is speaking to the audience in second person","the plot has ended","the character’s confidence may be misplaced"],"answer":3,"explanation":""}'::jsonb,'3ec95cf045a243e47d563ce11d403c1a','official',NULL,NULL,'Irony'),
('original:ela--literature-literary-analysis--irony:ela--literature-literary-analysis--irony--13',1,'{"question":"A student calls every surprising event “irony.” What distinction is important?","choices":["every surprise is automatically irony","irony only occurs in comedy","irony means an event is impossible","irony involves a meaningful gap between expectation and outcome or meaning"],"answer":3,"explanation":""}'::jsonb,'b66c55c984bf029ff58271443dceb97e','official',NULL,NULL,'Irony'),
('original:ela--literature-literary-analysis--irony:ela--literature-literary-analysis--irony--14',1,'{"question":"A restaurant advertises “fast service,” but one customer waits hours because the kitchen misplaced the order. Which claim is best supported?","choices":["the waiter uses a metaphor","the outcome contrasts with the advertised expectation","the customer is the narrator","the setting is a restaurant"],"answer":1,"explanation":""}'::jsonb,'7018921a7dead3597e2c8a89c7dcc4ed','official',NULL,NULL,'Irony'),
('original:ela--literature-literary-analysis--irony:ela--literature-literary-analysis--irony--15',1,'{"question":"A narrator praises a “wonderfully organized” desk while describing papers covering the floor. What clue signals verbal irony?","choices":["the narrator uses past tense","the desk is indoors","the praise conflicts with the described mess","the papers are visible"],"answer":2,"explanation":""}'::jsonb,'e1143aec751c30e85990f8423b3a95e5','official',NULL,NULL,'Irony'),
('original:ela--literature-literary-analysis--irony:ela--literature-literary-analysis--irony--16',1,'{"question":"A character hides from a harmless cat, while readers know the cat is looking for its owner. What creates dramatic irony?","choices":["readers know the cat’s purpose before the character does","the character speaks sarcastically","the cat is unexpectedly large","the setting is a home"],"answer":0,"explanation":""}'::jsonb,'b6a1056fc8c21f6c07256f195e85658c','official',NULL,NULL,'Irony'),
('original:ela--literature-literary-analysis--irony:ela--literature-literary-analysis--irony--17',1,'{"question":"Which is the clearest example of situational irony?","choices":["A speaker says “Lovely day” during a storm.","A mail carrier receives a letter addressed to the wrong person.","Readers know a secret that the hero does not.","A character describes a blue coat."],"answer":1,"explanation":""}'::jsonb,'cb363e67fc03767bdc7aae218d805129','official',NULL,NULL,'Irony'),
('original:ela--literature-literary-analysis--irony:ela--literature-literary-analysis--irony--18',1,'{"question":"A school’s “quiet reading contest” is interrupted by a loud announcement from the contest organizers. Why might this be ironic?","choices":["reading happens indoors","announcements use speakers","the organizers disrupt the quiet they are promoting","students have books"],"answer":2,"explanation":""}'::jsonb,'1d736a4fda62e8c938766148964711bf','official',NULL,NULL,'Irony'),
('original:ela--literature-literary-analysis--irony:ela--literature-literary-analysis--irony--19',1,'{"question":"In a story, a character fears a harmless shadow while overlooking a real danger behind them. What could this contrast create?","choices":["dramatic irony if readers recognize the danger first","verbal irony because shadows speak","situational irony whenever fear occurs","no irony because the shadow exists"],"answer":0,"explanation":""}'::jsonb,'fc660ab4451d819b9d2d7467912995bf','official',NULL,NULL,'Irony'),
('original:ela--literature-literary-analysis--irony:ela--literature-literary-analysis--irony--20',1,'{"question":"A promised “surprise ending” is obvious from the opening clues. What has the author weakened?","choices":["the setting’s physical detail","the narrator’s use of first person","the story’s sentence structure","the gap between reader expectation and the ending"],"answer":3,"explanation":""}'::jsonb,'54605c3a5c24b686d5820e3abdbd8292','official',NULL,NULL,'Irony'),
('original:ela--literature-literary-analysis--symbolism-and-motifs:ela--literature-literary-analysis--symbolism-and-motifs--1',1,'{"question":"A symbol is a concrete object, image, or action that also represents what?","choices":["the exact setting only","the plot’s chronological order","an additional idea or meaning","a character’s dialogue tag"],"answer":2,"explanation":""}'::jsonb,'59e9c747d3f9205cac75c847287e0736','official',NULL,NULL,'Symbolism and Motifs'),
('original:ela--literature-literary-analysis--symbolism-and-motifs:ela--literature-literary-analysis--symbolism-and-motifs--2',1,'{"question":"A motif is a recurring element that helps develop what?","choices":["patterns of meaning in a text","the author’s biography","the number of chapters","the point of view alone"],"answer":0,"explanation":""}'::jsonb,'e913d06db4ad5bdbeee2eb2bc507ad3c','official',NULL,NULL,'Symbolism and Motifs'),
('original:ela--literature-literary-analysis--symbolism-and-motifs:ela--literature-literary-analysis--symbolism-and-motifs--3',1,'{"question":"A story repeatedly shows locked doors when its character avoids difficult conversations. What may the doors symbolize?","choices":["the story’s time period","the narrator’s name","the literal weather","barriers to communication"],"answer":3,"explanation":""}'::jsonb,'a7dd68d92e1d01cf5728147c959413d9','official',NULL,NULL,'Symbolism and Motifs'),
('original:ela--literature-literary-analysis--symbolism-and-motifs:ela--literature-literary-analysis--symbolism-and-motifs--4',1,'{"question":"A white flag appears as opponents agree to stop fighting. What does it commonly symbolize in this context?","choices":["a new character","a request for peace or surrender","a change in season","an unreliable narrator"],"answer":1,"explanation":""}'::jsonb,'f70e4d69f13602376b70d6b185b8e89a','official',NULL,NULL,'Symbolism and Motifs'),
('original:ela--literature-literary-analysis--symbolism-and-motifs:ela--literature-literary-analysis--symbolism-and-motifs--5',1,'{"question":"A cracked family photograph appears whenever relatives argue. What might its repetition create?","choices":["a change in point of view","a motif connected to strained relationships","a plot summary","a literal setting description"],"answer":1,"explanation":""}'::jsonb,'1de0b72049a3b0a721aa3d792db1a135','official',NULL,NULL,'Symbolism and Motifs'),
('original:ela--literature-literary-analysis--symbolism-and-motifs:ela--literature-literary-analysis--symbolism-and-motifs--6',1,'{"question":"A character carries an old key but never finds a matching lock. Which interpretation is most cautious?","choices":["it definitely symbolizes freedom in every story","it must be the climax","it cannot be symbolic","its meaning may depend on how the story develops"],"answer":3,"explanation":""}'::jsonb,'64be149b863509aa37e3282d96e564f8','official',NULL,NULL,'Symbolism and Motifs'),
('original:ela--literature-literary-analysis--symbolism-and-motifs:ela--literature-literary-analysis--symbolism-and-motifs--7',1,'{"question":"Rain appears during both a character’s loss and later renewal. How should readers interpret it?","choices":["consider how its meaning shifts with context","assume it always means sadness","ignore its recurrence","treat it as a character"],"answer":0,"explanation":""}'::jsonb,'68361f6c350b0a14cb31b39204e6be85','official',NULL,NULL,'Symbolism and Motifs'),
('original:ela--literature-literary-analysis--symbolism-and-motifs:ela--literature-literary-analysis--symbolism-and-motifs--8',1,'{"question":"A story repeatedly mentions birds leaving a cage as a character gains independence. What meaning is most supported?","choices":["fear of change","the arrival of winter","freedom from restriction","the narrator’s memory"],"answer":2,"explanation":""}'::jsonb,'db68818754021df6aed82ebb9762e7b2','official',NULL,NULL,'Symbolism and Motifs'),
('original:ela--literature-literary-analysis--symbolism-and-motifs:ela--literature-literary-analysis--symbolism-and-motifs--9',1,'{"question":"A red scarf appears at key moments when two characters choose to trust each other. How can the scarf function?","choices":["as a symbol linked to trust","as the setting","as the narrator","as a plot conflict by itself"],"answer":0,"explanation":""}'::jsonb,'e3b8c003e7106ab088a48abc783b7f02','official',NULL,NULL,'Symbolism and Motifs'),
('original:ela--literature-literary-analysis--symbolism-and-motifs:ela--literature-literary-analysis--symbolism-and-motifs--10',1,'{"question":"A phrase about “closed windows” appears in several chapters during moments of isolation. What makes it a motif?","choices":["it describes one location once","it reveals the author’s age","its recurrence links separate scenes","it is always a metaphor"],"answer":2,"explanation":""}'::jsonb,'ee68485df6117b592b001bd390d67f49','official',NULL,NULL,'Symbolism and Motifs'),
('original:ela--literature-literary-analysis--symbolism-and-motifs:ela--literature-literary-analysis--symbolism-and-motifs--11',1,'{"question":"A character plants a tree after moving to a new town; years later, the tree shades a community gathering. What may the tree suggest?","choices":["the exact date of every event","roots and belonging developing over time","the narrator’s point of view","a conflict that cannot change"],"answer":1,"explanation":""}'::jsonb,'63444ee585b08a27f09466bdbdac5769','official',NULL,NULL,'Symbolism and Motifs'),
('original:ela--literature-literary-analysis--symbolism-and-motifs:ela--literature-literary-analysis--symbolism-and-motifs--12',1,'{"question":"An object appears once and has no clear connection to larger ideas. What should a reader avoid assuming?","choices":["that it exists in the plot","that it is described by the author","that it can have literal meaning","that it is definitely a symbol"],"answer":3,"explanation":""}'::jsonb,'1957a47bf8a27cdcd59987f7ab0fc471','official',NULL,NULL,'Symbolism and Motifs'),
('original:ela--literature-literary-analysis--symbolism-and-motifs:ela--literature-literary-analysis--symbolism-and-motifs--13',1,'{"question":"A lighthouse appears when a character is unsure which path to take. Which interpretation is best supported by context?","choices":["it always represents danger","it proves the story is nonfiction","it changes the point of view","it may represent guidance or hope"],"answer":3,"explanation":""}'::jsonb,'3338c01b5644bfa124ce881049925a38','official',NULL,NULL,'Symbolism and Motifs'),
('original:ela--literature-literary-analysis--symbolism-and-motifs:ela--literature-literary-analysis--symbolism-and-motifs--14',1,'{"question":"A broken clock recurs while a character refuses to discuss a past decision. What pattern might the clock reinforce?","choices":["a cheerful future","being stuck in unresolved time","a new setting each time","a change in narrator"],"answer":1,"explanation":""}'::jsonb,'814a157ec2a794844562f38446990334','official',NULL,NULL,'Symbolism and Motifs'),
('original:ela--literature-literary-analysis--symbolism-and-motifs:ela--literature-literary-analysis--symbolism-and-motifs--15',1,'{"question":"A character gives away a medal earned in a competition. What might the action symbolize if the character now values teamwork?","choices":["the end of the setting","the beginning of a flashback","a shift in priorities","a literal weather change"],"answer":2,"explanation":""}'::jsonb,'a56cdc68b85e28d6d5cf479a1912bdf0','official',NULL,NULL,'Symbolism and Motifs'),
