('original:ela--literature-literary-analysis--literary-genres:ela--literature-literary-analysis--literary-genres--15',1,'{"question":"A story describes ordinary people and events that could occur in the present world. Which genre fits?","choices":["fantasy","myth","realistic fiction","science fiction"],"answer":2,"explanation":""}'::jsonb,'2632afeba882ae6a54f3b8ee194d9460','official',NULL,NULL,'Literary Genres'),
('original:ela--literature-literary-analysis--literary-genres:ela--literature-literary-analysis--literary-genres--16',1,'{"question":"A text presents characters’ speech and actions through scenes meant for performance. What genre is it?","choices":["drama","biography","informational article","memoir"],"answer":0,"explanation":""}'::jsonb,'fef461a0d60c12b2d863f8369152376d','official',NULL,NULL,'Literary Genres')
insert into public.question_content_versions(source_key,version_number,question,content_hash,source_type,creator_id,source_set_id,source_title) values
('original:ela--literature-literary-analysis--literary-genres:ela--literature-literary-analysis--literary-genres--17',1,'{"question":"A student labels a text “fantasy” because one character has an unusual name. What evidence would better support the label?","choices":["the title is short","impossible or magical elements shape the story","the text has chapters","a character has a name"],"answer":1,"explanation":""}'::jsonb,'54c2eda89a87a48181ff74bc1fc1ae28','official',NULL,NULL,'Literary Genres'),
('original:ela--literature-literary-analysis--literary-genres:ela--literature-literary-analysis--literary-genres--18',1,'{"question":"A novel set in the past includes invented characters alongside real historical events. What distinction matters?","choices":["it is autobiography","it must be a primary source","it is historical fiction, not a factual account in every detail","it cannot include evidence"],"answer":2,"explanation":""}'::jsonb,'aca686debc3e76106dc7f0e3b3288688','official',NULL,NULL,'Literary Genres'),
('original:ela--literature-literary-analysis--literary-genres:ela--literature-literary-analysis--literary-genres--19',1,'{"question":"A first-person account describes a person’s own memories and reflections. Which label is most precise?","choices":["memoir or autobiography, depending on scope","biography written by a stranger","fantasy","drama"],"answer":0,"explanation":""}'::jsonb,'c787c738cf2b0141f56846f80d922c31','official',NULL,NULL,'Literary Genres'),
('original:ela--literature-literary-analysis--literary-genres:ela--literature-literary-analysis--literary-genres--20',1,'{"question":"A text shares traits of mystery and science fiction. What is a sound conclusion?","choices":["every text belongs to exactly one genre","genre is based only on length","genre depends only on the author","genres can overlap when a work uses conventions of more than one"],"answer":3,"explanation":""}'::jsonb,'068931c15124415be49315e8c084f6fa','official',NULL,NULL,'Literary Genres'),
('original:ela--reading-informational-text--main-idea-and-supporting-details:ela--reading-informational-text--main-idea-and-supporting-details--1',1,'{"question":"What is the main idea of a paragraph?","choices":["one interesting example","the first word","its central point or message","the author’s name"],"answer":2,"explanation":""}'::jsonb,'7969fa327598125dac7096479d4be3e4','official',NULL,NULL,'Main Idea and Supporting Details'),
('original:ela--reading-informational-text--main-idea-and-supporting-details:ela--reading-informational-text--main-idea-and-supporting-details--2',1,'{"question":"Supporting details mainly do what?","choices":["explain, illustrate, or support the main idea","introduce unrelated topics","replace the central point","identify the narrator"],"answer":0,"explanation":""}'::jsonb,'70901ba7ff171be2de3cf1bc321363db','official',NULL,NULL,'Main Idea and Supporting Details'),
('original:ela--reading-informational-text--main-idea-and-supporting-details:ela--reading-informational-text--main-idea-and-supporting-details--3',1,'{"question":"A paragraph explains that shade trees cool streets, reduce runoff, and provide habitat. What main idea unites the details?","choices":["streets need more signs","birds live in forests only","rain is unpredictable","urban trees benefit communities in several ways"],"answer":3,"explanation":""}'::jsonb,'b533e932ff4c2c9e5852a186cd673a24','official',NULL,NULL,'Main Idea and Supporting Details'),
('original:ela--reading-informational-text--main-idea-and-supporting-details:ela--reading-informational-text--main-idea-and-supporting-details--4',1,'{"question":"A passage lists three reasons a library expanded its hours. What should a summary include?","choices":["every minor example in order","the central reason and key supporting points","the writer’s personal opinion only","details unrelated to the change"],"answer":1,"explanation":""}'::jsonb,'20687c1323f490a7bd894a73ad0140ce','official',NULL,NULL,'Main Idea and Supporting Details'),
('original:ela--reading-informational-text--main-idea-and-supporting-details:ela--reading-informational-text--main-idea-and-supporting-details--5',1,'{"question":"Which sentence is most likely a supporting detail for “Regular sleep supports learning”?","choices":["Learning matters to many people.","Students who sleep well often find it easier to focus in class.","Sleep is a word with four letters.","Some schools have blue doors."],"answer":1,"explanation":""}'::jsonb,'03167436e78d3dbe159e1a3fb6402587','official',NULL,NULL,'Main Idea and Supporting Details'),
('original:ela--reading-informational-text--main-idea-and-supporting-details:ela--reading-informational-text--main-idea-and-supporting-details--6',1,'{"question":"A paragraph begins with examples of bees pollinating crops and ends by explaining their role in food systems. What can readers infer is central?","choices":["crops grow only in spring","bees live in every region","food systems are simple","pollinators are important to agriculture"],"answer":3,"explanation":""}'::jsonb,'76181a389a7ed657bd164c31c429b957','official',NULL,NULL,'Main Idea and Supporting Details'),
('original:ela--reading-informational-text--main-idea-and-supporting-details:ela--reading-informational-text--main-idea-and-supporting-details--7',1,'{"question":"A text gives facts about several renewable energy sources but never states one main claim. How can a reader identify its central idea?","choices":["synthesize repeated information across the sections","choose the longest sentence","use the title alone","count the examples"],"answer":0,"explanation":""}'::jsonb,'ad0e7d0e6268fdd60ba0338a234934ad','official',NULL,NULL,'Main Idea and Supporting Details'),
('original:ela--reading-informational-text--main-idea-and-supporting-details:ela--reading-informational-text--main-idea-and-supporting-details--8',1,'{"question":"A detail appears once but does not connect to the paragraph’s central claim. What should a concise summary do with it?","choices":["make it the main idea","repeat it several times","usually leave it out","treat it as evidence for every claim"],"answer":2,"explanation":""}'::jsonb,'e72ffa0e3474d7bd0e4a2d265d25e9ad','official',NULL,NULL,'Main Idea and Supporting Details'),
('original:ela--reading-informational-text--main-idea-and-supporting-details:ela--reading-informational-text--main-idea-and-supporting-details--9',1,'{"question":"A paragraph says a town added bike lanes, recorded more bicycle trips, and reduced short car journeys. Which is a reasonable main idea?","choices":["bike lanes can encourage cycling for local trips","all residents now ride bikes","cars are never useful","the town has no traffic"],"answer":0,"explanation":""}'::jsonb,'9dc5f3e77529f3d80cc965f1f49f98bc','official',NULL,NULL,'Main Idea and Supporting Details'),
('original:ela--reading-informational-text--main-idea-and-supporting-details:ela--reading-informational-text--main-idea-and-supporting-details--10',1,'{"question":"Which question helps distinguish a main idea from a detail?","choices":["Which noun is longest?","How many sentences are in the paragraph?","What larger point do several details support?","What is the final punctuation mark?"],"answer":2,"explanation":""}'::jsonb,'99c32308124aa90e66db5043d815e47b','official',NULL,NULL,'Main Idea and Supporting Details'),
('original:ela--reading-informational-text--main-idea-and-supporting-details:ela--reading-informational-text--main-idea-and-supporting-details--11',1,'{"question":"A passage describes a problem, then explains two possible solutions. What main structure and idea should a summary preserve?","choices":["every adjective in the passage","the problem and the proposed responses","the author’s unrelated biography","only the final example"],"answer":1,"explanation":""}'::jsonb,'c5378ed7640e09355f2b0b9518a6d7bf','official',NULL,NULL,'Main Idea and Supporting Details'),
('original:ela--reading-informational-text--main-idea-and-supporting-details:ela--reading-informational-text--main-idea-and-supporting-details--12',1,'{"question":"A student’s summary includes every statistic but omits the text’s central claim. What is the main weakness?","choices":["it is too brief","it includes evidence","it is written in the student’s words","it lists details without capturing the main idea"],"answer":3,"explanation":""}'::jsonb,'1bf66d36d1da18d72733784d8fe25a8f','official',NULL,NULL,'Main Idea and Supporting Details'),
('original:ela--reading-informational-text--main-idea-and-supporting-details:ela--reading-informational-text--main-idea-and-supporting-details--13',1,'{"question":"A passage explains that wetlands absorb floodwater, filter pollutants, and support wildlife. Which detail best supports the idea that wetlands protect communities?","choices":["they are found in many regions","some plants grow there","wildlife uses the habitat","they absorb excess floodwater"],"answer":3,"explanation":""}'::jsonb,'529f79611f1332bba2314879bf298199','official',NULL,NULL,'Main Idea and Supporting Details'),
('original:ela--reading-informational-text--main-idea-and-supporting-details:ela--reading-informational-text--main-idea-and-supporting-details--14',1,'{"question":"A heading reads “Why Local Markets Matter.” The article discusses nearby farms, seasonal food, and community jobs. What is the likely central idea?","choices":["all markets sell identical goods","local markets can connect food, producers, and communities","farms are always small","food has no economic role"],"answer":1,"explanation":""}'::jsonb,'b6c94591454223f7f513608160b1af35','official',NULL,NULL,'Main Idea and Supporting Details'),
('original:ela--reading-informational-text--main-idea-and-supporting-details:ela--reading-informational-text--main-idea-and-supporting-details--15',1,'{"question":"A paragraph gives one example of a student learning guitar, then explains how repeated practice improves skills. Which statement is broader?","choices":["the student owns a guitar","one song was difficult","practice can help people develop a skill","the lesson was after school"],"answer":2,"explanation":""}'::jsonb,'1cdd61281325155fc58aa478af78ddb9','official',NULL,NULL,'Main Idea and Supporting Details'),
('original:ela--reading-informational-text--main-idea-and-supporting-details:ela--reading-informational-text--main-idea-and-supporting-details--16',1,'{"question":"A reader finds a detail that contradicts the paragraph’s central claim. What is a careful next step?","choices":["check how the detail is used and whether it qualifies the claim","ignore every other sentence","assume the author made an error","change the topic"],"answer":0,"explanation":""}'::jsonb,'1de931c204dc8b87b18505b3fa105aa9','official',NULL,NULL,'Main Idea and Supporting Details'),
('original:ela--reading-informational-text--main-idea-and-supporting-details:ela--reading-informational-text--main-idea-and-supporting-details--17',1,'{"question":"Two paragraphs describe different benefits of public parks. What can a reader do to form a larger central idea?","choices":["copy one detail only","combine the related points into a broader statement","treat the paragraphs as unrelated","use the title as the sole evidence"],"answer":1,"explanation":""}'::jsonb,'4e1dd8275d991cdbadd1b8bccbc423f7','official',NULL,NULL,'Main Idea and Supporting Details'),
('original:ela--reading-informational-text--main-idea-and-supporting-details:ela--reading-informational-text--main-idea-and-supporting-details--18',1,'{"question":"A passage’s opening sentence is a statistic, but later sentences explain its significance. What should a reader avoid?","choices":["looking for repeated concepts","connecting details","assuming the statistic alone is the main idea","summarizing the central point"],"answer":2,"explanation":""}'::jsonb,'da2697b166b5af1686c0b249090c1c0a','official',NULL,NULL,'Main Idea and Supporting Details'),
('original:ela--reading-informational-text--main-idea-and-supporting-details:ela--reading-informational-text--main-idea-and-supporting-details--19',1,'{"question":"Which summary best preserves a passage about a school garden used for science lessons, fresh produce, and teamwork?","choices":["The garden supports learning, food growing, and collaboration.","The garden has soil and several tools.","Students planted tomatoes on Tuesday.","Gardens are outside."],"answer":0,"explanation":""}'::jsonb,'5e39610652187048cba5fde44d9348f7','official',NULL,NULL,'Main Idea and Supporting Details'),
('original:ela--reading-informational-text--main-idea-and-supporting-details:ela--reading-informational-text--main-idea-and-supporting-details--20',1,'{"question":"A text includes many examples but returns repeatedly to the value of preserving local languages. What is probably central?","choices":["every language has the same number of speakers","examples are always the main idea","only written languages matter","preserving local languages matters to communities and culture"],"answer":3,"explanation":""}'::jsonb,'a16ca579ee94fdd1a561dcf2279c7cc3','official',NULL,NULL,'Main Idea and Supporting Details'),
('original:ela--reading-informational-text--inferences-and-textual-evidence:ela--reading-informational-text--inferences-and-textual-evidence--1',1,'{"question":"An inference is a conclusion reached by combining clues with what?","choices":["a random guess","a book’s page count","prior knowledge or reasoning","the author’s biography"],"answer":2,"explanation":""}'::jsonb,'0c6a757d15c896e6483b5a034ae3404f','official',NULL,NULL,'Inferences and Textual Evidence'),
('original:ela--reading-informational-text--inferences-and-textual-evidence:ela--reading-informational-text--inferences-and-textual-evidence--2',1,'{"question":"Textual evidence is information taken from where?","choices":["the text itself","a reader’s unrelated memory","a title alone","an opinion poll not mentioned"],"answer":0,"explanation":""}'::jsonb,'3a043349935c4ca45fe7f3b76b9570da','official',NULL,NULL,'Inferences and Textual Evidence'),
('original:ela--reading-informational-text--inferences-and-textual-evidence:ela--reading-informational-text--inferences-and-textual-evidence--3',1,'{"question":"“Wet footprints crossed the kitchen, and an open umbrella leaned by the door.” What is a reasonable inference?","choices":["the floor was just cleaned","the umbrella is broken","the kitchen is outdoors","someone came inside from the rain"],"answer":3,"explanation":""}'::jsonb,'ba3d44a5d5e1df9ae85ad32c53fc847e','official',NULL,NULL,'Inferences and Textual Evidence'),
('original:ela--reading-informational-text--inferences-and-textual-evidence:ela--reading-informational-text--inferences-and-textual-evidence--4',1,'{"question":"A character rereads a letter, folds it carefully, and puts it away. What can readers reasonably infer?","choices":["the letter is definitely a bill","the letter may be important to the character","the character cannot read","the story is nonfiction"],"answer":1,"explanation":""}'::jsonb,'cfdd344e400cd4b946fcc8926aff087a','official',NULL,NULL,'Inferences and Textual Evidence'),
('original:ela--reading-informational-text--inferences-and-textual-evidence:ela--reading-informational-text--inferences-and-textual-evidence--5',1,'{"question":"Which statement is best supported by a text showing a town adding benches and shade to a public plaza?","choices":["the town will become a major city","the town is making the plaza more comfortable for visitors","every resident requested benches","the plaza is open all night"],"answer":1,"explanation":""}'::jsonb,'2529577a5691d47f26c4bfa516e81b99','official',NULL,NULL,'Inferences and Textual Evidence'),
('original:ela--reading-informational-text--inferences-and-textual-evidence:ela--reading-informational-text--inferences-and-textual-evidence--6',1,'{"question":"A passage says a researcher repeated a test and got similar results. What inference is supported?","choices":["the result is certainly true in every case","the researcher made no measurements","the test had no variables","the result may be more consistent than a single trial"],"answer":3,"explanation":""}'::jsonb,'8ca092b6bfad7edc7b888c9f49a3c9a7','official',NULL,NULL,'Inferences and Textual Evidence'),
('original:ela--reading-informational-text--inferences-and-textual-evidence:ela--reading-informational-text--inferences-and-textual-evidence--7',1,'{"question":"A student claims a character is generous. Which evidence is strongest?","choices":["the character shares supplies with a new student","the character owns a large backpack","the character walks to school","another character has a different name"],"answer":0,"explanation":""}'::jsonb,'8ca46d49d633249a9ffe90719f1dadea','official',NULL,NULL,'Inferences and Textual Evidence'),
('original:ela--reading-informational-text--inferences-and-textual-evidence:ela--reading-informational-text--inferences-and-textual-evidence--8',1,'{"question":"Which is an inference rather than a directly stated fact?","choices":["The train arrives at 8:15.","The sign is green.","The character may be worried because she checks the clock repeatedly.","The room has three windows."],"answer":2,"explanation":""}'::jsonb,'ee2c561c1d4f03d80c908cd5754a1579','official',NULL,NULL,'Inferences and Textual Evidence'),
('original:ela--reading-informational-text--inferences-and-textual-evidence:ela--reading-informational-text--inferences-and-textual-evidence--9',1,'{"question":"A text reports that a shop’s sales rose after it extended its hours. What can readers infer cautiously?","choices":["longer hours may have contributed to the increase","longer hours were the only cause","every customer prefers night shopping","sales will keep rising forever"],"answer":0,"explanation":""}'::jsonb,'4ce710b80054533a74c71221f3812a5f','official',NULL,NULL,'Inferences and Textual Evidence'),
('original:ela--reading-informational-text--inferences-and-textual-evidence:ela--reading-informational-text--inferences-and-textual-evidence--10',1,'{"question":"A character says “I’m fine,” avoids eye contact, and leaves quickly after criticism. What is a reasonable inference?","choices":["the character is certainly delighted","the criticism was helpful","the character may feel upset","the scene occurs in winter"],"answer":2,"explanation":""}'::jsonb,'93f62a83f7ec6e81e20eed335d9f1071','official',NULL,NULL,'Inferences and Textual Evidence'),
('original:ela--reading-informational-text--inferences-and-textual-evidence:ela--reading-informational-text--inferences-and-textual-evidence--11',1,'{"question":"A passage states a bridge closed after inspectors found cracks. Which conclusion is supported?","choices":["the bridge will never reopen","safety concerns led to the closure","the bridge was built last year","no cars used it"],"answer":1,"explanation":""}'::jsonb,'e1aaeccbe31431a29ab47266523a6d6d','official',NULL,NULL,'Inferences and Textual Evidence'),
('original:ela--reading-informational-text--inferences-and-textual-evidence:ela--reading-informational-text--inferences-and-textual-evidence--12',1,'{"question":"A reader cites a sentence that does not address the claim. What is the issue?","choices":["the inference uses too many words","all evidence is subjective","the text has no details","the evidence is not relevant to the inference"],"answer":3,"explanation":""}'::jsonb,'57fa7cfe21c106442cc9dbdac2c8c209','official',NULL,NULL,'Inferences and Textual Evidence'),
('original:ela--reading-informational-text--inferences-and-textual-evidence:ela--reading-informational-text--inferences-and-textual-evidence--13',1,'{"question":"A student says “the speaker is angry” because the speaker uses a raised voice once. What additional evidence would strengthen the inference?","choices":["the passage’s page number","a description of the weather","the speaker’s age","repeated hostile words or actions across the passage"],"answer":3,"explanation":""}'::jsonb,'3189baf9eff2aa9cbf2d33e4e5a7cb1b','official',NULL,NULL,'Inferences and Textual Evidence'),
('original:ela--reading-informational-text--inferences-and-textual-evidence:ela--reading-informational-text--inferences-and-textual-evidence--14',1,'{"question":"A passage says attendance improved after a bus route changed, but does not mention other factors. What inference is appropriately cautious?","choices":["the route change caused every improvement","the route change may have helped attendance","the school has perfect attendance","the bus is always late"],"answer":1,"explanation":""}'::jsonb,'e113123cd0a38fd271ee5c2313090a4c','official',NULL,NULL,'Inferences and Textual Evidence'),
('original:ela--reading-informational-text--inferences-and-textual-evidence:ela--reading-informational-text--inferences-and-textual-evidence--15',1,'{"question":"A character returns a borrowed tool clean and repaired. Which trait is best supported?","choices":["impatience","dishonesty","responsibility","carelessness"],"answer":2,"explanation":""}'::jsonb,'21a7a379fc44a93d832a5ea5732077c2','official',NULL,NULL,'Inferences and Textual Evidence'),
('original:ela--reading-informational-text--inferences-and-textual-evidence:ela--reading-informational-text--inferences-and-textual-evidence--16',1,'{"question":"A text describes a garden with dry soil, drooping leaves, and a broken irrigation hose. Which inference is best supported?","choices":["the plants may not be receiving enough water","the garden is overwatered","winter has arrived","the plants are artificial"],"answer":0,"explanation":""}'::jsonb,'d0f8b9ac47902ea26022c1151e30a578','official',NULL,NULL,'Inferences and Textual Evidence'),
('original:ela--reading-informational-text--inferences-and-textual-evidence:ela--reading-informational-text--inferences-and-textual-evidence--17',1,'{"question":"A reader notices a claim has two supporting details and one exception. What should a strong interpretation do?","choices":["ignore the exception","account for both the support and the exception","treat one detail as proof of everything","replace evidence with opinion"],"answer":1,"explanation":""}'::jsonb,'de0e059e9d5456dce56cad4e229a08ba','official',NULL,NULL,'Inferences and Textual Evidence'),
('original:ela--reading-informational-text--inferences-and-textual-evidence:ela--reading-informational-text--inferences-and-textual-evidence--18',1,'{"question":"Which pairing best connects inference and evidence?","choices":["“She is famous” supported by her blue coat","“He is kind” supported by his name","“She may be nervous” supported by her shaking hands","“They are lost” supported by a sunny day"],"answer":2,"explanation":""}'::jsonb,'f3ad794fa2b5701be39da281890065e5','official',NULL,NULL,'Inferences and Textual Evidence'),
('original:ela--reading-informational-text--inferences-and-textual-evidence:ela--reading-informational-text--inferences-and-textual-evidence--19',1,'{"question":"A passage says a student practiced each afternoon and gradually improved on timed reading. What conclusion is best supported?","choices":["regular practice may have contributed to improvement","practice guarantees top scores for everyone","reading speed is fixed at birth","the student stopped practicing"],"answer":0,"explanation":""}'::jsonb,'5e20fb01552410fe5cc0a009826c0758','official',NULL,NULL,'Inferences and Textual Evidence'),
('original:ela--reading-informational-text--inferences-and-textual-evidence:ela--reading-informational-text--inferences-and-textual-evidence--20',1,'{"question":"An inference conflicts with a clear sentence in the passage. What should a reader do?","choices":["keep it because all interpretations are equal","ignore the sentence","cite an unrelated detail","revise the inference to fit the text"],"answer":3,"explanation":""}'::jsonb,'5369eb815dca542955268c2ba3fb61ff','official',NULL,NULL,'Inferences and Textual Evidence'),
('original:ela--reading-informational-text--informational-text-structures:ela--reading-informational-text--informational-text-structures--1',1,'{"question":"A text structure is the way information and ideas are what?","choices":["illustrated","spoken aloud","organized","alphabetized"],"answer":2,"explanation":""}'::jsonb,'37031572afcf9f814eba47b401991624','official',NULL,NULL,'Informational Text Structures'),
('original:ela--reading-informational-text--informational-text-structures:ela--reading-informational-text--informational-text-structures--2',1,'{"question":"A passage explains a problem and then presents possible solutions. Which structure is used?","choices":["problem and solution","chronological order","compare and contrast","description"],"answer":0,"explanation":""}'::jsonb,'50ba1ae7ef16a3a3471248c64f3d8ad1','official',NULL,NULL,'Informational Text Structures'),
('original:ela--reading-informational-text--informational-text-structures:ela--reading-informational-text--informational-text-structures--3',1,'{"question":"A text explains how two renewable energy sources are alike and different. Which structure fits?","choices":["cause and effect","sequence","problem and solution","compare and contrast"],"answer":3,"explanation":""}'::jsonb,'959ab8941baf85b278c5a3fbe7083c0c','official',NULL,NULL,'Informational Text Structures'),
('original:ela--reading-informational-text--informational-text-structures:ela--reading-informational-text--informational-text-structures--4',1,'{"question":"A passage traces the steps for safely using a microscope. What structure is most likely?","choices":["compare and contrast","sequence or process","cause and effect","problem and solution"],"answer":1,"explanation":""}'::jsonb,'fb70be7b16f8f56b19aba5d5f14cc149','official',NULL,NULL,'Informational Text Structures'),
('original:ela--reading-informational-text--informational-text-structures:ela--reading-informational-text--informational-text-structures--5',1,'{"question":"An article explains that heavy rain caused a stream to overflow. Which structure is shown?","choices":["description","cause and effect","chronological order only","compare and contrast"],"answer":1,"explanation":""}'::jsonb,'0dfe18413635d86588012d974771b239','official',NULL,NULL,'Informational Text Structures'),
('original:ela--reading-informational-text--informational-text-structures:ela--reading-informational-text--informational-text-structures--6',1,'{"question":"A paragraph lists the parts and features of a coral reef. Which structure is most likely?","choices":["problem and solution","cause and effect","sequence","description"],"answer":3,"explanation":""}'::jsonb,'720ce499df2375ad42817be20ba84237','official',NULL,NULL,'Informational Text Structures'),
('original:ela--reading-informational-text--informational-text-structures:ela--reading-informational-text--informational-text-structures--7',1,'{"question":"Words such as “first,” “next,” and “finally” often signal what?","choices":["sequence","compare and contrast","cause and effect","definition"],"answer":0,"explanation":""}'::jsonb,'864c5d05b7821b2387021bdda4f46037','official',NULL,NULL,'Informational Text Structures'),
('original:ela--reading-informational-text--informational-text-structures:ela--reading-informational-text--informational-text-structures--8',1,'{"question":"Words such as “because,” “therefore,” and “as a result” often signal what?","choices":["description","compare and contrast","cause and effect","sequence"],"answer":2,"explanation":""}'::jsonb,'9337a4051efc8a400cf49955b7f56a23','official',NULL,NULL,'Informational Text Structures'),
('original:ela--reading-informational-text--informational-text-structures:ela--reading-informational-text--informational-text-structures--9',1,'{"question":"A passage uses “both,” “however,” and “unlike” to discuss two animals. Which structure is likely?","choices":["compare and contrast","sequence","problem and solution","cause and effect"],"answer":0,"explanation":""}'::jsonb,'6118156ede0a458f78994fdfce9ccfcc','official',NULL,NULL,'Informational Text Structures'),
('original:ela--reading-informational-text--informational-text-structures:ela--reading-informational-text--informational-text-structures--10',1,'{"question":"A heading reads “Challenges of Urban Gardening” followed by “Ways to Improve Soil.” What organization is suggested?","choices":["chronology","compare and contrast","problem and solution","cause and effect"],"answer":2,"explanation":""}'::jsonb,'8baf83dbd91d66073bc3b3e64baa07f5','official',NULL,NULL,'Informational Text Structures'),
('original:ela--reading-informational-text--informational-text-structures:ela--reading-informational-text--informational-text-structures--11',1,'{"question":"A biography describes events from childhood through adulthood. Which structure is primarily used?","choices":["compare and contrast","chronological order","description","problem and solution"],"answer":1,"explanation":""}'::jsonb,'bb8cc0c0d1bedec9ebdfbd336238aee1','official',NULL,NULL,'Informational Text Structures'),
('original:ela--reading-informational-text--informational-text-structures:ela--reading-informational-text--informational-text-structures--12',1,'{"question":"A passage describes a drought, then lists its effects on farms and reservoirs. What structure is emphasized?","choices":["compare and contrast","sequence","definition","cause and effect"],"answer":3,"explanation":""}'::jsonb,'dca72d7a71736c51e2eb5154a46874a1','official',NULL,NULL,'Informational Text Structures'),
('original:ela--reading-informational-text--informational-text-structures:ela--reading-informational-text--informational-text-structures--13',1,'{"question":"A chapter explains “ecosystem,” then gives its components and examples. Which structure is likely?","choices":["problem and solution","chronology","cause and effect","definition and description"],"answer":3,"explanation":""}'::jsonb,'2f356514f86c388c0fa700697b37df05','official',NULL,NULL,'Informational Text Structures'),
('original:ela--reading-informational-text--informational-text-structures:ela--reading-informational-text--informational-text-structures--14',1,'{"question":"An article alternates between the benefits and drawbacks of two transportation options. What structure supports that purpose?","choices":["sequence","compare and contrast","cause and effect","problem and solution"],"answer":1,"explanation":""}'::jsonb,'667a248a5e76d8f1ae38f7f299e8c52e','official',NULL,NULL,'Informational Text Structures'),
('original:ela--reading-informational-text--informational-text-structures:ela--reading-informational-text--informational-text-structures--15',1,'{"question":"A writer describes a community’s recycling problem and evaluates collection programs. How is the information organized?","choices":["chronological order","description","problem and solution","compare and contrast"],"answer":2,"explanation":""}'::jsonb,'6f38fdca7ddbbcaf060479b0659708fe','official',NULL,NULL,'Informational Text Structures'),
('original:ela--reading-informational-text--informational-text-structures:ela--reading-informational-text--informational-text-structures--16',1,'{"question":"A student sees the words “after” and “later” and assumes a cause-and-effect structure. What should the student check?","choices":["whether the text explains causation or only time order","whether the passage has a title","whether the writer uses first person","whether the topic is familiar"],"answer":0,"explanation":""}'::jsonb,'dd9803dd8828cd3f97ce31a1a862bd78','official',NULL,NULL,'Informational Text Structures'),
('original:ela--reading-informational-text--informational-text-structures:ela--reading-informational-text--informational-text-structures--17',1,'{"question":"A passage has a list of steps but also explains what happens if one is skipped. What can a reader conclude?","choices":["it cannot have a structure","sequence may be combined with cause and effect","it is necessarily compare and contrast","it is only description"],"answer":1,"explanation":""}'::jsonb,'8d05a785f139c75f17bbbb807b26ef14','official',NULL,NULL,'Informational Text Structures'),
('original:ela--reading-informational-text--informational-text-structures:ela--reading-informational-text--informational-text-structures--18',1,'{"question":"An article first describes two regions separately, then compares their climates. Which statement is precise?","choices":["the text is only chronological","the article has no organization","the text combines description and comparison","the comparison is a solution"],"answer":2,"explanation":""}'::jsonb,'8a02294a7f14d27c00e47e508c529519','official',NULL,NULL,'Informational Text Structures'),
('original:ela--reading-informational-text--informational-text-structures:ela--reading-informational-text--informational-text-structures--19',1,'{"question":"A student summarizes a process text by listing background facts but omitting the steps. What did the summary miss?","choices":["the sequence central to the author’s explanation","a character’s point of view","the poem’s rhyme","the text’s setting"],"answer":0,"explanation":""}'::jsonb,'06f217e829c96b81317011574f863c39','official',NULL,NULL,'Informational Text Structures'),
('original:ela--reading-informational-text--informational-text-structures:ela--reading-informational-text--informational-text-structures--20',1,'{"question":"A passage states that a new schedule reduced wait times, then explains how. Which organization is most apparent?","choices":["compare and contrast","description","sequence only","cause and effect"],"answer":3,"explanation":""}'::jsonb,'3b6c8fb4435886143c817c68523049f2','official',NULL,NULL,'Informational Text Structures'),
('original:ela--research-argument-media-literacy--analyzing-arguments-and-evidence:ela--research-argument-media-literacy--analyzing-arguments-and-evidence--1',1,'{"question":"An argument is a claim supported by what?","choices":["a title and illustration","a list of unrelated facts","reasons and evidence","a personal preference alone"],"answer":2,"explanation":""}'::jsonb,'0099af74ac7af2efa0cfbb33de324b00','official',NULL,NULL,'Analyzing Arguments and Evidence'),
('original:ela--research-argument-media-literacy--analyzing-arguments-and-evidence:ela--research-argument-media-literacy--analyzing-arguments-and-evidence--2',1,'{"question":"A claim is best described as what?","choices":["a position that can be supported with reasons","an example that proves every point","a source citation","a question with no answer"],"answer":0,"explanation":""}'::jsonb,'7148613d1e43a725ca9635ef72b3a606','official',NULL,NULL,'Analyzing Arguments and Evidence'),
('original:ela--research-argument-media-literacy--analyzing-arguments-and-evidence:ela--research-argument-media-literacy--analyzing-arguments-and-evidence--3',1,'{"question":"Evidence is relevant when it does what?","choices":["comes from the longest source","repeats the claim word for word","uses technical language","directly supports the claim or reason"],"answer":3,"explanation":""}'::jsonb,'5947c4671f6dc1721d2317e6b2ff84d0','official',NULL,NULL,'Analyzing Arguments and Evidence'),
('original:ela--research-argument-media-literacy--analyzing-arguments-and-evidence:ela--research-argument-media-literacy--analyzing-arguments-and-evidence--4',1,'{"question":"A school newsletter claims later start times help students and cites a local attendance study. What is the study’s role?","choices":["the conclusion","evidence supporting the claim","a counterclaim","the topic sentence only"],"answer":1,"explanation":""}'::jsonb,'c24be81602aedc487f549e8c58990858','official',NULL,NULL,'Analyzing Arguments and Evidence'),
('original:ela--research-argument-media-literacy--analyzing-arguments-and-evidence:ela--research-argument-media-literacy--analyzing-arguments-and-evidence--5',1,'{"question":"A writer says, “The park should add lights because visitors leave early when it gets dark.” Which part is the claim?","choices":["visitors leave early","The park should add lights.","when it gets dark","because"],"answer":1,"explanation":""}'::jsonb,'279e80537dabbb4bc3f6aacb9401a78e','official',NULL,NULL,'Analyzing Arguments and Evidence'),
('original:ela--research-argument-media-literacy--analyzing-arguments-and-evidence:ela--research-argument-media-literacy--analyzing-arguments-and-evidence--6',1,'{"question":"A counterclaim is what?","choices":["a second example supporting the same reason","the author’s final sentence","a fact that cannot be checked","a different position that an argument addresses"],"answer":3,"explanation":""}'::jsonb,'0f180b4e298a1a8f63421032008cd5aa','official',NULL,NULL,'Analyzing Arguments and Evidence'),
('original:ela--research-argument-media-literacy--analyzing-arguments-and-evidence:ela--research-argument-media-literacy--analyzing-arguments-and-evidence--7',1,'{"question":"A rebuttal responds to a counterclaim by doing what?","choices":["explaining why it is limited or less convincing","repeating it without comment","changing the topic","listing unrelated facts"],"answer":0,"explanation":""}'::jsonb,'2a3d76ef38ef1d8a3643ffc5e0685040','official',NULL,NULL,'Analyzing Arguments and Evidence'),
('original:ela--research-argument-media-literacy--analyzing-arguments-and-evidence:ela--research-argument-media-literacy--analyzing-arguments-and-evidence--8',1,'{"question":"Which is the strongest evidence for a claim about local bus delays?","choices":["one person’s memory of a ride years ago","a slogan about transportation","a recent log of arrival times from the bus system","a photograph of a bus"],"answer":2,"explanation":""}'::jsonb,'1796a76e6230e260bdbf370e9b96a459','official',NULL,NULL,'Analyzing Arguments and Evidence'),
('original:ela--research-argument-media-literacy--analyzing-arguments-and-evidence:ela--research-argument-media-literacy--analyzing-arguments-and-evidence--9',1,'{"question":"A writer claims daily reading improves vocabulary, then cites a study tracking students over a semester. What makes the evidence useful?","choices":["it directly relates to the claim and gives observed information","it is emotionally powerful","it is the writer’s favorite study","it proves every student learns identically"],"answer":0,"explanation":""}'::jsonb,'4742ef1a352a46a4e6012c1771c64fae','official',NULL,NULL,'Analyzing Arguments and Evidence'),
('original:ela--research-argument-media-literacy--analyzing-arguments-and-evidence:ela--research-argument-media-literacy--analyzing-arguments-and-evidence--10',1,'{"question":"A survey of ten friends is used to claim that all teenagers prefer online books. What is the main weakness?","choices":["the claim is written in a sentence","the survey includes teenagers","the sample may be too small and unrepresentative","the topic concerns books"],"answer":2,"explanation":""}'::jsonb,'2a7bcac995ed5011254751e568a72b71','official',NULL,NULL,'Analyzing Arguments and Evidence'),
('original:ela--research-argument-media-literacy--analyzing-arguments-and-evidence:ela--research-argument-media-literacy--analyzing-arguments-and-evidence--11',1,'{"question":"A source reports that students who join a club also earn higher grades. What should an argument avoid assuming without more evidence?","choices":["the two measures are related in the sample","club participation alone caused the higher grades","the report includes students","grades can be measured"],"answer":1,"explanation":""}'::jsonb,'581c3222bbc67ae0e24b378744e1d8ab','official',NULL,NULL,'Analyzing Arguments and Evidence'),
('original:ela--research-argument-media-literacy--analyzing-arguments-and-evidence:ela--research-argument-media-literacy--analyzing-arguments-and-evidence--12',1,'{"question":"A claim is supported only by examples from one unusual case. What should a reader question?","choices":["whether the writer used a title","whether examples are always allowed","whether the claim is a sentence","whether the evidence is sufficient and representative"],"answer":3,"explanation":""}'::jsonb,'ab29a3808ed123f43f93c0fc9e1a7c67','official',NULL,NULL,'Analyzing Arguments and Evidence'),
('original:ela--research-argument-media-literacy--analyzing-arguments-and-evidence:ela--research-argument-media-literacy--analyzing-arguments-and-evidence--13',1,'{"question":"Which statement is a counterclaim to “The town should build a new bike path”?","choices":["A new path could connect two neighborhoods.","More residents ride bikes in summer.","The path would be near the library.","Existing streets already have safe bike lanes on most routes."],"answer":3,"explanation":""}'::jsonb,'3d009322df3cd751c9ad32d614e147e7','official',NULL,NULL,'Analyzing Arguments and Evidence'),
('original:ela--research-argument-media-literacy--analyzing-arguments-and-evidence:ela--research-argument-media-literacy--analyzing-arguments-and-evidence--14',1,'{"question":"A writer responds to the counterclaim by citing crash reports from streets without bike lanes. What is this response?","choices":["an unrelated anecdote","a rebuttal supported with evidence","a topic sentence only","an appeal to popularity"],"answer":1,"explanation":""}'::jsonb,'acd692a59576542f3e4c698aa80b6866','official',NULL,NULL,'Analyzing Arguments and Evidence'),
('original:ela--research-argument-media-literacy--analyzing-arguments-and-evidence:ela--research-argument-media-literacy--analyzing-arguments-and-evidence--15',1,'{"question":"A report uses a graph showing fewer injuries after a safety rule began. What question helps assess the argument?","choices":["Is the graph printed in color?","Does the report have a long title?","Could other changes also explain the decline?","Is the rule easy to spell?"],"answer":2,"explanation":""}'::jsonb,'ba3d8985793074ce5c3932804c2510ea','official',NULL,NULL,'Analyzing Arguments and Evidence'),
('original:ela--research-argument-media-literacy--analyzing-arguments-and-evidence:ela--research-argument-media-literacy--analyzing-arguments-and-evidence--16',1,'{"question":"An argument includes accurate facts that do not address its claim. How should the evidence be judged?","choices":["factual but irrelevant","relevant and sufficient","emotional and false","conclusive by itself"],"answer":0,"explanation":""}'::jsonb,'b8488303dda8a52564678426a42af57c','official',NULL,NULL,'Analyzing Arguments and Evidence'),
('original:ela--research-argument-media-literacy--analyzing-arguments-and-evidence:ela--research-argument-media-literacy--analyzing-arguments-and-evidence--17',1,'{"question":"A writer presents only examples that support a position and omits known contrary findings. What concern arises?","choices":["balanced reasoning","selective use of evidence","precise citation","clear organization"],"answer":1,"explanation":""}'::jsonb,'33195117a95657fc28de9bfc23fabc3f','official',NULL,NULL,'Analyzing Arguments and Evidence'),
('original:ela--research-argument-media-literacy--analyzing-arguments-and-evidence:ela--research-argument-media-literacy--analyzing-arguments-and-evidence--18',1,'{"question":"A claim says “every student benefits,” but evidence comes from one classroom. What adjustment would make the claim more responsible?","choices":["keep the claim and remove the evidence","add an unrelated quotation","narrow the claim or provide broader evidence","replace evidence with a slogan"],"answer":2,"explanation":""}'::jsonb,'ef83e6d8f8761664a0766b723eea08ae','official',NULL,NULL,'Analyzing Arguments and Evidence'),
('original:ela--research-argument-media-literacy--analyzing-arguments-and-evidence:ela--research-argument-media-literacy--analyzing-arguments-and-evidence--19',1,'{"question":"Which argument is best supported?","choices":["“The library should extend hours; visitor counts show demand during the final hour.”","“The library should extend hours because libraries are nice.”","“Everyone agrees, so it must be right.”","“More books exist than yesterday, therefore hours should change.”"],"answer":0,"explanation":""}'::jsonb,'d00911cdde6399b221c0fdeac732cfdb','official',NULL,NULL,'Analyzing Arguments and Evidence'),
('original:ela--research-argument-media-literacy--analyzing-arguments-and-evidence:ela--research-argument-media-literacy--analyzing-arguments-and-evidence--20',1,'{"question":"A source finds a correlation between screen time and sleep, but cannot show which caused the other. What is a careful conclusion?","choices":["screen time always causes poor sleep","sleep causes all screen use","the study is useless","the variables are associated, but causation is not established"],"answer":3,"explanation":""}'::jsonb,'9d9b593e59a8b8cda86dd256456eb983','official',NULL,NULL,'Analyzing Arguments and Evidence'),
('original:ela--research-argument-media-literacy--rhetorical-appeals-and-persuasive-techniques:ela--research-argument-media-literacy--rhetorical-appeals-and-persuasive-techniques--1',1,'{"question":"An appeal to ethos focuses on a speaker’s what?","choices":["emotional response","logical structure","credibility or character","word origins"],"answer":2,"explanation":""}'::jsonb,'901199505583a88c39e1ffa0e3d1c35a','official',NULL,NULL,'Rhetorical Appeals and Persuasive Techniques'),
('original:ela--research-argument-media-literacy--rhetorical-appeals-and-persuasive-techniques:ela--research-argument-media-literacy--rhetorical-appeals-and-persuasive-techniques--2',1,'{"question":"An appeal to pathos seeks to influence the audience’s what?","choices":["emotions","source credibility","sentence length","factual accuracy alone"],"answer":0,"explanation":""}'::jsonb,'bd55bad13fad7031f02c6962204693f9','official',NULL,NULL,'Rhetorical Appeals and Persuasive Techniques'),
('original:ela--research-argument-media-literacy--rhetorical-appeals-and-persuasive-techniques:ela--research-argument-media-literacy--rhetorical-appeals-and-persuasive-techniques--3',1,'{"question":"An appeal to logos relies primarily on what?","choices":["the speaker’s clothing","emotional imagery only","repetition without reasons","reasoning and evidence"],"answer":3,"explanation":""}'::jsonb,'7d1967390e96a759580e642d405ad7da','official',NULL,NULL,'Rhetorical Appeals and Persuasive Techniques'),
('original:ela--research-argument-media-literacy--rhetorical-appeals-and-persuasive-techniques:ela--research-argument-media-literacy--rhetorical-appeals-and-persuasive-techniques--4',1,'{"question":"A doctor explains relevant training before discussing a health issue. Which appeal is emphasized?","choices":["pathos","ethos","logos","irony"],"answer":1,"explanation":""}'::jsonb,'2db3d8ae02131c20596638fafe11e749','official',NULL,NULL,'Rhetorical Appeals and Persuasive Techniques'),
('original:ela--research-argument-media-literacy--rhetorical-appeals-and-persuasive-techniques:ela--research-argument-media-literacy--rhetorical-appeals-and-persuasive-techniques--5',1,'{"question":"A speaker describes families affected by a flood to encourage donations. Which appeal is prominent?","choices":["ethos","pathos","logos","definition"],"answer":1,"explanation":""}'::jsonb,'12b2a566f945dbafad271fa609c81702','official',NULL,NULL,'Rhetorical Appeals and Persuasive Techniques'),
('original:ela--research-argument-media-literacy--rhetorical-appeals-and-persuasive-techniques:ela--research-argument-media-literacy--rhetorical-appeals-and-persuasive-techniques--6',1,'{"question":"A writer uses a comparison of costs and savings to support a proposal. Which appeal is used?","choices":["pathos","ethos","allusion","logos"],"answer":3,"explanation":""}'::jsonb,'8fecd6832f857d34435038b07e8771ca','official',NULL,NULL,'Rhetorical Appeals and Persuasive Techniques'),
('original:ela--research-argument-media-literacy--rhetorical-appeals-and-persuasive-techniques:ela--research-argument-media-literacy--rhetorical-appeals-and-persuasive-techniques--7',1,'{"question":"A campaign says, “Nine out of ten riders use helmets,” and provides its survey method. Which appeal is strongest?","choices":["logos","pathos","ethos","hyperbole"],"answer":0,"explanation":""}'::jsonb,'a3e9b941cb1f3d258f1105c53cb80685','official',NULL,NULL,'Rhetorical Appeals and Persuasive Techniques'),
('original:ela--research-argument-media-literacy--rhetorical-appeals-and-persuasive-techniques:ela--research-argument-media-literacy--rhetorical-appeals-and-persuasive-techniques--8',1,'{"question":"A local coach describes personal experience with youth sports before recommending safer equipment. What may strengthen the appeal?","choices":["a dramatic soundtrack","a long unrelated biography","relevant experience that supports credibility","an insult toward critics"],"answer":2,"explanation":""}'::jsonb,'e32331072daa7cfb1c971d94043fd59f','official',NULL,NULL,'Rhetorical Appeals and Persuasive Techniques'),
('original:ela--research-argument-media-literacy--rhetorical-appeals-and-persuasive-techniques:ela--research-argument-media-literacy--rhetorical-appeals-and-persuasive-techniques--9',1,'{"question":"A charity ad shows a lost pet and asks viewers to help shelters. Which response is it designed to evoke?","choices":["empathy or concern","trust in a statistician","agreement through a syllogism","awareness of a definition"],"answer":0,"explanation":""}'::jsonb,'756ca2c0b1063a450c97dd79b3d7b296','official',NULL,NULL,'Rhetorical Appeals and Persuasive Techniques'),
('original:ela--research-argument-media-literacy--rhetorical-appeals-and-persuasive-techniques:ela--research-argument-media-literacy--rhetorical-appeals-and-persuasive-techniques--10',1,'{"question":"A speaker cites a well-designed study and explains its limits. Which combination is most evident?","choices":["pathos without evidence","irony and symbolism","logos with careful credibility","repetition alone"],"answer":2,"explanation":""}'::jsonb,'39b0f4a1c823c4a79edf763244333517','official',NULL,NULL,'Rhetorical Appeals and Persuasive Techniques'),
('original:ela--research-argument-media-literacy--rhetorical-appeals-and-persuasive-techniques:ela--research-argument-media-literacy--rhetorical-appeals-and-persuasive-techniques--11',1,'{"question":"A writer says, “Everyone is buying this phone, so you should too.” Which technique is used?","choices":["expert testimony","bandwagon appeal","cause-and-effect proof","counterclaim"],"answer":1,"explanation":""}'::jsonb,'eba9d3a9296648b8f50ee7300c421a54','official',NULL,NULL,'Rhetorical Appeals and Persuasive Techniques'),
('original:ela--research-argument-media-literacy--rhetorical-appeals-and-persuasive-techniques:ela--research-argument-media-literacy--rhetorical-appeals-and-persuasive-techniques--12',1,'{"question":"A product ad says it is “the choice of champions” but gives no supporting data. What should a critical reader ask?","choices":["how many colors the ad uses","whether champions exist","whether the slogan rhymes","what evidence supports the implied endorsement"],"answer":3,"explanation":""}'::jsonb,'e021b214eb91e122ebeace2e70069504','official',NULL,NULL,'Rhetorical Appeals and Persuasive Techniques'),
('original:ela--research-argument-media-literacy--rhetorical-appeals-and-persuasive-techniques:ela--research-argument-media-literacy--rhetorical-appeals-and-persuasive-techniques--13',1,'{"question":"A speaker repeats “We can make the river clean” at the start of several sentences. What technique is this?","choices":["counterclaim","statistical sampling","definition","repetition for emphasis"],"answer":3,"explanation":""}'::jsonb,'44233a031676b60168c0210954e2a904','official',NULL,NULL,'Rhetorical Appeals and Persuasive Techniques'),
('original:ela--research-argument-media-literacy--rhetorical-appeals-and-persuasive-techniques:ela--research-argument-media-literacy--rhetorical-appeals-and-persuasive-techniques--14',1,'{"question":"A writer calls a small fee “a mountain of debt.” What technique may be at work?","choices":["precise measurement","hyperbole","neutral definition","expert testimony"],"answer":1,"explanation":""}'::jsonb,'94489304af02d154c6620902770a9602','official',NULL,NULL,'Rhetorical Appeals and Persuasive Techniques'),
('original:ela--research-argument-media-literacy--rhetorical-appeals-and-persuasive-techniques:ela--research-argument-media-literacy--rhetorical-appeals-and-persuasive-techniques--15',1,'{"question":"A presenter names a real expert whose research directly concerns the topic. What can this support?","choices":["pathos only","a straw man","ethos","bandwagon"],"answer":2,"explanation":""}'::jsonb,'e83b761d038110febea975c60e2d9284','official',NULL,NULL,'Rhetorical Appeals and Persuasive Techniques'),
('original:ela--research-argument-media-literacy--rhetorical-appeals-and-persuasive-techniques:ela--research-argument-media-literacy--rhetorical-appeals-and-persuasive-techniques--16',1,'{"question":"A speech uses vivid descriptions of a damaged forest alongside data on water quality. Which pairing is used?","choices":["pathos and logos","ethos and irony","bandwagon and allusion","hyperbole and definition"],"answer":0,"explanation":""}'::jsonb,'cb66b75533a3b050cb2ee9693b7760b5','official',NULL,NULL,'Rhetorical Appeals and Persuasive Techniques')
insert into public.question_content_versions(source_key,version_number,question,content_hash,source_type,creator_id,source_set_id,source_title) values
('original:ela--research-argument-media-literacy--rhetorical-appeals-and-persuasive-techniques:ela--research-argument-media-literacy--rhetorical-appeals-and-persuasive-techniques--17',1,'{"question":"A writer attacks an opponent’s character instead of addressing the opponent’s evidence. What fallacy is this?","choices":["hasty generalization","ad hominem","false dilemma","appeal to authority"],"answer":1,"explanation":""}'::jsonb,'12a35d3a0404918264b4b39f83f989d2','official',NULL,NULL,'Rhetorical Appeals and Persuasive Techniques'),
('original:ela--research-argument-media-literacy--rhetorical-appeals-and-persuasive-techniques:ela--research-argument-media-literacy--rhetorical-appeals-and-persuasive-techniques--18',1,'{"question":"A speaker presents only two choices when several reasonable options exist. What reasoning flaw may this be?","choices":["bandwagon","expert testimony","false dilemma","rhetorical question"],"answer":2,"explanation":""}'::jsonb,'08754cf2eb1d6fdbaa5e2ca9266cfcef','official',NULL,NULL,'Rhetorical Appeals and Persuasive Techniques'),
('original:ela--research-argument-media-literacy--rhetorical-appeals-and-persuasive-techniques:ela--research-argument-media-literacy--rhetorical-appeals-and-persuasive-techniques--19',1,'{"question":"A persuasive question is asked to make a point rather than receive an answer. What is it?","choices":["rhetorical question","counterclaim","citation","analogy"],"answer":0,"explanation":""}'::jsonb,'4ce323a605a3bbdc6726e64f10e97af7','official',NULL,NULL,'Rhetorical Appeals and Persuasive Techniques'),
