('original:ela--language-grammar-vocabulary--sentence-structure:ela--language-grammar-vocabulary--sentence-structure--1',1,'{"question":"A simple sentence contains what?","choices":["two dependent clauses","no subject","one independent clause","two independent clauses joined by a conjunction"],"answer":2,"explanation":""}'::jsonb,'3cbacaf84203a8817df6101d9b946bcb','official',NULL,NULL,'Sentence Structure'),
