('original:ela--reading-informational-text--fact-opinion-bias:ela--reading-informational-text--fact-opinion-bias--6',1,'{"question":"A poll of 20 volunteers at a sports event is used to describe all residents. What is the main concern?","choices":["The poll has too many respondents","The sample may not represent the full population","Volunteers cannot answer questions","Residents have no opinions"],"answer":1,"explanation":""}'::jsonb,'551b07568bb903ddaefba960319c335a','official',NULL,NULL,'Fact, Opinion & Bias'),
('original:ela--reading-informational-text--fact-opinion-bias:ela--reading-informational-text--fact-opinion-bias--7',1,'{"question":"Which sentence combines a fact with an opinion?","choices":["The park has three courts","The park opened last summer","The park has three courts, making it the city''s finest recreation space","The park is located beside the school"],"answer":2,"explanation":""}'::jsonb,'7e746398f53e41c92f0978506d0cac07','official',NULL,NULL,'Fact, Opinion & Bias'),
('original:ela--reading-informational-text--fact-opinion-bias:ela--reading-informational-text--fact-opinion-bias--8',1,'{"question":"A product page reports only positive customer reviews and omits how reviews were selected. What should a reader ask?","choices":["Whether every product has a page","Whether the page has a title","Whether the reviews use complete sentences","Whether the reviews are representative and what evidence was left out"],"answer":3,"explanation":""}'::jsonb,'ca3548d833d80087223256bfe1364a52','official',NULL,NULL,'Fact, Opinion & Bias'),
('original:ela--reading-informational-text--fact-opinion-bias:ela--reading-informational-text--fact-opinion-bias--9',1,'{"question":"Which phrase most clearly signals an opinion?","choices":["The most effective solution","At a distance of two kilometers","On September 14","According to the posted data"],"answer":0,"explanation":""}'::jsonb,'315d7458fb47f3553f1b59a6aa321f85','official',NULL,NULL,'Fact, Opinion & Bias'),
('original:ela--reading-informational-text--fact-opinion-bias:ela--reading-informational-text--fact-opinion-bias--10',1,'{"question":"A chart begins its vertical axis at 95 rather than zero, making a small difference look large. What should readers examine?","choices":["The color of the chart title","The scale and how it affects the visual comparison","Whether the chart has a caption","The alphabetical order of labels"],"answer":1,"explanation":""}'::jsonb,'9cd8957c7b3bc3911f0f4913fe906a89','official',NULL,NULL,'Fact, Opinion & Bias'),
('original:ela--reading-informational-text--fact-opinion-bias:ela--reading-informational-text--fact-opinion-bias--11',1,'{"question":"An author describes one group as ''concerned residents'' and another as ''complainers.'' What does this wording suggest?","choices":["A neutral comparison of both groups","A verified count of participants","Uneven framing that may reveal bias","An explanation of the issue''s timeline"],"answer":2,"explanation":""}'::jsonb,'e9728bf84c6aed77daf2f76a04fdabbf','official',NULL,NULL,'Fact, Opinion & Bias'),
('original:ela--reading-informational-text--fact-opinion-bias:ela--reading-informational-text--fact-opinion-bias--12',1,'{"question":"Which evidence best supports an objective claim that a bus route became faster?","choices":["A rider''s statement that it feels faster","A campaign slogan about efficiency","A photograph of the bus","Recorded travel times from comparable trips before and after the change"],"answer":3,"explanation":""}'::jsonb,'7ae7a8231631f9f36d097dc1b2ac92c5','official',NULL,NULL,'Fact, Opinion & Bias'),
('original:ela--reading-informational-text--fact-opinion-bias:ela--reading-informational-text--fact-opinion-bias--13',1,'{"question":"A claim is repeated by many websites, all citing the same original post. What does this indicate?","choices":["Repetition does not equal independent confirmation","The claim is proven by the number of pages","The original post is necessarily false","Each website conducted a new study"],"answer":0,"explanation":""}'::jsonb,'4a27f394e75c2921156b643fb83e5035','official',NULL,NULL,'Fact, Opinion & Bias'),
('original:ela--reading-informational-text--fact-opinion-bias:ela--reading-informational-text--fact-opinion-bias--14',1,'{"question":"Which question helps distinguish an opinion from a fact?","choices":["Does the statement sound confident?","Can reliable evidence verify the statement as written?","Is the statement printed in a large font?","Does the author agree with me?"],"answer":1,"explanation":""}'::jsonb,'492e60bde617f2d045b958b478b61a4d','official',NULL,NULL,'Fact, Opinion & Bias'),
('original:ela--reading-informational-text--fact-opinion-bias:ela--reading-informational-text--fact-opinion-bias--15',1,'{"question":"A report describes a policy''s costs but not its benefits. What is a fair next step?","choices":["Assume the policy has no benefits","Reject every fact in the report","Seek additional sources that examine the omitted side","Repeat the report''s conclusion"],"answer":2,"explanation":""}'::jsonb,'8caca85dce1cc251ad557bd686a2b121','official',NULL,NULL,'Fact, Opinion & Bias'),
('original:ela--reading-informational-text--fact-opinion-bias:ela--reading-informational-text--fact-opinion-bias--16',1,'{"question":"An influencer recommends a product and receives payment from its seller. What should readers consider?","choices":["Payment guarantees the product works","The recommendation is a scientific study","The seller cannot be identified","The financial relationship may affect how the recommendation is presented"],"answer":3,"explanation":""}'::jsonb,'2ed3da9e0207ecedbde79c88d420764a','official',NULL,NULL,'Fact, Opinion & Bias'),
('original:ela--reading-informational-text--fact-opinion-bias:ela--reading-informational-text--fact-opinion-bias--17',1,'{"question":"Which sentence is most clearly an observable fact?","choices":["The container holds 500 milliliters","The container is unattractive","The container is too large","The container is the best choice"],"answer":0,"explanation":""}'::jsonb,'dee5d0f9bdb6febd1cae87396e2c2556','official',NULL,NULL,'Fact, Opinion & Bias'),
('original:ela--reading-informational-text--fact-opinion-bias:ela--reading-informational-text--fact-opinion-bias--18',1,'{"question":"A writer uses only examples that support a claim while ignoring stronger contrary evidence. This is","choices":["a random sample","cherry-picking evidence","a neutral summary","a controlled variable"],"answer":1,"explanation":""}'::jsonb,'1c155fd09b8b262b413d4c6e9e3cf302','official',NULL,NULL,'Fact, Opinion & Bias'),
('original:ela--reading-informational-text--fact-opinion-bias:ela--reading-informational-text--fact-opinion-bias--19',1,'{"question":"Why should a reader separate a source''s evidence from its conclusion?","choices":["Evidence always proves every conclusion","Conclusions are always facts","The conclusion may extend beyond what the evidence supports","Evidence cannot be interpreted"],"answer":2,"explanation":""}'::jsonb,'be03276b63daeb16303e731a2a7f6387','official',NULL,NULL,'Fact, Opinion & Bias'),
('original:ela--reading-informational-text--fact-opinion-bias:ela--reading-informational-text--fact-opinion-bias--20',1,'{"question":"Two reports give different estimates because they use different date ranges. What should a reader compare?","choices":["Their website colors","The authors'' preferred headlines","The number of images","Their methods and the time periods measured"],"answer":3,"explanation":""}'::jsonb,'872759b5a40752fd40d46c332869b035','official',NULL,NULL,'Fact, Opinion & Bias'),
('original:ela--research-argument-media-literacy--note-taking-organizers:ela--research-argument-media-literacy--note-taking-organizers--1',1,'{"question":"What is the main purpose of taking notes while reading or listening?","choices":["Capture useful ideas in a form that supports later understanding or work","Copy every word without selecting information","Replace reading or listening entirely","Record only the source''s title"],"answer":0,"explanation":""}'::jsonb,'4351428c0b243e32e6762147826d78f6','official',NULL,NULL,'Note-Taking & Organizers'),
('original:ela--research-argument-media-literacy--note-taking-organizers:ela--research-argument-media-literacy--note-taking-organizers--2',1,'{"question":"Which note is most useful for distinguishing a source''s claim from its evidence?","choices":["School gardens","Claim: school gardens improve access; evidence: harvest records from three years","Very interesting","Page 4"],"answer":1,"explanation":""}'::jsonb,'0282ce975b6e3531524021304bdcdf5a','official',NULL,NULL,'Note-Taking & Organizers'),
('original:ela--research-argument-media-literacy--note-taking-organizers:ela--research-argument-media-literacy--note-taking-organizers--3',1,'{"question":"A student copies a paragraph into notes without quotation marks or a citation. What is the risk?","choices":["The notes will become too concise","The source will be easier to verify","The copied language may later be mistaken for the student''s own writing","The main idea will be stated more clearly"],"answer":2,"explanation":""}'::jsonb,'48a38554cf96448bcb1c71d1bd8ef950','official',NULL,NULL,'Note-Taking & Organizers'),
('original:ela--research-argument-media-literacy--note-taking-organizers:ela--research-argument-media-literacy--note-taking-organizers--4',1,'{"question":"Which organizer is best for comparing two proposed solutions across cost, time, and impact?","choices":["A plot diagram","A calendar with no labels","A single-column glossary","A comparison matrix"],"answer":3,"explanation":""}'::jsonb,'c38abf0db10f8734c592060637c8be88','official',NULL,NULL,'Note-Taking & Organizers'),
('original:ela--research-argument-media-literacy--note-taking-organizers:ela--research-argument-media-literacy--note-taking-organizers--5',1,'{"question":"A student researches a question and wants notes to preserve where each fact came from. What should be recorded alongside the note?","choices":["Source details or a citation key","Only the student''s reaction","The color of the webpage","The number of paragraphs in the source"],"answer":0,"explanation":""}'::jsonb,'5817a3ab38ef05ed449e074ed6524ad4','official',NULL,NULL,'Note-Taking & Organizers'),
('original:ela--research-argument-media-literacy--note-taking-organizers:ela--research-argument-media-literacy--note-taking-organizers--6',1,'{"question":"Which note-taking method best supports a later summary?","choices":["Copy every sentence in order","Group key ideas by topic and record concise supporting details","Write isolated keywords with no context","Record only unfamiliar words"],"answer":1,"explanation":""}'::jsonb,'b0f098174464d0ee4b34a54d77c320b3','official',NULL,NULL,'Note-Taking & Organizers'),
('original:ela--research-argument-media-literacy--note-taking-organizers:ela--research-argument-media-literacy--note-taking-organizers--7',1,'{"question":"A concept map places ''erosion'' at the center and links causes, effects, and examples. What does this structure show well?","choices":["A strict chronological sequence","The credibility of every source","Relationships among connected ideas","The correct spelling of terms"],"answer":2,"explanation":""}'::jsonb,'ff6eb9aab1eda12deb1caba034984b51','official',NULL,NULL,'Note-Taking & Organizers'),
('original:ela--research-argument-media-literacy--note-taking-organizers:ela--research-argument-media-literacy--note-taking-organizers--8',1,'{"question":"When is a timeline organizer most appropriate?","choices":["When comparing the reliability of websites","When identifying synonyms","When listing unrelated definitions","When the order and timing of events matter"],"answer":3,"explanation":""}'::jsonb,'5c88ca1eae7f27a010e6d87b523952d0','official',NULL,NULL,'Note-Taking & Organizers'),
('original:ela--research-argument-media-literacy--note-taking-organizers:ela--research-argument-media-literacy--note-taking-organizers--9',1,'{"question":"A student uses Cornell notes. What belongs in the cue column?","choices":["Questions or key terms that help prompt recall of the notes","A full copy of every source page","Decorative images unrelated to the lesson","A second copy of the title only"],"answer":0,"explanation":""}'::jsonb,'69e22490b21694fa252880b1ae94b34d','official',NULL,NULL,'Note-Taking & Organizers'),
('original:ela--research-argument-media-literacy--note-taking-organizers:ela--research-argument-media-literacy--note-taking-organizers--10',1,'{"question":"What is a useful reason to paraphrase a source in notes?","choices":["It removes the need to cite the source","It checks understanding and separates the student''s wording from the source''s wording","It guarantees the source is accurate","It preserves every phrase exactly"],"answer":1,"explanation":""}'::jsonb,'b1e9e2473fa47120e785de701d7224aa','official',NULL,NULL,'Note-Taking & Organizers'),
('original:ela--research-argument-media-literacy--note-taking-organizers:ela--research-argument-media-literacy--note-taking-organizers--11',1,'{"question":"A source gives a statistic but not the date or population measured. What should the note-taker do?","choices":["Record it as universally true","Delete all other notes","Mark the missing context and seek it before relying on the statistic","Invent a likely date"],"answer":2,"explanation":""}'::jsonb,'7ebb99fc5c114f7f00ca77d39d970989','official',NULL,NULL,'Note-Taking & Organizers'),
('original:ela--research-argument-media-literacy--note-taking-organizers:ela--research-argument-media-literacy--note-taking-organizers--12',1,'{"question":"Which organizer helps sort evidence into reasons for and against a claim?","choices":["A character web","A number line","A sequence diagram","A pro-and-con or claim-evidence chart"],"answer":3,"explanation":""}'::jsonb,'35c66237e1f52a10c9a073391997bc3d','official',NULL,NULL,'Note-Taking & Organizers'),
('original:ela--research-argument-media-literacy--note-taking-organizers:ela--research-argument-media-literacy--note-taking-organizers--13',1,'{"question":"A student has notes from five sources. How can they reduce accidental overreliance on one source?","choices":["Track which ideas come from each source and compare evidence across them","Remove all source labels","Use only the longest source","Combine all wording into one paragraph"],"answer":0,"explanation":""}'::jsonb,'7ab2a1c2530c2a6f4d7e4df5ad307175','official',NULL,NULL,'Note-Taking & Organizers'),
('original:ela--research-argument-media-literacy--note-taking-organizers:ela--research-argument-media-literacy--note-taking-organizers--14',1,'{"question":"Why should notes use labels or headings?","choices":["They prove the ideas are correct","They make ideas easier to locate and synthesize later","They remove the need for supporting details","They ensure all sources agree"],"answer":1,"explanation":""}'::jsonb,'e2ab2ae1287f1e2f9d01eedf1d0dfed6','official',NULL,NULL,'Note-Taking & Organizers'),
('original:ela--research-argument-media-literacy--note-taking-organizers:ela--research-argument-media-literacy--note-taking-organizers--15',1,'{"question":"Which note is clearest and most useful?","choices":["Wetlands, county, maybe","Floods are bad","Flood risk rose after wetlands were drained; county map shows affected zones","Read more later"],"answer":2,"explanation":""}'::jsonb,'5de22c0b0a10ce043de1e2887c17bf64','official',NULL,NULL,'Note-Taking & Organizers'),
('original:ela--research-argument-media-literacy--note-taking-organizers:ela--research-argument-media-literacy--note-taking-organizers--16',1,'{"question":"What is the strongest reason to revise notes after a research session?","choices":["Make them look longer","Remove source information","Turn every note into a quotation","Clarify shorthand, group related ideas, and identify unanswered questions"],"answer":3,"explanation":""}'::jsonb,'821060c9895522ba245cd5069a7c0004','official',NULL,NULL,'Note-Taking & Organizers'),
('original:ela--research-argument-media-literacy--note-taking-organizers:ela--research-argument-media-literacy--note-taking-organizers--17',1,'{"question":"A Venn diagram is most useful for","choices":["showing shared and distinct features of two or more subjects","sequencing steps in an experiment","ranking events by date","calculating a percentage"],"answer":0,"explanation":""}'::jsonb,'5b81efc3beaf82d0d7f9824f769fa1db','official',NULL,NULL,'Note-Taking & Organizers'),
('original:ela--research-argument-media-literacy--note-taking-organizers:ela--research-argument-media-literacy--note-taking-organizers--18',1,'{"question":"A student copies a quotation into notes for possible use. What should be included immediately?","choices":["A paraphrase that hides the original wording","Quotation marks and enough source information to locate it","The student''s conclusion only","A new title for the quotation"],"answer":1,"explanation":""}'::jsonb,'7a5856a00a9b69540213902f69b2b272','official',NULL,NULL,'Note-Taking & Organizers'),
('original:ela--research-argument-media-literacy--note-taking-organizers:ela--research-argument-media-literacy--note-taking-organizers--19',1,'{"question":"A research organizer has columns for claim, evidence, source, and limitation. What does the limitation column encourage?","choices":["Memorization of source titles","Removal of counterevidence","Evaluation of what the evidence can and cannot establish","Ranking sources by page length"],"answer":2,"explanation":""}'::jsonb,'78bd4a86c137f73891d206c853052c0f','official',NULL,NULL,'Note-Taking & Organizers'),
('original:ela--research-argument-media-literacy--note-taking-organizers:ela--research-argument-media-literacy--note-taking-organizers--20',1,'{"question":"Which action best turns notes into a synthesis?","choices":["Paste notes in the order they were collected","Choose the most dramatic quotation","List source titles without explaining them","Connect ideas across sources and explain how they answer the research question"],"answer":3,"explanation":""}'::jsonb,'4344fb1185ed14db4e02c6ec539e244b','official',NULL,NULL,'Note-Taking & Organizers'),
('original:ela--research-argument-media-literacy--digital-citizenship:ela--research-argument-media-literacy--digital-citizenship--1',1,'{"question":"Before sharing a dramatic online claim, what is the best first step?","choices":["Check the original source and seek independent corroboration","Share it quickly so others can decide","Trust it if many accounts repeat it","Judge its truth by the number of emojis"],"answer":0,"explanation":""}'::jsonb,'167d1a38d04a8b473a5b53c6e02d3d5e','official',NULL,NULL,'Digital Citizenship'),
('original:ela--research-argument-media-literacy--digital-citizenship:ela--research-argument-media-literacy--digital-citizenship--2',1,'{"question":"A post asks users to enter a password through an unfamiliar link. What is the safest response?","choices":["Reuse the password to test the link","Do not enter credentials; verify the request through the official service","Forward the link to friends","Enter a fake password and personal details"],"answer":1,"explanation":""}'::jsonb,'58f58fb5c92ad4ee4d27dda1fb78ed79','official',NULL,NULL,'Digital Citizenship'),
('original:ela--research-argument-media-literacy--digital-citizenship:ela--research-argument-media-literacy--digital-citizenship--3',1,'{"question":"What does a strong password practice include?","choices":["Using the same short password on every site","Including a public birthday","Using unique, hard-to-guess passwords and a password manager when available","Sharing it with a group chat"],"answer":2,"explanation":""}'::jsonb,'06e26a6db5f7cc01fe4ce64c2286eebe','official',NULL,NULL,'Digital Citizenship'),
('original:ela--research-argument-media-literacy--digital-citizenship:ela--research-argument-media-literacy--digital-citizenship--4',1,'{"question":"A student wants to use an online image in a project. What should they check?","choices":["Whether it appears in the first search result","Whether the file name is short","Whether the image has no visible watermark","Its license or permission and the required attribution"],"answer":3,"explanation":""}'::jsonb,'059107c788d855b9bcee6630b6eb5d62','official',NULL,NULL,'Digital Citizenship'),
('original:ela--research-argument-media-literacy--digital-citizenship:ela--research-argument-media-literacy--digital-citizenship--5',1,'{"question":"A website headline says a study ''proves'' a food causes a health outcome, but the linked study reports only an association. What should a reader conclude?","choices":["The headline overstates what the study establishes","Association always proves causation","The study must be fake","The food has no possible effect"],"answer":0,"explanation":""}'::jsonb,'24737b2158612cb6aa41ba9b09d1edff','official',NULL,NULL,'Digital Citizenship'),
('original:ela--research-argument-media-literacy--digital-citizenship:ela--research-argument-media-literacy--digital-citizenship--6',1,'{"question":"What is a digital footprint?","choices":["A device''s screen size","The trail of information created by a person''s online activity","A private browsing window","A computer''s physical location only"],"answer":1,"explanation":""}'::jsonb,'71855e193a73b9effb2937778f3b9808','official',NULL,NULL,'Digital Citizenship'),
('original:ela--research-argument-media-literacy--digital-citizenship:ela--research-argument-media-literacy--digital-citizenship--7',1,'{"question":"A classmate posts an embarrassing photo of someone without consent. What is a responsible response?","choices":["Download it for later","Add a mocking comment","Avoid resharing it and use appropriate reporting or support channels","Post it to another platform"],"answer":2,"explanation":""}'::jsonb,'e2ec7ea73102ee1d1c48bf788af30600','official',NULL,NULL,'Digital Citizenship'),
('original:ela--research-argument-media-literacy--digital-citizenship:ela--research-argument-media-literacy--digital-citizenship--8',1,'{"question":"A message claims to come from a school but uses a misspelled domain and urgent payment demand. What should the recipient do?","choices":["Pay immediately to avoid a threat","Reply with financial information","Assume the logo proves it is authentic","Verify through a known official contact before acting"],"answer":3,"explanation":""}'::jsonb,'4d948c927ea9d91d63eed7560a28972f','official',NULL,NULL,'Digital Citizenship'),
('original:ela--research-argument-media-literacy--digital-citizenship:ela--research-argument-media-literacy--digital-citizenship--9',1,'{"question":"What does two-factor authentication add?","choices":["A second verification step beyond the password","A second public profile","A guarantee that no account can be hacked","A way to share passwords safely"],"answer":0,"explanation":""}'::jsonb,'7c98e0bf2b2ab97fd5cf3a3039ee985c','official',NULL,NULL,'Digital Citizenship'),
('original:ela--research-argument-media-literacy--digital-citizenship:ela--research-argument-media-literacy--digital-citizenship--10',1,'{"question":"A student uses an AI-generated summary for research. Which practice is strongest?","choices":["Cite the summary as primary evidence","Verify key claims against credible sources and follow class disclosure rules","Assume it is accurate because it is fluent","Submit it without reading it"],"answer":1,"explanation":""}'::jsonb,'8d77fa19b70010bf9aa0dbb3ea26a27e','official',NULL,NULL,'Digital Citizenship'),
('original:ela--research-argument-media-literacy--digital-citizenship:ela--research-argument-media-literacy--digital-citizenship--11',1,'{"question":"Which action respects copyright when using a creator''s work?","choices":["Remove the creator''s name","Assume anything online is public domain","Follow the license terms and credit the creator as required","Change the file name and claim ownership"],"answer":2,"explanation":""}'::jsonb,'b8ad0fb4e6e23491d73a6ab2ba8c7a4b','official',NULL,NULL,'Digital Citizenship'),
('original:ela--research-argument-media-literacy--digital-citizenship:ela--research-argument-media-literacy--digital-citizenship--12',1,'{"question":"A private group chat begins sharing a rumor about a student. What action best limits harm?","choices":["Post the rumor publicly","Ask others to add details","Save it to embarrass the student later","Do not forward it; report threats or harassment to a trusted adult or platform"],"answer":3,"explanation":""}'::jsonb,'9e1c598df0a1c861bde08ad5b3d7a380','official',NULL,NULL,'Digital Citizenship'),
('original:ela--research-argument-media-literacy--digital-citizenship:ela--research-argument-media-literacy--digital-citizenship--13',1,'{"question":"Why might a free app request access to contacts and location?","choices":["It may collect data beyond what its core function needs","Every permission is automatically necessary","Permissions have no privacy effect","The app cannot operate without every permission"],"answer":0,"explanation":""}'::jsonb,'41255b0d13fa867690650bf59e220b48','official',NULL,NULL,'Digital Citizenship'),
('original:ela--research-argument-media-literacy--digital-citizenship:ela--research-argument-media-literacy--digital-citizenship--14',1,'{"question":"Which choice best protects personal information on a public profile?","choices":["Post a home address for verification","Limit identifying details and review privacy settings","Share travel plans in real time with everyone","Use a public profile for account recovery answers"],"answer":1,"explanation":""}'::jsonb,'c7ffec33fef35453cc2533bfccb00b60','official',NULL,NULL,'Digital Citizenship'),
('original:ela--research-argument-media-literacy--digital-citizenship:ela--research-argument-media-literacy--digital-citizenship--15',1,'{"question":"A student sees an edited image presented as a news photograph. What should they check?","choices":["Only whether the image looks realistic","The number of shares","The original context, source, date, and independent reporting","The font used in the caption"],"answer":2,"explanation":""}'::jsonb,'c6aee09642de3319d8557e4fa6f16f7b','official',NULL,NULL,'Digital Citizenship'),
('original:ela--research-argument-media-literacy--digital-citizenship:ela--research-argument-media-literacy--digital-citizenship--16',1,'{"question":"A website''s article is sponsored by a company whose product it praises. What should readers consider?","choices":["Sponsorship proves the product is safe","The article cannot contain any facts","The article is independent by definition","The sponsor may have an interest that shapes the article"],"answer":3,"explanation":""}'::jsonb,'367eb26f8c7959616689888e72f4b0cd','official',NULL,NULL,'Digital Citizenship')
insert into public.question_content_versions(source_key,version_number,question,content_hash,source_type,creator_id,source_set_id,source_title) values
('original:ela--research-argument-media-literacy--digital-citizenship:ela--research-argument-media-literacy--digital-citizenship--17',1,'{"question":"Which online comment contributes most constructively to a disagreement?","choices":["A response that addresses the claim with evidence and respectful language","A personal insult","A threat to expose private information","A repeated rumor"],"answer":0,"explanation":""}'::jsonb,'23b0986a5c68aba4dd4d36b7ac3d4916','official',NULL,NULL,'Digital Citizenship'),
('original:ela--research-argument-media-literacy--digital-citizenship:ela--research-argument-media-literacy--digital-citizenship--18',1,'{"question":"What is phishing?","choices":["A method of compressing files","A deceptive attempt to obtain sensitive information by impersonation","A secure way to store passwords","A type of licensed image"],"answer":1,"explanation":""}'::jsonb,'3ea31fbb66ee8715d6c3c0afd8c6866b','official',NULL,NULL,'Digital Citizenship'),
('original:ela--research-argument-media-literacy--digital-citizenship:ela--research-argument-media-literacy--digital-citizenship--19',1,'{"question":"Why should people consider an audience before posting?","choices":["A post disappears once viewed","Only intended readers can access it","Posts can be copied, shared, and interpreted outside their original context","Audience has no effect on meaning"],"answer":2,"explanation":""}'::jsonb,'fabeb1733ebff6bc2748966abf4e0837','official',NULL,NULL,'Digital Citizenship'),
('original:ela--research-argument-media-literacy--digital-citizenship:ela--research-argument-media-literacy--digital-citizenship--20',1,'{"question":"A friend sends a link to a shocking video but cannot identify its source. What is the most responsible choice?","choices":["Share it with a warning but no verification","Assume it is current","Use its caption as proof","Pause sharing and verify the video and context first"],"answer":3,"explanation":""}'::jsonb,'91bc6bd3f868420671eeb1337fe832c7','official',NULL,NULL,'Digital Citizenship'),
('original:ela--speaking-listening--class-discussions-socratic-seminars:ela--speaking-listening--class-discussions-socratic-seminars--1',1,'{"question":"What is a useful purpose of an open-ended seminar question?","choices":["Invite multiple evidence-based interpretations","Signal that only one word is acceptable","End discussion before participants respond","Test how quickly someone can speak"],"answer":0,"explanation":""}'::jsonb,'6df8427b2ddf5c8b6e872f877b433841','official',NULL,NULL,'Class Discussions & Socratic Seminars'),
('original:ela--speaking-listening--class-discussions-socratic-seminars:ela--speaking-listening--class-discussions-socratic-seminars--2',1,'{"question":"A participant disagrees with a classmate''s interpretation. Which response best advances discussion?","choices":["Interrupt and repeat the same claim louder","Refer to a specific part of the text and explain a different reading","Criticize the classmate personally","Change the subject"],"answer":1,"explanation":""}'::jsonb,'ce1b895f7a14c871a674c079dd41f29a','official',NULL,NULL,'Class Discussions & Socratic Seminars'),
('original:ela--speaking-listening--class-discussions-socratic-seminars:ela--speaking-listening--class-discussions-socratic-seminars--3',1,'{"question":"What does active listening include?","choices":["Planning a rebuttal without listening","Waiting for a pause to change topics","Attending to a speaker''s idea and responding to what was actually said","Agreeing with every statement"],"answer":2,"explanation":""}'::jsonb,'9e4b7b0a00af75af37c5ff79bc4cdfad','official',NULL,NULL,'Class Discussions & Socratic Seminars'),
('original:ela--speaking-listening--class-discussions-socratic-seminars:ela--speaking-listening--class-discussions-socratic-seminars--4',1,'{"question":"A seminar is dominated by two speakers. What is a useful facilitation move?","choices":["End the discussion immediately","Let the same speakers take every turn","Score participants by speaking speed","Invite voices that have not yet contributed and make space for them"],"answer":3,"explanation":""}'::jsonb,'5c92f071745639c8ba2f61f17c000ebd','official',NULL,NULL,'Class Discussions & Socratic Seminars'),
('original:ela--speaking-listening--class-discussions-socratic-seminars:ela--speaking-listening--class-discussions-socratic-seminars--5',1,'{"question":"Which comment best builds on a previous speaker''s idea?","choices":["I want to extend Maya''s point about the setting by considering the narrator''s word choice","That is wrong","I have a different topic","I was going to say something"],"answer":0,"explanation":""}'::jsonb,'85cd1ef8fd1a755ea13a6515cc4ced7a','official',NULL,NULL,'Class Discussions & Socratic Seminars'),
('original:ela--speaking-listening--class-discussions-socratic-seminars:ela--speaking-listening--class-discussions-socratic-seminars--6',1,'{"question":"Why should participants support claims with evidence?","choices":["Evidence prevents disagreement","Evidence lets the group evaluate and compare interpretations","Evidence makes discussion shorter by definition","Evidence replaces listening"],"answer":1,"explanation":""}'::jsonb,'2578e3521ee5ec9f4d70f46ad08b8ea7','official',NULL,NULL,'Class Discussions & Socratic Seminars'),
('original:ela--speaking-listening--class-discussions-socratic-seminars:ela--speaking-listening--class-discussions-socratic-seminars--7',1,'{"question":"A student asks, ''What in the passage supports that conclusion?'' What discussion move is this?","choices":["Changing the subject","Summarizing a final decision","Requesting evidence or clarification","Making a personal attack"],"answer":2,"explanation":""}'::jsonb,'bc7bec981d32c2d3fee6dba5587659b4','official',NULL,NULL,'Class Discussions & Socratic Seminars'),
('original:ela--speaking-listening--class-discussions-socratic-seminars:ela--speaking-listening--class-discussions-socratic-seminars--8',1,'{"question":"What is a respectful way to enter a discussion after a pause?","choices":["Speak over another participant","Dismiss the previous points","Read an unrelated prepared paragraph","Connect a comment to an earlier idea or pose a relevant question"],"answer":3,"explanation":""}'::jsonb,'3cb47c0fc195e1c8a84b79a91a34c631','official',NULL,NULL,'Class Discussions & Socratic Seminars'),
('original:ela--speaking-listening--class-discussions-socratic-seminars:ela--speaking-listening--class-discussions-socratic-seminars--9',1,'{"question":"A participant changes their interpretation after hearing new evidence. What does this show?","choices":["Reasoned discussion can refine a claim","The first interpretation was dishonest","The participant must stop contributing","Evidence should be ignored"],"answer":0,"explanation":""}'::jsonb,'6c7e2b4f480c2d0c1669c5d1322c10a1','official',NULL,NULL,'Class Discussions & Socratic Seminars'),
('original:ela--speaking-listening--class-discussions-socratic-seminars:ela--speaking-listening--class-discussions-socratic-seminars--10',1,'{"question":"Which question is most likely to deepen analysis?","choices":["Did you like the story?","How does the author''s choice in this passage shape the theme?","What page is this on?","Was the book printed in color?"],"answer":1,"explanation":""}'::jsonb,'63cafd96e476fcd9be2ecf82bab10a6d','official',NULL,NULL,'Class Discussions & Socratic Seminars'),
('original:ela--speaking-listening--class-discussions-socratic-seminars:ela--speaking-listening--class-discussions-socratic-seminars--11',1,'{"question":"A seminar norm says ''criticize ideas, not people.'' What does it encourage?","choices":["Avoid all disagreement","Agree with the highest-status speaker","Focus disagreement on claims, reasoning, and evidence","Discuss classmates'' personalities"],"answer":2,"explanation":""}'::jsonb,'c89cd90f88aaa7ce3c5be118db08c1e7','official',NULL,NULL,'Class Discussions & Socratic Seminars'),
('original:ela--speaking-listening--class-discussions-socratic-seminars:ela--speaking-listening--class-discussions-socratic-seminars--12',1,'{"question":"Why might a participant paraphrase a peer''s point before responding?","choices":["To change the point into a weaker one","To avoid adding any analysis","To take credit for the idea","To check understanding and show the response addresses the point"],"answer":3,"explanation":""}'::jsonb,'48a503d1a5514ba272ba39e68e63ea69','official',NULL,NULL,'Class Discussions & Socratic Seminars'),
('original:ela--speaking-listening--class-discussions-socratic-seminars:ela--speaking-listening--class-discussions-socratic-seminars--13',1,'{"question":"A group has several plausible interpretations and incomplete evidence. What should it do?","choices":["Compare the interpretations and identify what evidence would help distinguish them","Vote without explaining","Treat the first claim as final","Ignore the text"],"answer":0,"explanation":""}'::jsonb,'fcba9536bbb00ed508e21eab82ec2c3a','official',NULL,NULL,'Class Discussions & Socratic Seminars'),
('original:ela--speaking-listening--class-discussions-socratic-seminars:ela--speaking-listening--class-discussions-socratic-seminars--14',1,'{"question":"What is a facilitator''s role in a seminar?","choices":["Provide every answer","Support equitable participation and keep discussion connected to its purpose","Speak for most of the time","Prevent participants from asking questions"],"answer":1,"explanation":""}'::jsonb,'59de658a7b392241de777bb261fc5808','official',NULL,NULL,'Class Discussions & Socratic Seminars'),
('original:ela--speaking-listening--class-discussions-socratic-seminars:ela--speaking-listening--class-discussions-socratic-seminars--15',1,'{"question":"A speaker makes a broad claim that ''everyone'' agrees. Which response is most useful?","choices":["Accept it because it sounds confident","Mock the speaker","Ask what evidence or examples support the claim and whether exceptions exist","End the discussion"],"answer":2,"explanation":""}'::jsonb,'c93b14e99ac6769408883b284866d00f','official',NULL,NULL,'Class Discussions & Socratic Seminars'),
('original:ela--speaking-listening--class-discussions-socratic-seminars:ela--speaking-listening--class-discussions-socratic-seminars--16',1,'{"question":"How can a participant disagree while keeping the discussion productive?","choices":["Say the other person is ignorant","Refuse to explain the disagreement","Repeat the claim without evidence","Acknowledge the point, state a different claim, and support it with evidence"],"answer":3,"explanation":""}'::jsonb,'a22eb478f9ddc80357b63e47ef99e514','official',NULL,NULL,'Class Discussions & Socratic Seminars'),
('original:ela--speaking-listening--class-discussions-socratic-seminars:ela--speaking-listening--class-discussions-socratic-seminars--17',1,'{"question":"A discussion keeps drifting away from the central question. What can bring it back?","choices":["Restate the question and connect the current point to it","Introduce a more entertaining topic","Stop taking turns","Ignore the original task"],"answer":0,"explanation":""}'::jsonb,'bff5e09a7fe31b687c27734d6e184cc5','official',NULL,NULL,'Class Discussions & Socratic Seminars'),
('original:ela--speaking-listening--class-discussions-socratic-seminars:ela--speaking-listening--class-discussions-socratic-seminars--18',1,'{"question":"Which behavior best demonstrates listening?","choices":["Repeat a memorized response regardless of what was said","Ask a follow-up that accurately reflects the speaker''s point","Check unrelated messages","Interrupt every sentence"],"answer":1,"explanation":""}'::jsonb,'0fc63c32e69652f61ecc6d231205b24b','official',NULL,NULL,'Class Discussions & Socratic Seminars'),
('original:ela--speaking-listening--class-discussions-socratic-seminars:ela--speaking-listening--class-discussions-socratic-seminars--19',1,'{"question":"Why can silence be useful in a discussion?","choices":["It proves no one prepared","It guarantees agreement","It gives participants time to think before responding","It replaces the need for a question"],"answer":2,"explanation":""}'::jsonb,'1dfec33c66cd93e88b762da4e626ffb1','official',NULL,NULL,'Class Discussions & Socratic Seminars'),
('original:ela--speaking-listening--class-discussions-socratic-seminars:ela--speaking-listening--class-discussions-socratic-seminars--20',1,'{"question":"After a seminar, which reflection is most useful?","choices":["Rate classmates by popularity","List only who spoke most","Decide whether every participant agreed","Identify how evidence, listening, and participation shaped the discussion"],"answer":3,"explanation":""}'::jsonb,'24ecc80fae50e2f044ed30b69ff4b20c','official',NULL,NULL,'Class Discussions & Socratic Seminars'),
