('original:ela--speaking-listening--listening-comprehension-tasks:ela--speaking-listening--listening-comprehension-tasks--5',1,'{"question":"A speaker''s tone sounds uncertain while the words state a firm conclusion. What should a listener do?","choices":["Consider both the wording and vocal cues before interpreting the message","Ignore the words entirely","Assume tone never matters","Conclude the speaker is lying"],"answer":0,"explanation":""}'::jsonb,'9ccc9b9e64def58ef9bcf2fafb7e98d2','official',NULL,NULL,'Listening Comprehension Tasks'),
('original:ela--speaking-listening--listening-comprehension-tasks:ela--speaking-listening--listening-comprehension-tasks--6',1,'{"question":"Which note-taking choice best supports listening comprehension?","choices":["Write continuously without understanding","Use brief key words and relationships rather than trying to transcribe every word","Ignore transitions","Record only filler words"],"answer":1,"explanation":""}'::jsonb,'b3b8c56ac87a1140e9ebe8d313ac7cc8','official',NULL,NULL,'Listening Comprehension Tasks'),
('original:ela--speaking-listening--listening-comprehension-tasks:ela--speaking-listening--listening-comprehension-tasks--7',1,'{"question":"In a conversation, what is a clarifying question?","choices":["A question that changes the topic","A statement that repeats a rumor","A question that asks the speaker to explain an unclear point","A personal criticism"],"answer":2,"explanation":""}'::jsonb,'2f27103f0fa2fcd1c5133254b7d9a4ec','official',NULL,NULL,'Listening Comprehension Tasks'),
