('original:ela--speaking-listening--listening-comprehension-tasks:ela--speaking-listening--listening-comprehension-tasks--9',1,'{"question":"A listener summarizes a speaker''s main point before responding. Why is this useful?","choices":["It checks comprehension and gives the speaker a chance to clarify","It proves the listener agrees","It ends the discussion","It replaces evidence"],"answer":0,"explanation":""}'::jsonb,'17681d452f0a73a14c7ceef14c1eac34','official',NULL,NULL,'Listening Comprehension Tasks'),
('original:ela--speaking-listening--listening-comprehension-tasks:ela--speaking-listening--listening-comprehension-tasks--10',1,'{"question":"A lecture includes a key claim and a counterexample. What should a listener record?","choices":["Only the first sentence","Both the claim and how the counterexample affects it","Only the counterexample''s source","Neither, because they conflict"],"answer":1,"explanation":""}'::jsonb,'30d559c372a51229c1001077041eea3e','official',NULL,NULL,'Listening Comprehension Tasks'),
('original:ela--speaking-listening--listening-comprehension-tasks:ela--speaking-listening--listening-comprehension-tasks--11',1,'{"question":"A speaker provides an example but does not state a conclusion. What can the listener reasonably do?","choices":["Treat any inference as a direct quotation","Assume the speaker has no purpose","Infer a possible point but distinguish inference from what was stated directly","Ignore the example"],"answer":2,"explanation":""}'::jsonb,'1a562013f1bec90d04188bce94622a1e','official',NULL,NULL,'Listening Comprehension Tasks'),
('original:ela--speaking-listening--listening-comprehension-tasks:ela--speaking-listening--listening-comprehension-tasks--12',1,'{"question":"During a peer''s presentation, which action best demonstrates respectful listening?","choices":["Talk over the presentation","Use a phone throughout","Prepare a response unrelated to the talk","Attend to the speaker and save questions for an appropriate pause"],"answer":3,"explanation":""}'::jsonb,'1bf8361e89b83f77efe1fef9bed4da8d','official',NULL,NULL,'Listening Comprehension Tasks'),
('original:ela--speaking-listening--listening-comprehension-tasks:ela--speaking-listening--listening-comprehension-tasks--13',1,'{"question":"What should a listener do when two speakers give conflicting information?","choices":["Compare their evidence, context, and claims before deciding","Choose the more confident voice","Assume both are equally accurate","Ignore both sources"],"answer":0,"explanation":""}'::jsonb,'f36ab80f5ea468d8d4fa572a48d00895','official',NULL,NULL,'Listening Comprehension Tasks'),
