('original:ela--speaking-listening--listening-comprehension-tasks:ela--speaking-listening--listening-comprehension-tasks--16',1,'{"question":"A listener misses one sentence. What is the best way to recover?","choices":["Stop attending to the rest","Invent the missing sentence","Assume all later points are irrelevant","Use the next points and context, then ask for clarification if needed"],"answer":3,"explanation":""}'::jsonb,'61704876c9f222998f9becd3fa587730','official',NULL,NULL,'Listening Comprehension Tasks'),
('original:ela--speaking-listening--listening-comprehension-tasks:ela--speaking-listening--listening-comprehension-tasks--17',1,'{"question":"Why are nonverbal cues useful but limited evidence?","choices":["They can add context, but they do not reveal a person''s thoughts with certainty","They always reveal exact meaning","They replace words in every situation","They prove a speaker''s claim is true"],"answer":0,"explanation":""}'::jsonb,'144b3090338135314a227685d82547e6','official',NULL,NULL,'Listening Comprehension Tasks'),
('original:ela--speaking-listening--listening-comprehension-tasks:ela--speaking-listening--listening-comprehension-tasks--18',1,'{"question":"A speaker repeats a phrase before introducing a main point. What might the repetition signal?","choices":["A change of speaker","Emphasis or an upcoming important idea","A missing source","An unrelated conclusion"],"answer":1,"explanation":""}'::jsonb,'b27bdd4021e090bbee4568f017a04ea0','official',NULL,NULL,'Listening Comprehension Tasks'),
('original:ela--speaking-listening--listening-comprehension-tasks:ela--speaking-listening--listening-comprehension-tasks--19',1,'{"question":"After listening to a science explanation, a student can restate the steps but not explain why they work. What is the best next move?","choices":["Memorize the wording without understanding","Change to an unrelated topic","Ask a question about the reasoning connecting the steps","Assume the steps are incorrect"],"answer":2,"explanation":""}'::jsonb,'6dc7af27509df183d2cd6915bc57295a','official',NULL,NULL,'Listening Comprehension Tasks'),
('original:ela--speaking-listening--listening-comprehension-tasks:ela--speaking-listening--listening-comprehension-tasks--20',1,'{"question":"Which response best distinguishes a speaker''s main idea from a supporting detail?","choices":["List the example alone","Repeat the title","Name the speaker''s clothing","State the broad claim, then identify the example that illustrates it"],"answer":3,"explanation":""}'::jsonb,'49b5aea18beebbac4a35e9af2e61a267','official',NULL,NULL,'Listening Comprehension Tasks'),
('original:ela--research-argument-media-literacy--debates-structured-argument:ela--research-argument-media-literacy--debates-structured-argument--1',1,'{"question":"Which claim is most suitable for a structured debate?","choices":["The city should extend library hours on school nights because student access is limited","Libraries are buildings","Everyone has an opinion about books","The city has many streets"],"answer":0,"explanation":""}'::jsonb,'50192fad826db3604539eb133797b098','official',NULL,NULL,'Debates & Structured Argument'),
('original:ela--research-argument-media-literacy--debates-structured-argument:ela--research-argument-media-literacy--debates-structured-argument--2',1,'{"question":"What makes a reason different from evidence?","choices":["A reason is always a quotation","A reason explains why a claim may be true; evidence supports the reason","Evidence is a personal preference","They are identical terms"],"answer":1,"explanation":""}'::jsonb,'d3ede68f880e85ce357a9224675f0997','official',NULL,NULL,'Debates & Structured Argument'),
('original:ela--research-argument-media-literacy--debates-structured-argument:ela--research-argument-media-literacy--debates-structured-argument--3',1,'{"question":"A debater cites a survey of 800 local residents. What should the audience ask to evaluate it?","choices":["What color the survey used","Whether the survey title is catchy","How participants were selected and what question they answered","How many pages the debate has"],"answer":2,"explanation":""}'::jsonb,'d1f3a34a88a4f72efe1f68d2bf4a68b0','official',NULL,NULL,'Debates & Structured Argument'),
('original:ela--research-argument-media-literacy--debates-structured-argument:ela--research-argument-media-literacy--debates-structured-argument--4',1,'{"question":"Why address a counterclaim?","choices":["To weaken the main claim without explanation","To avoid presenting evidence","To change the topic","To show that opposing reasoning has been considered and respond to it"],"answer":3,"explanation":""}'::jsonb,'aa98ade866867cb426c3dc212b18920c','official',NULL,NULL,'Debates & Structured Argument'),
('original:ela--research-argument-media-literacy--debates-structured-argument:ela--research-argument-media-literacy--debates-structured-argument--5',1,'{"question":"Which response best challenges an argument respectfully?","choices":["The data support a different conclusion because they include only one season","Your argument is ridiculous","You clearly did not read the prompt","No one should listen to you"],"answer":0,"explanation":""}'::jsonb,'8e482f56e9aa237b9f6a182b65e5ad3e','official',NULL,NULL,'Debates & Structured Argument'),
('original:ela--research-argument-media-literacy--debates-structured-argument:ela--research-argument-media-literacy--debates-structured-argument--6',1,'{"question":"A debater uses an emotional story as the only support for a broad policy claim. What is the main limitation?","choices":["Stories can never be relevant evidence","One example may not establish how common the situation is","Policies cannot be discussed with examples","Emotion always makes reasoning invalid"],"answer":1,"explanation":""}'::jsonb,'cb2f7291fd3408ed78c55ae55e304248','official',NULL,NULL,'Debates & Structured Argument'),
('original:ela--research-argument-media-literacy--debates-structured-argument:ela--research-argument-media-literacy--debates-structured-argument--7',1,'{"question":"Which evidence most directly supports a claim about reduced traffic injuries after a street redesign?","choices":["A drawing of the new street","A resident''s favorite color","Comparable injury records from before and after the redesign","A list of unrelated city projects"],"answer":2,"explanation":""}'::jsonb,'20d9bd4b9f0435eec0722ee00ece19ac','official',NULL,NULL,'Debates & Structured Argument'),
('original:ela--research-argument-media-literacy--debates-structured-argument:ela--research-argument-media-literacy--debates-structured-argument--8',1,'{"question":"What is a rebuttal?","choices":["A topic sentence introducing a new subject","A list of sources with no claim","An opening greeting","A response that challenges or answers an opposing argument"],"answer":3,"explanation":""}'::jsonb,'8d860cd3f5c3b408d66324464e28f29d','official',NULL,NULL,'Debates & Structured Argument'),
('original:ela--research-argument-media-literacy--debates-structured-argument:ela--research-argument-media-literacy--debates-structured-argument--9',1,'{"question":"A speaker says, ''My opponent wants children to be unsafe.'' The opponent had argued only about budget. What tactic is this?","choices":["Misrepresenting the opposing position","Providing a qualified concession","Using a direct comparison","Citing relevant evidence"],"answer":0,"explanation":""}'::jsonb,'b55d85108328aefb5ce511a677bfce34','official',NULL,NULL,'Debates & Structured Argument'),
('original:ela--research-argument-media-literacy--debates-structured-argument:ela--research-argument-media-literacy--debates-structured-argument--10',1,'{"question":"Which statement is a concession?","choices":["The plan has no possible drawback","Although the plan costs more initially, it may reduce repair expenses later","My opponent''s evidence is fabricated","Only one option exists"],"answer":1,"explanation":""}'::jsonb,'aa2e88d236e169c0158604ad7a2e387e','official',NULL,NULL,'Debates & Structured Argument'),
('original:ela--research-argument-media-literacy--debates-structured-argument:ela--research-argument-media-literacy--debates-structured-argument--11',1,'{"question":"A claim relies on a study from another country with different conditions. What should a debater explain?","choices":["Why location never affects evidence","Why the study''s title proves the claim","How well that evidence applies to the local situation","Why no other evidence is needed"],"answer":2,"explanation":""}'::jsonb,'4b4394d2a06de9ac570c6a977989d4cb','official',NULL,NULL,'Debates & Structured Argument'),
('original:ela--research-argument-media-literacy--debates-structured-argument:ela--research-argument-media-literacy--debates-structured-argument--12',1,'{"question":"Which debate rule best supports fair participation?","choices":["Allow only one side to ask questions","Reward interruptions","Change the rules during a speaker''s turn","Set clear speaking turns and equal time limits"],"answer":3,"explanation":""}'::jsonb,'8f771e5c6a72dcebc0c87c3f7e206bbe','official',NULL,NULL,'Debates & Structured Argument'),
('original:ela--research-argument-media-literacy--debates-structured-argument:ela--research-argument-media-literacy--debates-structured-argument--13',1,'{"question":"An argument includes a claim, relevant evidence, and reasoning connecting them. What is strengthened by this structure?","choices":["The audience can follow how the evidence supports the claim","The argument becomes automatically correct","The need to consider counterevidence disappears","The speaker no longer needs a conclusion"],"answer":0,"explanation":""}'::jsonb,'ed1729c75ca0fe7a550977fcc73ecb0b','official',NULL,NULL,'Debates & Structured Argument'),
('original:ela--research-argument-media-literacy--debates-structured-argument:ela--research-argument-media-literacy--debates-structured-argument--14',1,'{"question":"Which question tests whether a source is relevant to a claim?","choices":["Is the source''s font attractive?","Does this source provide information that bears directly on the issue?","Is the source longer than the speech?","Does the source agree with my first impression?"],"answer":1,"explanation":""}'::jsonb,'81d4b5f057c79b6401525f43b7d80ef9','official',NULL,NULL,'Debates & Structured Argument'),
('original:ela--research-argument-media-literacy--debates-structured-argument:ela--research-argument-media-literacy--debates-structured-argument--15',1,'{"question":"A debater cites a percentage but not the total number of people surveyed. What context is missing?","choices":["The argument''s topic","The speaker''s speaking time","The sample size","The debate''s location"],"answer":2,"explanation":""}'::jsonb,'71765627a1745d741fd910087cd781b7','official',NULL,NULL,'Debates & Structured Argument'),
('original:ela--research-argument-media-literacy--debates-structured-argument:ela--research-argument-media-literacy--debates-structured-argument--16',1,'{"question":"Why should a debater distinguish correlation from causation?","choices":["Correlations cannot be measured","Causes are always opinions","The distinction applies only to history","A relationship between two trends alone does not prove one caused the other"],"answer":3,"explanation":""}'::jsonb,'fb14fa49e0de684f4711a90e679f718e','official',NULL,NULL,'Debates & Structured Argument'),
('original:ela--research-argument-media-literacy--debates-structured-argument:ela--research-argument-media-literacy--debates-structured-argument--17',1,'{"question":"A team changes its position after hearing stronger evidence. What does that demonstrate?","choices":["Evidence-based reasoning can lead to a revised claim","The team has lost automatically","Debate positions can never change","The earlier evidence should be hidden"],"answer":0,"explanation":""}'::jsonb,'c470545d071425492a248a361cd0e78e','official',NULL,NULL,'Debates & Structured Argument'),
('original:ela--research-argument-media-literacy--debates-structured-argument:ela--research-argument-media-literacy--debates-structured-argument--18',1,'{"question":"Which closing best fits a debate speech?","choices":["Introduce an unrelated issue","Restate the central claim and summarize the strongest reasons and evidence","Add an unsupported statistic","Repeat the opening word for word"],"answer":1,"explanation":""}'::jsonb,'c47696e5d2cf2c4c7c7a8777750ed972','official',NULL,NULL,'Debates & Structured Argument'),
('original:ela--research-argument-media-literacy--debates-structured-argument:ela--research-argument-media-literacy--debates-structured-argument--19',1,'{"question":"A debater uses a personal attack instead of answering evidence. What is the problem?","choices":["Personal attacks make evidence stronger","The opposing claim is therefore false","The attack does not address whether the opposing claim is supported","The audience cannot evaluate any claims"],"answer":2,"explanation":""}'::jsonb,'c8b9dd3775fc9c51f01536382397d735','official',NULL,NULL,'Debates & Structured Argument'),
('original:ela--research-argument-media-literacy--debates-structured-argument:ela--research-argument-media-literacy--debates-structured-argument--20',1,'{"question":"What is the best way to compare two proposed policies?","choices":["Use strong evidence for one and anecdotes for the other","Compare only their names","Ignore trade-offs","Use the same criteria and relevant evidence for both"],"answer":3,"explanation":""}'::jsonb,'982979397d9b8513c3862b343d968ae9','official',NULL,NULL,'Debates & Structured Argument'),
('original:ela--speaking-listening--collaborative-conversations:ela--speaking-listening--collaborative-conversations--1',1,'{"question":"What is a productive first step when a group receives a complex task?","choices":["Clarify the goal, constraints, and roles","Begin separate work without discussing the goal","Choose a final answer before reading the task","Assign every role to one person"],"answer":0,"explanation":""}'::jsonb,'4b4309278c3719fa71534a2500184989','official',NULL,NULL,'Collaborative Conversations'),
('original:ela--speaking-listening--collaborative-conversations:ela--speaking-listening--collaborative-conversations--2',1,'{"question":"A team member has not spoken. What can another member do to support collaboration?","choices":["Assume the member has no ideas","Invite the member to share their perspective without putting them on the spot","Speak for the member","End the conversation"],"answer":1,"explanation":""}'::jsonb,'8b2eec1e677aa473a7d2e7394cba873a','official',NULL,NULL,'Collaborative Conversations'),
('original:ela--speaking-listening--collaborative-conversations:ela--speaking-listening--collaborative-conversations--3',1,'{"question":"Two group members disagree about a solution. What should they compare?","choices":["Who has the louder voice","Which proposal was mentioned first","The evidence and criteria relevant to each proposal","Which member is more popular"],"answer":2,"explanation":""}'::jsonb,'2d9d332d0b96720abb97027b2958365f','official',NULL,NULL,'Collaborative Conversations'),
('original:ela--speaking-listening--collaborative-conversations:ela--speaking-listening--collaborative-conversations--4',1,'{"question":"Why should a group summarize decisions before ending a meeting?","choices":["To prevent members from asking questions","To avoid recording responsibilities","To make the meeting longer","To confirm shared understanding and clarify next steps"],"answer":3,"explanation":""}'::jsonb,'ef774f0bb122cf5c4be16562169b5262','official',NULL,NULL,'Collaborative Conversations'),
('original:ela--speaking-listening--collaborative-conversations:ela--speaking-listening--collaborative-conversations--5',1,'{"question":"A group assigns one person to research, one to check evidence, and one to report. What is the benefit?","choices":["Responsibilities are clear and work can be coordinated","No one needs to communicate","The task is guaranteed to be correct","Members cannot contribute outside their role"],"answer":0,"explanation":""}'::jsonb,'d15057535b766f50198761ff60340ec2','official',NULL,NULL,'Collaborative Conversations'),
('original:ela--speaking-listening--collaborative-conversations:ela--speaking-listening--collaborative-conversations--6',1,'{"question":"Which response best handles a misunderstanding?","choices":["Assume the worst intention","Ask the speaker to clarify and restate what you understood","Repeat the misunderstood idea as fact","Stop listening"],"answer":1,"explanation":""}'::jsonb,'fb8d9a5ec7517738a10408093f6bea57','official',NULL,NULL,'Collaborative Conversations'),
('original:ela--speaking-listening--collaborative-conversations:ela--speaking-listening--collaborative-conversations--7',1,'{"question":"A team is behind schedule. Which action is most constructive?","choices":["Blame one person before checking progress","Ignore the deadline","Identify the remaining tasks, set priorities, and redistribute work fairly","Discard the shared goal"],"answer":2,"explanation":""}'::jsonb,'801308264f2fb93c8725a23d3de66783','official',NULL,NULL,'Collaborative Conversations'),
('original:ela--speaking-listening--collaborative-conversations:ela--speaking-listening--collaborative-conversations--8',1,'{"question":"What does building on a peer''s idea involve?","choices":["Repeat the idea and claim it as your own","Reject it without explanation","Change to an unrelated topic","Acknowledge the idea and add a related point or question"],"answer":3,"explanation":""}'::jsonb,'f929ebe938ec4528b696c98a727803a5','official',NULL,NULL,'Collaborative Conversations'),
('original:ela--speaking-listening--collaborative-conversations:ela--speaking-listening--collaborative-conversations--9',1,'{"question":"Which group norm helps make disagreement productive?","choices":["Challenge ideas with reasons while treating members respectfully","Never question a proposal","Criticize the person who proposed it","Let only the leader speak"],"answer":0,"explanation":""}'::jsonb,'2acd37a1dd257cbb0b5ae5eba31ce525','official',NULL,NULL,'Collaborative Conversations'),
('original:ela--speaking-listening--collaborative-conversations:ela--speaking-listening--collaborative-conversations--10',1,'{"question":"A group agrees quickly, but one member has concerns. What should the facilitator do?","choices":["Declare the decision final","Invite the concern and check whether the decision addresses it","Exclude the member from later work","Pretend agreement is complete"],"answer":1,"explanation":""}'::jsonb,'76348f0c9fad9365e9c5e9895f6c6d3e','official',NULL,NULL,'Collaborative Conversations'),
('original:ela--speaking-listening--collaborative-conversations:ela--speaking-listening--collaborative-conversations--11',1,'{"question":"A group uses a shared document. Which practice improves accountability?","choices":["Delete names from all tasks","Let everyone assume someone else will do it","Record owners and due dates for each task","Avoid reviewing progress"],"answer":2,"explanation":""}'::jsonb,'193d8d92c8fe16e3d32c5dcbfe8fe2ac','official',NULL,NULL,'Collaborative Conversations'),
('original:ela--speaking-listening--collaborative-conversations:ela--speaking-listening--collaborative-conversations--12',1,'{"question":"What is consensus?","choices":["A decision made by the fastest speaker","A rule that everyone must share the same opinion","A vote that ignores discussion","A decision the group can support after considering perspectives, even if it is not everyone''s first choice"],"answer":3,"explanation":""}'::jsonb,'e558d2d03c0682cdc62e662d2c3d5b49','official',NULL,NULL,'Collaborative Conversations'),
('original:ela--speaking-listening--collaborative-conversations:ela--speaking-listening--collaborative-conversations--13',1,'{"question":"A member interrupts repeatedly. Which reminder is most useful?","choices":["Let''s finish each turn and make sure everyone has a chance to contribute","Stop talking forever","Your ideas are not useful","Only the leader may speak"],"answer":0,"explanation":""}'::jsonb,'35a30bde9a3b25e17fd2b52e655ccca2','official',NULL,NULL,'Collaborative Conversations'),
('original:ela--speaking-listening--collaborative-conversations:ela--speaking-listening--collaborative-conversations--14',1,'{"question":"Why can assigning a rotating facilitator help a group?","choices":["It removes the need for group decisions","It shares responsibility for keeping discussion focused and equitable","It makes one member responsible for all content","It prevents disagreement"],"answer":1,"explanation":""}'::jsonb,'2db819b9a0ae7cd9e669ddac889a4b77','official',NULL,NULL,'Collaborative Conversations'),
('original:ela--speaking-listening--collaborative-conversations:ela--speaking-listening--collaborative-conversations--15',1,'{"question":"A group receives feedback that its presentation lacks evidence. What is the best response?","choices":["Dismiss all feedback as unfair","Add unrelated quotations","Review the claim and add relevant, credible support","Remove the claim without discussion"],"answer":2,"explanation":""}'::jsonb,'b9e0fc40cb8d7c34b487ab5e3bc8602f','official',NULL,NULL,'Collaborative Conversations'),
('original:ela--speaking-listening--collaborative-conversations:ela--speaking-listening--collaborative-conversations--16',1,'{"question":"Which statement demonstrates paraphrasing in conversation?","choices":["I disagree","Whatever","Let''s move on","So your concern is that the schedule leaves too little time for testing—is that right?"],"answer":3,"explanation":""}'::jsonb,'de664619b50f6ab6ad25e10675e42bb2','official',NULL,NULL,'Collaborative Conversations')
insert into public.question_content_versions(source_key,version_number,question,content_hash,source_type,creator_id,source_set_id,source_title) values
('original:ela--speaking-listening--collaborative-conversations:ela--speaking-listening--collaborative-conversations--17',1,'{"question":"A group is choosing among options with different costs and benefits. What should it do?","choices":["Agree on criteria, compare options, and explain the trade-offs","Choose at random","Compare each option using different criteria","Ignore affected stakeholders"],"answer":0,"explanation":""}'::jsonb,'6e9daa5cba2cf2b5ad3b30aae09520ad','official',NULL,NULL,'Collaborative Conversations'),
('original:ela--speaking-listening--collaborative-conversations:ela--speaking-listening--collaborative-conversations--18',1,'{"question":"How can a recorder support a collaborative group?","choices":["Decide the answer without consulting others","Capture decisions, questions, and assigned next steps","Record only personal opinions","Prevent members from revising ideas"],"answer":1,"explanation":""}'::jsonb,'a2a492b9f9d32f94d0144fe3904b3088','official',NULL,NULL,'Collaborative Conversations'),
('original:ela--speaking-listening--collaborative-conversations:ela--speaking-listening--collaborative-conversations--19',1,'{"question":"A member misses a meeting. How can the group support continuity?","choices":["Restart all work without explanation","Assume the member will guess what happened","Share the decisions and assigned tasks with that member","Remove the member''s responsibilities without notice"],"answer":2,"explanation":""}'::jsonb,'ac30328e2b4ea4f815be96bec2fe131d','official',NULL,NULL,'Collaborative Conversations'),
('original:ela--speaking-listening--collaborative-conversations:ela--speaking-listening--collaborative-conversations--20',1,'{"question":"Which reflection best evaluates collaboration?","choices":["Rate the group by who spoke most","Focus only on whether the task was finished","List members'' personalities","Consider how listening, role-sharing, and evidence influenced the group''s result"],"answer":3,"explanation":""}'::jsonb,'492cee18a0af169092ae78f93487daf7','official',NULL,NULL,'Collaborative Conversations'),
('original:ela--writing-composition--test-style-writing-prompts:ela--writing-composition--test-style-writing-prompts--1',1,'{"question":"A prompt asks the writer to compare two sources. What should the response do?","choices":["Explain meaningful similarities and differences using evidence from both","Summarize only the first source","List opinions without referring to either source","Describe the sources'' page layouts"],"answer":0,"explanation":""}'::jsonb,'7e1f4c3952f455958da7ab5ebb636c14','official',NULL,NULL,'Test-Style Writing Prompts'),
('original:ela--writing-composition--test-style-writing-prompts:ela--writing-composition--test-style-writing-prompts--2',1,'{"question":"A prompt says ''argue whether the school should change its schedule.'' What must a strong response include?","choices":["A plot summary","A clear position supported by reasons and evidence","A list of unrelated facts","A position with no explanation"],"answer":1,"explanation":""}'::jsonb,'68d79e9663cd1e2231316cfa388d58e9','official',NULL,NULL,'Test-Style Writing Prompts'),
('original:ela--writing-composition--test-style-writing-prompts:ela--writing-composition--test-style-writing-prompts--3',1,'{"question":"A writer begins drafting before identifying what a prompt asks. What is a likely risk?","choices":["The response will automatically be more original","The prompt will become shorter","The response may address a related subject but miss the task","The evidence will be easier to find"],"answer":2,"explanation":""}'::jsonb,'cdc83c45f1f5dd4c2052da8463f95d8b','official',NULL,NULL,'Test-Style Writing Prompts'),
('original:ela--writing-composition--test-style-writing-prompts:ela--writing-composition--test-style-writing-prompts--4',1,'{"question":"A prompt asks for an explanation of how a character changes. Which evidence is most relevant?","choices":["The author''s biography only","A description of the book cover","The number of chapters","Events and choices that show the character''s development across the text"],"answer":3,"explanation":""}'::jsonb,'460ff12799092fb8b6c3708dcdfa4004','official',NULL,NULL,'Test-Style Writing Prompts'),
('original:ela--writing-composition--test-style-writing-prompts:ela--writing-composition--test-style-writing-prompts--5',1,'{"question":"What is the purpose of unpacking a writing prompt?","choices":["Identify the task, topic, audience, and required evidence or structure","Choose a title before reading it","Avoid planning","Copy the prompt into the response"],"answer":0,"explanation":""}'::jsonb,'17c1d7645735e34efb86099bbabd828a','official',NULL,NULL,'Test-Style Writing Prompts'),
('original:ela--writing-composition--test-style-writing-prompts:ela--writing-composition--test-style-writing-prompts--6',1,'{"question":"A source-based prompt requires evidence from two passages. What should the writer do?","choices":["Use one source and ignore the other","Use and explain relevant evidence from both passages","Add quotations without explaining them","Rely only on personal experience"],"answer":1,"explanation":""}'::jsonb,'6b05a113794d4db32914d4afe5e08d16','official',NULL,NULL,'Test-Style Writing Prompts'),
('original:ela--writing-composition--test-style-writing-prompts:ela--writing-composition--test-style-writing-prompts--7',1,'{"question":"A prompt asks for a narrative from a particular point of view. Which choice should guide the writer?","choices":["Switch narrators every paragraph without reason","Write an informational report instead","Keep the narrator''s perspective consistent and relevant to events","Avoid establishing a setting"],"answer":2,"explanation":""}'::jsonb,'e3e18b8222beb91e9d62eff92e4c1ab3','official',NULL,NULL,'Test-Style Writing Prompts'),
('original:ela--writing-composition--test-style-writing-prompts:ela--writing-composition--test-style-writing-prompts--8',1,'{"question":"Which thesis best answers ''Should the town invest in a public garden?''","choices":["Public gardens are interesting","This essay will discuss gardens","Some people like vegetables","The town should fund a public garden because it can expand access to fresh food and create a shared learning space"],"answer":3,"explanation":""}'::jsonb,'17b4c5e47209e8330f7745a71d4bfb18','official',NULL,NULL,'Test-Style Writing Prompts'),
('original:ela--writing-composition--test-style-writing-prompts:ela--writing-composition--test-style-writing-prompts--9',1,'{"question":"A writer''s response has strong evidence but no explanation after quotations. What is missing?","choices":["Reasoning that connects the evidence to the claim","A second title","A longer introduction","More quotations without context"],"answer":0,"explanation":""}'::jsonb,'30f081510479504ac1993778860c59cc','official',NULL,NULL,'Test-Style Writing Prompts'),
('original:ela--writing-composition--test-style-writing-prompts:ela--writing-composition--test-style-writing-prompts--10',1,'{"question":"The prompt asks for a process explanation. Which structure is most appropriate?","choices":["Arrange details by which sounds best","Present the steps in an order that helps readers follow the process","List results before defining the process","Use a character conflict"],"answer":1,"explanation":""}'::jsonb,'b0d97a40286caeed9d24731ae342b1fb','official',NULL,NULL,'Test-Style Writing Prompts'),
('original:ela--writing-composition--test-style-writing-prompts:ela--writing-composition--test-style-writing-prompts--11',1,'{"question":"What is a useful way to check that a response addresses every part of a prompt?","choices":["Count the adjectives","Check only the opening sentence","Turn each task requirement into a brief checklist and review the draft","Compare the response length to a friend''s"],"answer":2,"explanation":""}'::jsonb,'2886dbf32b6595e9d803b2a61e22be0c','official',NULL,NULL,'Test-Style Writing Prompts'),
('original:ela--writing-composition--test-style-writing-prompts:ela--writing-composition--test-style-writing-prompts--12',1,'{"question":"A prompt asks for a claim and a counterclaim. What should the writer include?","choices":["Only a list of facts","Two unrelated claims","A conclusion without an argument","A response to an opposing position as well as support for the main claim"],"answer":3,"explanation":""}'::jsonb,'8778587941cfb80627bbae36e29da4f3','official',NULL,NULL,'Test-Style Writing Prompts'),
