('original:ela--language-grammar-vocabulary--multiple-meaning-words:ela--language-grammar-vocabulary--multiple-meaning-words--20',1,'{"question":"Why can context be more reliable than a word''s first dictionary definition?","choices":["Context changes the word''s spelling","A word has only one possible meaning","Dictionary definitions never include multiple meanings","Context shows which meaning fits the sentence and situation"],"answer":3,"explanation":""}'::jsonb,'163d748a90eab935f6e0a33bb45f0e06','official',NULL,NULL,'Multiple-Meaning Words'),
('original:ela--writing-composition--narrative-writing:ela--writing-composition--narrative-writing--1',1,'{"question":"What is a narrative''s plot?","choices":["The sequence and connection of events","A list of character traits","The author''s purpose statement","A description of the setting only"],"answer":0,"explanation":""}'::jsonb,'bea2a17d0fdb2cf33569fd16296dc7ed','official',NULL,NULL,'Narrative Writing'),
('original:ela--writing-composition--narrative-writing:ela--writing-composition--narrative-writing--2',1,'{"question":"Which detail most effectively establishes a tense setting?","choices":["Mina was a student","The hallway lights flickered as a locked door clicked behind Mina","The school had three floors","It was Tuesday"],"answer":1,"explanation":""}'::jsonb,'17a8a5db6ddf697b62b4a080435b36bd','official',NULL,NULL,'Narrative Writing'),
('original:ela--writing-composition--narrative-writing:ela--writing-composition--narrative-writing--3',1,'{"question":"A story''s conflict is best described as","choices":["the lesson stated in the title","a list of places in the story","a central problem or tension that drives events","the narrator''s vocabulary"],"answer":2,"explanation":""}'::jsonb,'085c3b3c2c9e016a2c71acdf52b449d2','official',NULL,NULL,'Narrative Writing'),
('original:ela--writing-composition--narrative-writing:ela--writing-composition--narrative-writing--4',1,'{"question":"Why might a writer begin a story in the middle of an important action?","choices":["To avoid developing any characters","To explain every event before the story begins","To remove the need for a setting","To create immediate momentum and raise questions for the reader"],"answer":3,"explanation":""}'::jsonb,'83d6c3216b93a3f623d8d7fccbdc7a55','official',NULL,NULL,'Narrative Writing'),
('original:ela--writing-composition--narrative-writing:ela--writing-composition--narrative-writing--5',1,'{"question":"Which choice best reveals a character indirectly?","choices":["He folded the map twice before handing it back without speaking","He was nervous","The character''s name was Sam","The story takes place in a city"],"answer":0,"explanation":""}'::jsonb,'52d0cb6d6a687f58a5e62dab7e51aa8f','official',NULL,NULL,'Narrative Writing'),
('original:ela--writing-composition--narrative-writing:ela--writing-composition--narrative-writing--6',1,'{"question":"A narrator describes events as ''I'' and knows only their own thoughts. What point of view is this?","choices":["Second person","First person","Third-person omniscient","Third-person limited"],"answer":1,"explanation":""}'::jsonb,'9f8ca56cb90e1b74fd2e849312f07c81','official',NULL,NULL,'Narrative Writing'),
('original:ela--writing-composition--narrative-writing:ela--writing-composition--narrative-writing--7',1,'{"question":"What is a turning point in a narrative?","choices":["The first descriptive sentence","A repeated character trait","An event that changes the direction or stakes of the story","A detail unrelated to the conflict"],"answer":2,"explanation":""}'::jsonb,'73c1c39d9fd991551bc52ba71df97e12','official',NULL,NULL,'Narrative Writing'),
('original:ela--writing-composition--narrative-writing:ela--writing-composition--narrative-writing--8',1,'{"question":"A writer wants dialogue to reveal tension. Which exchange is most effective?","choices":["''Hello,'' she said. ''Hello,'' he replied.","''It is Tuesday,'' he said. ''Yes,'' she said.","''The sky is blue,'' she said. ''It is.''","''You said you locked it.'' ''I thought you did.''"],"answer":3,"explanation":""}'::jsonb,'e0f1d4febd8a64adb22d73ff04cc43ba','official',NULL,NULL,'Narrative Writing'),
('original:ela--writing-composition--narrative-writing:ela--writing-composition--narrative-writing--9',1,'{"question":"Why should a writer vary sentence length in a narrative?","choices":["Pacing and emphasis can change with the action or reflection","Every sentence must have a different subject","Long sentences are always more descriptive","Short sentences remove the need for plot"],"answer":0,"explanation":""}'::jsonb,'9be64d6f846e071ad71547b2864efa29','official',NULL,NULL,'Narrative Writing'),
('original:ela--writing-composition--narrative-writing:ela--writing-composition--narrative-writing--10',1,'{"question":"A story''s resolution should generally","choices":["introduce every character for the first time","show how the central conflict is addressed or left changed","repeat the opening without change","add a new conflict unrelated to the story"],"answer":1,"explanation":""}'::jsonb,'d49707b35d6463eba983415039bf83b3','official',NULL,NULL,'Narrative Writing'),
('original:ela--writing-composition--narrative-writing:ela--writing-composition--narrative-writing--11',1,'{"question":"A writer describes a character''s hands shaking before an audition. What does this detail most directly do?","choices":["Explain the entire plot","Establish the story''s historical period","Suggest emotion through physical behavior","Prove the narrator knows every thought"],"answer":2,"explanation":""}'::jsonb,'f1805f9ac6845185905f4dd84c0152df','official',NULL,NULL,'Narrative Writing'),
('original:ela--writing-composition--narrative-writing:ela--writing-composition--narrative-writing--12',1,'{"question":"Which transition best signals a flashback?","choices":["At the same time, the train arrived","She closed the door","The station was crowded","Two years earlier, the same station had been their meeting place"],"answer":3,"explanation":""}'::jsonb,'db47c2d6ca8452ff8b0e9475918ceeab','official',NULL,NULL,'Narrative Writing'),
('original:ela--writing-composition--narrative-writing:ela--writing-composition--narrative-writing--13',1,'{"question":"A narrative has many events but no clear focus. What should the writer do?","choices":["Select events that develop the central conflict or character change","Add more unrelated scenes","Remove the setting","Replace all actions with definitions"],"answer":0,"explanation":""}'::jsonb,'b7cc98ab6a95b0461cbf871f7c95ea76','official',NULL,NULL,'Narrative Writing'),
('original:ela--writing-composition--narrative-writing:ela--writing-composition--narrative-writing--14',1,'{"question":"What is foreshadowing?","choices":["A return to an earlier event","A clue that hints at a later event","A direct statement of the theme","A description of the setting"],"answer":1,"explanation":""}'::jsonb,'7f6aee8d0ca9279eabcfefc1e984b70f','official',NULL,NULL,'Narrative Writing'),
('original:ela--writing-composition--narrative-writing:ela--writing-composition--narrative-writing--15',1,'{"question":"A narrator says, ''I never worry,'' while nervously checking the window every minute. What can the contrast reveal?","choices":["The setting is a courtroom","The story has no conflict","The narrator''s actions may contradict their words","The narrator is omniscient"],"answer":2,"explanation":""}'::jsonb,'c34433d46bf5f45b30882a0bbda092f0','official',NULL,NULL,'Narrative Writing'),
('original:ela--writing-composition--narrative-writing:ela--writing-composition--narrative-writing--16',1,'{"question":"Which ending creates the strongest sense of character development?","choices":["The story stops in the middle of a sentence","A new character appears without context","The conflict disappears without explanation","The character makes a choice that shows a changed understanding"],"answer":3,"explanation":""}'::jsonb,'82a72f1672f1a2662e8ef92229906804','official',NULL,NULL,'Narrative Writing')
insert into public.question_content_versions(source_key,version_number,question,content_hash,source_type,creator_id,source_set_id,source_title) values
('original:ela--writing-composition--narrative-writing:ela--writing-composition--narrative-writing--17',1,'{"question":"What should a writer consider when choosing a narrative point of view?","choices":["Which perspective best serves the story''s information and effect","Which pronoun appears most often in the title","Whether the story has a dialogue line","How many pages the draft will be"],"answer":0,"explanation":""}'::jsonb,'ee65cd222afa486cb067ece83ccaf5e7','official',NULL,NULL,'Narrative Writing'),
('original:ela--writing-composition--narrative-writing:ela--writing-composition--narrative-writing--18',1,'{"question":"A scene feels rushed. Which revision is most likely to improve it?","choices":["Add a summary of unrelated events","Develop the key moment with action, sensory detail, and character response","Remove the central choice","Explain the ending before the scene"],"answer":1,"explanation":""}'::jsonb,'8efd5cae9604f6a1795f3a185ecd51db','official',NULL,NULL,'Narrative Writing'),
('original:ela--writing-composition--narrative-writing:ela--writing-composition--narrative-writing--19',1,'{"question":"Why is a specific detail usually more effective than a general one?","choices":["It guarantees the story is true","It eliminates the need for sequence","It helps the reader imagine the scene and infer meaning","It makes every character identical"],"answer":2,"explanation":""}'::jsonb,'3df00599eee7683458588a2c2aca7355','official',NULL,NULL,'Narrative Writing'),
('original:ela--writing-composition--narrative-writing:ela--writing-composition--narrative-writing--20',1,'{"question":"A writer wants the climax to feel earned. What should earlier scenes do?","choices":["Hide all relevant information until after the ending","Include only background description","Avoid introducing the central conflict","Develop causes, stakes, and choices that lead toward it"],"answer":3,"explanation":""}'::jsonb,'29802a74c020d4cc159c26326970aec6','official',NULL,NULL,'Narrative Writing'),
('original:ela--writing-composition--informational-explanatory-writing:ela--writing-composition--informational-explanatory-writing--1',1,'{"question":"What is the main goal of informational writing?","choices":["Explain a topic clearly using accurate information","Convince readers through unsupported opinion","Tell a fictional story","Entertain without a central focus"],"answer":0,"explanation":""}'::jsonb,'6c8f5610755342d1b2b128d1ec87ce29','official',NULL,NULL,'Informational & Explanatory Writing'),
('original:ela--writing-composition--informational-explanatory-writing:ela--writing-composition--informational-explanatory-writing--2',1,'{"question":"Which thesis best fits an explanation of how urban trees reduce heat?","choices":["Trees are wonderful","Urban trees cool neighborhoods by providing shade and releasing water vapor","This report is about cities","Some streets have trees"],"answer":1,"explanation":""}'::jsonb,'5a0f7c8fc5c6ed0b81300d4bd0045af1','official',NULL,NULL,'Informational & Explanatory Writing'),
('original:ela--writing-composition--informational-explanatory-writing:ela--writing-composition--informational-explanatory-writing--3',1,'{"question":"A paragraph explains how a volcano forms. Which structure is most appropriate?","choices":["A dialogue between fictional characters","A list of preferences","A sequence of processes and cause-and-effect relationships","A debate with no evidence"],"answer":2,"explanation":""}'::jsonb,'2c586d4c73e7be7dfd1db4ed2bb91506','official',NULL,NULL,'Informational & Explanatory Writing'),
('original:ela--writing-composition--informational-explanatory-writing:ela--writing-composition--informational-explanatory-writing--4',1,'{"question":"Why should technical terms be defined for a general audience?","choices":["Definitions make evidence unnecessary","Every reader already knows technical vocabulary","Terms should replace examples","Readers need enough context to understand the explanation"],"answer":3,"explanation":""}'::jsonb,'1655b076696aa7dd833e9daa3d6fb3e7','official',NULL,NULL,'Informational & Explanatory Writing'),
('original:ela--writing-composition--informational-explanatory-writing:ela--writing-composition--informational-explanatory-writing--5',1,'{"question":"Which evidence best supports an explanation of a local recycling program''s results?","choices":["Documented participation and material recovery data","A slogan from the program poster","One person''s unrelated opinion","A photograph with no date or context"],"answer":0,"explanation":""}'::jsonb,'24ba5e9eb0a20f02a168ddc2926fdcd0','official',NULL,NULL,'Informational & Explanatory Writing'),
('original:ela--writing-composition--informational-explanatory-writing:ela--writing-composition--informational-explanatory-writing--6',1,'{"question":"A draft includes facts but no transitions between sections. What would help?","choices":["Remove the headings","Add language that shows how the ideas connect","Add unrelated quotations","Repeat the title after each sentence"],"answer":1,"explanation":""}'::jsonb,'cd291132c58483b3647899d5a45c6f28','official',NULL,NULL,'Informational & Explanatory Writing'),
('original:ela--writing-composition--informational-explanatory-writing:ela--writing-composition--informational-explanatory-writing--7',1,'{"question":"A writer is explaining a complex process. What can a labeled diagram contribute?","choices":["Proof that the process always works","A replacement for all explanations","A visual representation of parts or steps that supports the text","An unrelated opinion"],"answer":2,"explanation":""}'::jsonb,'720640f97deceb982de02486bf2ca44a','official',NULL,NULL,'Informational & Explanatory Writing'),
('original:ela--writing-composition--informational-explanatory-writing:ela--writing-composition--informational-explanatory-writing--8',1,'{"question":"Which choice best distinguishes an example from a definition?","choices":["An example is always a quotation","A definition must include a statistic","They have the same purpose","An example illustrates a concept; a definition states what it means"],"answer":3,"explanation":""}'::jsonb,'3344f0559a10f1e5eb5148384813059f','official',NULL,NULL,'Informational & Explanatory Writing'),
('original:ela--writing-composition--informational-explanatory-writing:ela--writing-composition--informational-explanatory-writing--9',1,'{"question":"A report says a new policy ''caused'' attendance to rise but only compares two years. What should be improved?","choices":["Consider other factors and avoid claiming causation without adequate evidence","Remove all dates","Change the topic","Add a stronger adjective"],"answer":0,"explanation":""}'::jsonb,'9f5a0585eaf69b17ff9ef6e20f5ef030','official',NULL,NULL,'Informational & Explanatory Writing'),
('original:ela--writing-composition--informational-explanatory-writing:ela--writing-composition--informational-explanatory-writing--10',1,'{"question":"How can a writer avoid overwhelming readers with facts?","choices":["Include every fact found","Select details that directly explain the main idea and organize them clearly","Remove the main idea","Put evidence in random order"],"answer":1,"explanation":""}'::jsonb,'0252ebd5f88dba12638b4276b9e9b9ca','official',NULL,NULL,'Informational & Explanatory Writing'),
('original:ela--writing-composition--informational-explanatory-writing:ela--writing-composition--informational-explanatory-writing--11',1,'{"question":"Which paragraph order best explains how a water filter works?","choices":["List parts alphabetically with no explanation","Give the conclusion before naming the process","Describe the parts, then trace water through each stage","Mix steps and unrelated facts"],"answer":2,"explanation":""}'::jsonb,'930e4c3273e3b0d1913c4dfd02f316fe','official',NULL,NULL,'Informational & Explanatory Writing'),
('original:ela--writing-composition--informational-explanatory-writing:ela--writing-composition--informational-explanatory-writing--12',1,'{"question":"What is paraphrasing in informational writing?","choices":["Changing a few words and omitting attribution","Copying a source exactly","Writing an unsupported opinion","Restating source information in new wording while preserving its meaning and crediting it"],"answer":3,"explanation":""}'::jsonb,'e288d6a7ac3f8c36822bed1c3aa7f7db','official',NULL,NULL,'Informational & Explanatory Writing'),
('original:ela--writing-composition--informational-explanatory-writing:ela--writing-composition--informational-explanatory-writing--13',1,'{"question":"A writer compares two energy sources. What should guide the comparison?","choices":["Consistent criteria such as cost, reliability, and environmental impact","Different criteria chosen for each source","Only the writer''s favorite source","The length of each source''s name"],"answer":0,"explanation":""}'::jsonb,'32c76ca4f247152d172c4d6542518097','official',NULL,NULL,'Informational & Explanatory Writing'),
('original:ela--writing-composition--informational-explanatory-writing:ela--writing-composition--informational-explanatory-writing--14',1,'{"question":"Which detail is most relevant in a section about a city''s water use?","choices":["A famous river in another continent","Household and industrial water-use data for that city","The author''s favorite drink","The history of a local sports team"],"answer":1,"explanation":""}'::jsonb,'9687864698213ade63ee31b5336408ac','official',NULL,NULL,'Informational & Explanatory Writing'),
('original:ela--writing-composition--informational-explanatory-writing:ela--writing-composition--informational-explanatory-writing--15',1,'{"question":"Why should an explanatory conclusion synthesize rather than introduce a new topic?","choices":["A new topic makes the evidence stronger","A conclusion should not connect to the main idea","It helps readers understand the significance of the explanation they just read","Synthesis removes all details"],"answer":2,"explanation":""}'::jsonb,'34676ba2ef055a01d09887ba1b07bb8c','official',NULL,NULL,'Informational & Explanatory Writing'),
('original:ela--writing-composition--informational-explanatory-writing:ela--writing-composition--informational-explanatory-writing--16',1,'{"question":"A writer uses a chart from a source. What must the writer do?","choices":["Remove its labels","Present it as the writer''s own data","Assume the chart needs no context","Identify the source and explain what the chart shows"],"answer":3,"explanation":""}'::jsonb,'73d522b44934c695912f030ff131a558','official',NULL,NULL,'Informational & Explanatory Writing'),
('original:ela--writing-composition--informational-explanatory-writing:ela--writing-composition--informational-explanatory-writing--17',1,'{"question":"Which sentence is the most objective?","choices":["The survey included 240 students from four grade levels","The survey was amazing","The results are obviously perfect","Everyone loved the survey"],"answer":0,"explanation":""}'::jsonb,'6532f74226a9cad6f237f060b6485860','official',NULL,NULL,'Informational & Explanatory Writing'),
('original:ela--writing-composition--informational-explanatory-writing:ela--writing-composition--informational-explanatory-writing--18',1,'{"question":"A section contains five paragraphs on separate subtopics. What can improve navigation?","choices":["Remove all paragraph breaks","Use clear headings that reflect each subtopic","Repeat the same heading everywhere","Put the conclusion in the middle"],"answer":1,"explanation":""}'::jsonb,'98f1d283dd1bf40baa2ef2f70f9eb8d7','official',NULL,NULL,'Informational & Explanatory Writing'),
('original:ela--writing-composition--informational-explanatory-writing:ela--writing-composition--informational-explanatory-writing--19',1,'{"question":"A writer finds a reliable source, but it is ten years old. What should the writer ask?","choices":["Whether old sources are always false","Whether the source has enough pages","Whether the information may have changed and needs a current source","Whether the title is interesting"],"answer":2,"explanation":""}'::jsonb,'84d0be91ca874070c01b8d92e401ca2c','official',NULL,NULL,'Informational & Explanatory Writing'),
('original:ela--writing-composition--informational-explanatory-writing:ela--writing-composition--informational-explanatory-writing--20',1,'{"question":"Which revision best improves clarity?","choices":["Add more passive sentences","Remove key terms","Combine unrelated ideas into one sentence","Replace vague pronouns with the specific people or things they refer to"],"answer":3,"explanation":""}'::jsonb,'dd27e1f777acd694a2413f780c5c979b','official',NULL,NULL,'Informational & Explanatory Writing'),
('original:ela--writing-composition--introductions-conclusions:ela--writing-composition--introductions-conclusions--1',1,'{"question":"What should an effective introduction usually establish?","choices":["The topic and direction of the response","Every supporting detail","A new argument unrelated to the thesis","The final evidence only"],"answer":0,"explanation":""}'::jsonb,'2818ca5baae76655ec79e90984e0726b','official',NULL,NULL,'Introductions & Conclusions'),
('original:ela--writing-composition--introductions-conclusions:ela--writing-composition--introductions-conclusions--2',1,'{"question":"Which opening best introduces an essay about reducing food waste?","choices":["Food is a noun","Each year, usable food is discarded while many households face limited access to meals","I am going to write an essay","There are many things in the world"],"answer":1,"explanation":""}'::jsonb,'188cbffc17ef354398247cb436c3f472','official',NULL,NULL,'Introductions & Conclusions'),
('original:ela--writing-composition--introductions-conclusions:ela--writing-composition--introductions-conclusions--3',1,'{"question":"What is a thesis statement''s main job?","choices":["List every source title","Repeat the assignment","State the central claim or focus of the writing","Provide a decorative opening"],"answer":2,"explanation":""}'::jsonb,'aead9c136cf39e384d6b4339857eadca','official',NULL,NULL,'Introductions & Conclusions'),
('original:ela--writing-composition--introductions-conclusions:ela--writing-composition--introductions-conclusions--4',1,'{"question":"Why might a writer use a brief anecdote in an introduction?","choices":["To replace the thesis","To avoid explaining the topic","To introduce an unrelated character","To provide a relevant example that draws readers into the topic"],"answer":3,"explanation":""}'::jsonb,'27c6652bffa3c1061f950be6d2100c13','official',NULL,NULL,'Introductions & Conclusions'),
('original:ela--writing-composition--introductions-conclusions:ela--writing-composition--introductions-conclusions--5',1,'{"question":"A conclusion repeats the thesis word for word and stops. What could improve it?","choices":["Restate the idea in light of the evidence and show its significance","Add an unsupported claim","Start a new body paragraph","Remove the central idea"],"answer":0,"explanation":""}'::jsonb,'fb6cceb2ea91e845b4e2646f6e164158','official',NULL,NULL,'Introductions & Conclusions'),
('original:ela--writing-composition--introductions-conclusions:ela--writing-composition--introductions-conclusions--6',1,'{"question":"Which conclusion best fits an explanatory essay about pollinators?","choices":["Pollinators are insects","Understanding pollinator needs helps communities make habitat choices that support food systems","This essay is now over","The next topic is the history of trains"],"answer":1,"explanation":""}'::jsonb,'c20eaa3521d67fc4e3da41145469b16b','official',NULL,NULL,'Introductions & Conclusions'),
('original:ela--writing-composition--introductions-conclusions:ela--writing-composition--introductions-conclusions--7',1,'{"question":"What is a hook''s purpose when used well?","choices":["Make any claim seem true","Replace evidence","Engage attention while connecting naturally to the topic","Distract readers from the thesis"],"answer":2,"explanation":""}'::jsonb,'01411e06e22aef823cdeda13c2a5b345','official',NULL,NULL,'Introductions & Conclusions'),
('original:ela--writing-composition--introductions-conclusions:ela--writing-composition--introductions-conclusions--8',1,'{"question":"A writer begins with a dictionary definition that everyone already knows. What is a stronger alternative?","choices":["Repeat the definition three times","Add an unrelated joke","Skip directly to the bibliography","Open with a relevant problem, observation, or question"],"answer":3,"explanation":""}'::jsonb,'b18323767eb5fe63e7ed6a6b196417d7','official',NULL,NULL,'Introductions & Conclusions'),
('original:ela--writing-composition--introductions-conclusions:ela--writing-composition--introductions-conclusions--9',1,'{"question":"What should an introduction avoid?","choices":["Making a claim the body of the writing cannot support","Naming the topic","Providing needed context","Previewing the central direction"],"answer":0,"explanation":""}'::jsonb,'3b60e874c55c0284314da432fb98c484','official',NULL,NULL,'Introductions & Conclusions'),
('original:ela--writing-composition--introductions-conclusions:ela--writing-composition--introductions-conclusions--10',1,'{"question":"A conclusion introduces a new statistic that changes the argument. What is the best revision?","choices":["Leave it without context","Move and explain the evidence in the body, or remove it if it is not needed","Make it the title","Delete the thesis"],"answer":1,"explanation":""}'::jsonb,'a8ad86656adb129033cd9e317ad90599','official',NULL,NULL,'Introductions & Conclusions'),
('original:ela--writing-composition--introductions-conclusions:ela--writing-composition--introductions-conclusions--11',1,'{"question":"In a short response, what is often the most effective introduction?","choices":["A long personal story unrelated to the question","A list of dictionary entries","A direct opening that answers the prompt and states the focus","A conclusion before the claim"],"answer":2,"explanation":""}'::jsonb,'5f2683f30b0a7f9a9c3d9d90a2e8d188','official',NULL,NULL,'Introductions & Conclusions'),
('original:ela--writing-composition--introductions-conclusions:ela--writing-composition--introductions-conclusions--12',1,'{"question":"Why should a writer consider the audience when choosing an opening?","choices":["Audience determines whether evidence matters","Every audience prefers the same anecdote","The opening must include every detail","Different audiences may need different context or levels of explanation"],"answer":3,"explanation":""}'::jsonb,'a459b2098b7f6eefaafb10634e37ea63','official',NULL,NULL,'Introductions & Conclusions'),
('original:ela--writing-composition--introductions-conclusions:ela--writing-composition--introductions-conclusions--13',1,'{"question":"Which thesis is most focused?","choices":["Community gardens can improve access to produce and create outdoor learning spaces","Gardens are good and many things happen","There are many ways to spend time","This essay is about everything in the neighborhood"],"answer":0,"explanation":""}'::jsonb,'b261210ba310356c57beb833b3c35bcb','official',NULL,NULL,'Introductions & Conclusions'),
('original:ela--writing-composition--introductions-conclusions:ela--writing-composition--introductions-conclusions--14',1,'{"question":"A writer wants a conclusion to call readers to action. What should the action do?","choices":["Introduce an unrelated demand","Follow logically from the argument and be realistic for the audience","Replace all evidence","Contradict the thesis"],"answer":1,"explanation":""}'::jsonb,'e6fc3bb6a1025f1afb552d182b5a0176','official',NULL,NULL,'Introductions & Conclusions'),
('original:ela--writing-composition--introductions-conclusions:ela--writing-composition--introductions-conclusions--15',1,'{"question":"What does background context in an introduction help readers do?","choices":["Skip the body paragraphs","Know the author''s entire life story","Understand information needed to follow the central claim","Assume the claim is proven"],"answer":2,"explanation":""}'::jsonb,'63d2fa0dfa0f2f0a6cddf534dfa897bc','official',NULL,NULL,'Introductions & Conclusions'),
