('original:ela--writing-composition--introductions-conclusions:ela--writing-composition--introductions-conclusions--18',1,'{"question":"What is a useful final check for an introduction?","choices":["Count how many adjectives it contains","Confirm it leads readers toward the response''s actual focus","Make sure it states the conclusion''s final sentence","Check whether every paragraph is summarized"],"answer":1,"explanation":""}'::jsonb,'9e927d9e39ef11c6a41eb1e39d586d45','official',NULL,NULL,'Introductions & Conclusions'),
