('original:ela--writing-composition--introductions-conclusions:ela--writing-composition--introductions-conclusions--20',1,'{"question":"Why should an introduction and conclusion feel connected?","choices":["They must use identical wording","They replace the body","They determine the source''s reliability","Their relationship can frame the writing''s development and sense of purpose"],"answer":3,"explanation":""}'::jsonb,'44a0edf7900922166eac8d291b99b499','official',NULL,NULL,'Introductions & Conclusions'),
